    def _fallback_creative_decision(
        self,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any],
    ) -> dict[str, Any]:
        planning_hints = dict(request.layout_decision or {})
        template_candidates = request.template_candidates or []
        hinted_mode = str(planning_hints.get("mode") or compiled_context.get("template_fit_brief", {}).get("mode") or "synthesized_layout")
        selected_template_id = str(planning_hints.get("template_id") or "").strip() or None
        reasoning = list(planning_hints.get("rationale") or planning_hints.get("reasoning") or [])
        if not reasoning:
            reasoning = ["Generated from backend planning hints while AI creative planning is unavailable."]
        return {
            "layout_mode": hinted_mode,
            "selected_template_id": selected_template_id,
            "confidence": float(planning_hints.get("confidence") or 0.58),
            "reasoning": reasoning,
            "adaptations": dict(planning_hints.get("adaptation_plan") or planning_hints.get("adaptations") or {}),
            "asset_strategy": dict(planning_hints.get("asset_strategy") or {}),
            "template_candidates": template_candidates[:6],
            "planning_hints": planning_hints,
        }

    @staticmethod
    def _normalize_template_lookup_key(value: object) -> str:
        text = str(value or "").strip()
        if not text:
            return ""
        text = re.sub(r"^[a-z]+://", "", text.casefold())
        text = text.rsplit("/", 1)[-1]
        text = text.rsplit("\\", 1)[-1]
        text = text.split("?", 1)[0]
        text = text.rsplit(".", 1)[0]
        text = re.sub(r"-[0-9a-f]{8,}$", "", text)
        text = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
        return text

    @classmethod
    def _sequence_reference_signature(cls, value: object) -> tuple[str, int] | None:
        normalized = cls._normalize_template_lookup_key(value)
        if not normalized:
            return None
        match = re.match(r"^(?P<prefix>.+?)-(?P<index>\d{1,3})$", normalized)
        if not match:
            return None
        prefix = str(match.group("prefix") or "").strip("-")
        index = int(match.group("index") or 0)
        if not prefix or index <= 0:
            return None
        return prefix, index

    @classmethod
    def _storage_reference_candidates(cls, value: object) -> list[str]:
        raw = str(value or "").strip()
        if not raw:
            return []
        candidates: list[str] = [raw]
        try:
            parsed = urlparse(raw)
            query = parse_qs(parsed.query or "")
        except Exception:  # pragma: no cover - defensive parsing fallback
            query = {}
        for key in ("storage_path", "filename"):
            for item in query.get(key) or []:
                text = str(item or "").strip()
                if text:
                    candidates.append(text)
        for token in query.get("token") or []:
            token_payload = str(token or "").split(".", 1)[0].strip()
            if not token_payload:
                continue
            try:
                padding = "=" * (-len(token_payload) % 4)
                decoded = base64.urlsafe_b64decode(f"{token_payload}{padding}")
                payload = json.loads(decoded.decode("utf-8"))
            except Exception:  # pragma: no cover - corrupt or unexpected token
                continue
            if not isinstance(payload, dict):
                continue
            for key in ("storage_path", "filename"):
                text = str(payload.get(key) or "").strip()
                if text:
                    candidates.append(text)
        deduped: list[str] = []
        seen: set[str] = set()
        for candidate in candidates:
            key = candidate.casefold()
            if key in seen:
                continue
            seen.add(key)
            deduped.append(candidate)
        return deduped

    @classmethod
    def _effective_template_surface_policy(
        cls,
        request: AIOrchestrationRequest | None = None,
        *,
        creative_decision: CreativeDecisionPayload | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> str:
        candidate_values: list[Any] = []
        if creative_decision and isinstance(getattr(creative_decision, "asset_strategy", None), dict):
            candidate_values.append((creative_decision.asset_strategy or {}).get("template_surface_policy"))
        if isinstance(metadata, dict):
            candidate_values.append(metadata.get("template_surface_policy"))
            metadata_asset_strategy = (
                metadata.get("asset_strategy")
                if isinstance(metadata.get("asset_strategy"), dict)
                else {}
            )
            candidate_values.append(metadata_asset_strategy.get("template_surface_policy"))
            validation_hints = metadata.get("validation_hints") if isinstance(metadata.get("validation_hints"), dict) else {}
            candidate_values.append(validation_hints.get("template_surface_policy"))
        if request is not None:
            template_context = getattr(request, "template_context", {})
            template_context = template_context if isinstance(template_context, dict) else {}
            direct_sequence_pack = template_context.get("sequence_pack") if isinstance(template_context.get("sequence_pack"), dict) else {}
            if isinstance(direct_sequence_pack, dict):
                candidate_values.append(direct_sequence_pack.get("surface_policy"))
            sequence_pack = (
                cls._template_sequence_pack(request, creative_decision=creative_decision)
                if template_context or isinstance(request, AIOrchestrationRequest)
                else {}
            )
            if isinstance(sequence_pack, dict):
                candidate_values.append(sequence_pack.get("surface_policy"))
        for candidate in candidate_values:
            normalized = str(candidate or "").strip().lower()
            if normalized:
                return normalized
        return ""

    @classmethod
    def _resolve_template_candidate_identifier(
        cls,
        template_reference: str | None,
        *,
        template_name: str | None = None,
        template_candidates: list[dict[str, Any]] | None = None,
    ) -> str | None:
        raw_reference = str(template_reference or "").strip()
        if raw_reference and re.fullmatch(r"[0-9a-fA-F-]{36}", raw_reference):
            return raw_reference
        normalized_targets = {
            cls._normalize_template_lookup_key(template_reference),
            cls._normalize_template_lookup_key(template_name),
        }
        if raw_reference:
            normalized_targets.add(cls._normalize_template_lookup_key(raw_reference))
        normalized_targets.discard("")
        for candidate in template_candidates or []:
            if not isinstance(candidate, dict):
                continue
            candidate_id = str(candidate.get("template_id") or "").strip()
            candidate_name = str(candidate.get("name") or "").strip()
            if not candidate_id:
                continue
            if cls._normalize_template_lookup_key(candidate_id) in normalized_targets:
                return candidate_id
            if cls._normalize_template_lookup_key(candidate_name) in normalized_targets:
                return candidate_id
        return raw_reference or None

    @classmethod
    def _template_sequence_pack(
        cls,
        request: AIOrchestrationRequest,
        creative_decision: CreativeDecisionPayload | None = None,
    ) -> dict[str, Any] | None:
        template_context = request.template_context if isinstance(request.template_context, dict) else {}
        pack = template_context.get("sequence_pack")
        if not isinstance(pack, dict):
            return None
        slides = pack.get("slides")
        if not isinstance(slides, list) or not slides:
            return None
        normalized_slides = [dict(item) for item in slides if isinstance(item, dict)]
        if not normalized_slides:
            return None
        normalized_slides.sort(key=lambda item: int(item.get("slide_index") or 0))
        normalized_pack = {
            **pack,
            "slide_count": max(int(pack.get("slide_count") or len(normalized_slides)), len(normalized_slides)),
            "slides": normalized_slides,
        }
        surface_policy = str(normalized_pack.get("surface_policy") or "").strip().lower()
        selected_template_authority = cls._sequence_pack_matches_active_template(
            request,
            normalized_pack,
            creative_decision=creative_decision,
        )
        if (
            surface_policy != "lock_template_surface"
            and not selected_template_authority
            and not cls._sequence_pack_is_semantically_relevant(
            request,
            normalized_pack,
            )
        ):
            return None
        return normalized_pack

    @classmethod
    def _sequence_pack_matches_active_template(
        cls,
        request: AIOrchestrationRequest | None,
        sequence_pack: dict[str, Any] | None,
        *,
        creative_decision: CreativeDecisionPayload | None = None,
    ) -> bool:
        if not isinstance(sequence_pack, dict):
            return False
        layout_decision = request.layout_decision if request is not None and isinstance(request.layout_decision, dict) else {}
        active_template_ids = {
            str(value or "").strip()
            for value in (
                getattr(creative_decision, "selected_template_id", None),
                layout_decision.get("template_id"),
                layout_decision.get("selected_template_id"),
                layout_decision.get("primary_adaptation_template_id"),
            )
            if str(value or "").strip()
        }
        pack_template_id = str(sequence_pack.get("selected_template_id") or "").strip()
        if pack_template_id and pack_template_id in active_template_ids:
            return True
        active_template_names = {
            cls._normalize_template_lookup_key(value)
            for value in (
                layout_decision.get("template_name"),
                layout_decision.get("selected_template_name"),
                layout_decision.get("primary_adaptation_template_name"),
                sequence_pack.get("selected_template_name"),
            )
            if cls._normalize_template_lookup_key(value)
        }
        pack_template_name = cls._normalize_template_lookup_key(sequence_pack.get("selected_template_name"))
        if pack_template_name and pack_template_name in active_template_names:
            return True
        return False

    @staticmethod
    def _explicit_requested_slide_count(request: AIOrchestrationRequest | None) -> int | None:
        if request is None:
            return None
        prompt = str(getattr(request, "prompt", "") or "")
        match = re.search(r"\b(\d{1,2})\s*(?:-| )?slides?\b", prompt, re.IGNORECASE)
        if not match:
            match = re.search(r"\bslides?\s*:\s*(\d{1,2})\b", prompt, re.IGNORECASE)
        if not match:
            return None
        try:
            value = int(match.group(1))
        except (TypeError, ValueError):
            return None
        return value if 1 < value <= 20 else None

