    @classmethod
    def _repair_common_mojibake(cls, value: str) -> str:
        text = value or ""
        if not any(token in text for token in ("Ã", "Â", "â€", "â€™", "â€œ", "â€”", "â€“", "â€¢")):
            return text
        try:
            repaired = text.encode("latin-1").decode("utf-8")
        except (UnicodeEncodeError, UnicodeDecodeError):
            return text
        return repaired or text

    @classmethod
    def _sanitize_text_for_canvas(cls, value: str) -> str:
        text = cls._repair_common_mojibake(value or "")
        text = cls.MOJIBAKE_SYMBOL_PATTERN.sub(" ", text)
        text = cls.DISALLOWED_GLYPH_PATTERN.sub(" ", text)
        return " ".join(text.split()).strip()

    @classmethod
    def _normalized_prompt_tokens(cls, value: str) -> list[str]:
        cleaned = re.sub(r"[^a-z0-9\s]+", " ", (value or "").lower())
        return [
            token
            for token in cleaned.split()
            if token and token not in cls.PROMPT_ECHO_STOPWORDS
        ]

    @classmethod
    def _looks_like_prompt_echo(cls, value: Any, prompt: str) -> bool:
        candidate = cls._coerce_text_value(value)
        if not candidate:
            return False
        prompt_text = cls._coerce_text_value(prompt)
        if not prompt_text:
            return False
        lowered_candidate = candidate.lower().strip()
        if lowered_candidate.startswith(("create ", "make ", "design ", "generate ", "write ", "craft ")):
            return True
        candidate_tokens = cls._normalized_prompt_tokens(candidate)
        prompt_tokens = cls._normalized_prompt_tokens(prompt_text)
        if not candidate_tokens or not prompt_tokens:
            return False
        overlap_tokens = set(candidate_tokens) & set(prompt_tokens)
        overlap = len(overlap_tokens)
        prompt_instruction_markers = (
            "instagram post",
            "social media post",
            "create a",
            "make a",
            "design a",
            "generate a",
            "write a",
            "craft a",
            "cta for this post",
        )
        generic_fallback_starts = (
            "practical guidance for ",
            "smart strategies for ",
        )
        if lowered_candidate.startswith(generic_fallback_starts):
            return True
        audience_facing_starts = (
            "tips for ",
            "how to ",
            "ways to ",
            "why ",
            "want to ",
        )
        if lowered_candidate.startswith(audience_facing_starts) and not any(
            marker in lowered_candidate for marker in prompt_instruction_markers
        ):
            return False
        if not any(marker in lowered_candidate for marker in prompt_instruction_markers) and overlap <= 2:
            return False
        candidate_phrase = " ".join(candidate_tokens)
        prompt_phrase = " ".join(prompt_tokens)
        if candidate_phrase and (candidate_phrase in prompt_phrase or prompt_phrase in candidate_phrase):
            return True
        baseline = max(1, min(len(candidate_tokens), len(prompt_tokens)))
        return overlap >= 3 and (overlap / baseline) >= 0.8

    @classmethod
    def _has_mistake_carousel_signals(cls, *values: Any) -> bool:
        combined = " ".join(
            cls._normalize_metadata_text(value, limit=240)
            for value in values
            if cls._normalize_metadata_text(value, limit=240)
        )
        return bool(cls.MISTAKE_CAROUSEL_SIGNAL_PATTERN.search(combined))

    @classmethod
    def _prefers_multiple_mistake_slides(cls, *values: Any) -> bool:
        combined = " ".join(
            cls._normalize_metadata_text(value, limit=240)
            for value in values
            if cls._normalize_metadata_text(value, limit=240)
        )
        return bool(cls.MULTI_MISTAKE_SIGNAL_PATTERN.search(combined))

    @classmethod
    def _is_generic_carousel_education_label(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=120).casefold()
        if not text:
            return False
        return (
            text in {
                "education",
                "investment education",
                "investor education",
                "financial education",
                "financial literacy",
                "tips",
                "key insight",
                "key point",
                "insight",
                "why this matters now",
                "what actually changed",
                "why it matters beyond the headline",
                "what to do with this insight",
                "the takeaway",
                "final takeaway",
            }
            or text.endswith(" education")
            or text.startswith("key insight")
            or text.startswith("key point")
        )

    @classmethod
    def _content_topic_tokens(cls, request: AIOrchestrationRequest | None) -> set[str]:
        tokens = cls._request_topic_tokens(request)
        return {
            token
            for token in tokens
            if len(token) >= 4 and token not in cls.TOPIC_MATCH_NOISE_TOKENS
        }

    @classmethod
    def _headline_lacks_topic_specificity(
        cls,
        headline: Any,
        *,
        request: AIOrchestrationRequest | None,
    ) -> bool:
        text = cls._normalize_metadata_text(headline, limit=140)
        if not text:
            return True
        lowered = text.casefold()
        generic_patterns = (
            "why this matters",
            "what changed",
            "what actually changed",
            "why it matters",
            "beyond the headline",
            "what to do with this insight",
            "key insight",
            "key point",
            "the takeaway",
        )
        if not any(pattern in lowered for pattern in generic_patterns):
            return False
        topic_tokens = cls._content_topic_tokens(request)
        if not topic_tokens:
            return True
        headline_tokens = set(cls._normalized_prompt_tokens(text))
        return not bool(headline_tokens & topic_tokens)

    @staticmethod
    def _canonicalize_number_words_in_exact_claim_marker(value: str) -> str:
        units = {
            "zero": 0,
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
            "seven": 7,
            "eight": 8,
            "nine": 9,
            "ten": 10,
            "eleven": 11,
            "twelve": 12,
            "thirteen": 13,
            "fourteen": 14,
            "fifteen": 15,
            "sixteen": 16,
            "seventeen": 17,
            "eighteen": 18,
            "nineteen": 19,
        }
        tens = {
            "twenty": 20,
            "thirty": 30,
            "forty": 40,
            "fifty": 50,
            "sixty": 60,
            "seventy": 70,
            "eighty": 80,
            "ninety": 90,
        }
        number_words = "|".join([*units.keys(), *tens.keys()])
        unit_words = "|".join(units.keys())

        def replace(match: re.Match[str]) -> str:
            first = match.group("first")
            second = match.group("second")
            suffix = match.group("suffix")
            number = tens.get(first, units.get(first, 0))
            if second:
                number += units.get(second, 0)
            return f"{number} {suffix}"

        return re.sub(
            rf"\b(?P<first>{number_words})(?:[\s-]+(?P<second>{unit_words}))?\s+(?P<suffix>billion|million|crore|lakh|trillion|tariff lines|years|skilled professionals|occupations)\b",
            replace,
            value,
            flags=re.IGNORECASE,
        )

    @staticmethod
    def _canonical_exact_claim_marker(value: Any) -> str:
        marker = " ".join(str(value or "").casefold().replace("us$", "usd ").split())
        marker = marker.replace("nz$", "nzd ")
        marker = marker.replace("$", "usd ")
        marker = marker.replace("₹", "inr ")
        marker = marker.replace("â‚¹", "inr ")
        marker = re.sub(r"\brs\.?\s*", "inr ", marker)
        marker = re.sub(r"\b(usd|nzd|inr)\s*(\d+(?:\.\d+)?)\s*b\b", r"\1 \2 billion", marker)
        marker = re.sub(r"\b(usd|nzd|inr)\s*(\d+(?:\.\d+)?)\s*m\b", r"\1 \2 million", marker)
        marker = re.sub(r"\b(\d+(?:\.\d+)?)\s*b\b", r"\1 billion", marker)
        marker = re.sub(r"\b(\d+(?:\.\d+)?)\s*m\b", r"\1 million", marker)
        marker = AIOrchestratorService._canonicalize_number_words_in_exact_claim_marker(marker)
        return re.sub(r"\s+", " ", marker).strip()

    @staticmethod
    def _exact_claim_marker_aliases(marker: str) -> set[str]:
        normalized = " ".join(str(marker or "").split())
        if not normalized:
            return set()
        aliases = {normalized}
        currencyless = re.sub(r"^(?:usd|nzd|inr)\s+", "", normalized).strip()
        if currencyless:
            aliases.add(currencyless)
        return aliases

    @classmethod
    def _exact_claim_markers(cls, value: Any) -> set[str]:
        text = AIOrchestratorService._coerce_text_value(value)
        if not text:
            return set()
        markers: set[str] = set()
        patterns = (
            r"\b\d{1,2}\s+(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+\d{4}\b",
            r"\b(?:19|20)\d{2}\b",
            r"\b\d+(?:\.\d+)?\s?%",
            r"\b(?:top|rank(?:ed)?|#)\s?\d+\b",
            r"\bus\$\s?\d+(?:\.\d+)?(?:\s?(?:billion|million|crore|lakh|trillion))?\b",
            r"\b(?:usd|nzd|nz\$|inr|rs\.?|â‚¹|\$)\s?\d+(?:\.\d+)?\s?[bm]\b",
            r"\b\d+(?:\.\d+)?\s?[bm]\b",
            r"\b(?:usd|inr|rs\.?|₹|\$)\s?\d+(?:\.\d+)?(?:\s?(?:billion|million|crore|lakh|trillion))?\b",
            r"\b\d+(?:\.\d+)?\s?(?:billion|million|crore|lakh|trillion|tariff lines|years|skilled professionals|occupations)\b",
            r"\b(?:one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)(?:[\s-]+(?:one|two|three|four|five|six|seven|eight|nine))?\s?(?:billion|million|crore|lakh|trillion|tariff lines|years|skilled professionals|occupations)\b",
        )
        for pattern in patterns:
            for match in re.findall(pattern, text, flags=re.IGNORECASE):
                marker = cls._canonical_exact_claim_marker(match)
                if marker:
                    markers.add(marker)
        return markers

    @classmethod
    def _supported_exact_claim_markers(
        cls,
        *,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any] | None,
    ) -> set[str]:
        source_texts: list[Any] = [request.prompt]
        for source in (
            request.research_editorial_brief,
            request.live_research,
            (compiled_context or {}).get("research_editorial_brief"),
            (compiled_context or {}).get("live_research"),
        ):
            if not isinstance(source, dict):
                continue
            fact_model = source.get("fact_model") if isinstance(source.get("fact_model"), dict) else source
            for fact in fact_model.get("verified_facts") or []:
                if isinstance(fact, dict):
                    source_texts.extend([fact.get("label"), fact.get("value"), fact.get("detail")])
                else:
                    source_texts.append(fact)
        supported: set[str] = set()
        for text in source_texts:
            for marker in cls._exact_claim_markers(text):
                supported.update(cls._exact_claim_marker_aliases(marker))
        return supported

    @classmethod
    def _unsupported_exact_claim_markers(
        cls,
        text: Any,
        *,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any] | None,
    ) -> set[str]:
        markers = cls._exact_claim_markers(text)
        if not markers:
            return set()
        supported = cls._supported_exact_claim_markers(
            request=request,
            compiled_context=compiled_context,
        )
        return {marker for marker in markers if not (cls._exact_claim_marker_aliases(marker) & supported)}

    @classmethod
    def _has_research_fact_context(
        cls,
        *,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any] | None,
    ) -> bool:
        for source in (
            request.research_editorial_brief,
            request.live_research,
            (compiled_context or {}).get("research_editorial_brief"),
            (compiled_context or {}).get("live_research"),
        ):
            if not isinstance(source, dict):
                continue
            fact_model = source.get("fact_model") if isinstance(source.get("fact_model"), dict) else source
            if fact_model.get("verified_facts"):
                return True
            if fact_model.get("research_summary") or fact_model.get("source_summaries"):
                return True
            if fact_model.get("evidence") or fact_model.get("sources"):
                return True
        return False

    @classmethod
    def _visual_focus_is_weak_for_carousel(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=420).casefold()
        if not text:
            return True
        if cls._visual_focus_is_raw_reference_payload(value):
            return True
        if "follow selected sample page" in text and "visual authority" in text:
            return False
        generic_markers = (
            "generic",
            "professional photo",
            "business person",
            "handshake",
            "flag-only",
            "signing ceremony",
            "conceptual visual",
            "clean graphic",
            "finance icon",
            "icons representing",
            "visual highlighting",
        )
        if any(marker in text for marker in generic_markers):
            return True
        specific_visual_markers = (
            "3d",
            "2.5d",
            "isometric",
            "dashboard",
            "chart",
            "graph",
            "module",
            "card",
            "document",
            "evidence",
            "data",
            "map",
            "network",
            "product",
            "screen",
            "yield",
            "bond",
            "tariff",
            "trade",
            "investment",
            "flat editorial",
            "illustration",
            "object",
            "system",
        )
        return not any(marker in text for marker in specific_visual_markers)

    @classmethod
    def _visual_focus_is_raw_reference_payload(cls, value: Any) -> bool:
        if isinstance(value, dict):
            raw_type = cls._normalize_metadata_text(value.get("type"), limit=80).casefold()
            if raw_type in {"reference_image", "uploaded_reference", "asset", "image_asset"}:
                return True
            if any(cls._normalize_metadata_text(value.get(key), limit=260) for key in ("storage_path", "asset_id", "path", "url")):
                return True
        text = cls._normalize_metadata_text(value, limit=520).casefold()
        if not text:
            return False
        reference_markers = (
            "storage_path",
            "reference_image",
            "reference_creatives/",
            "derived-assets/",
            "uploaded reference",
            ".pdf",
            ".png",
            ".jpg",
            ".jpeg",
        )
        return any(marker in text for marker in reference_markers)

    @classmethod
    def _content_line_is_evidence_anchor(
        cls,
        value: Any,
        *,
        request: AIOrchestrationRequest | None,
    ) -> bool:
        text = cls._normalize_metadata_text(value, limit=320)
        if len(text.split()) < 6:
            return False
        topic_tokens = cls._content_topic_tokens(request)
        if not topic_tokens:
            return True
        text_tokens = set(cls._normalized_prompt_tokens(text))
        if text_tokens & topic_tokens:
            return True
        domain_evidence_tokens = {
            "agreement",
            "tariff",
            "tariffs",
            "market",
            "access",
            "services",
            "mobility",
            "investment",
            "investor",
            "investors",
            "wealth",
            "sector",
            "sectors",
            "trade",
            "deal",
            "context",
        }
        return bool(text_tokens & domain_evidence_tokens)

    @classmethod
    def _is_promotional_line(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=220)
        if not text:
            return False
        return bool(cls.PROMOTIONAL_LINE_PATTERN.search(text))

    @classmethod
    def _is_mistake_candidate_line(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=220)
        if not text:
            return False
        if cls.MISTAKE_GROUP_START_PATTERN.match(text):
            return True
        if cls.IMPACT_LINE_PATTERN.match(text) or cls.FIX_LINE_PATTERN.match(text):
            return False
        return bool(cls.NEGATIVE_MISTAKE_CANDIDATE_PATTERN.search(text)) and not cls._is_promotional_line(text)

    @classmethod
    def _mistake_cover_headline(cls, *values: Any) -> str:
        combined = " ".join(
            cls._normalize_metadata_text(value, limit=240)
            for value in values
            if cls._normalize_metadata_text(value, limit=240)
        )
        focus = cls._prompt_topic_summary(combined)
        focus = re.sub(r"\b(?:top|common|most|costly)\b", " ", focus, flags=re.IGNORECASE)
        focus = " ".join(focus.split()).strip(" -:.;")
        if focus and "mistake" not in focus.casefold():
            return cls._normalize_metadata_text(f"Common {focus.title()} Mistakes To Avoid", limit=90)
        if focus:
            return cls._normalize_metadata_text(focus.title(), limit=90)
        return "Common Mistakes To Avoid"

    @classmethod
    def _strip_mistake_markers(cls, value: Any) -> str:
        cleaned = cls._normalize_metadata_text(value, limit=160)
        if not cleaned:
            return ""
        cleaned = cls.MISTAKE_GROUP_START_PATTERN.sub("", cleaned).strip(" -:.;")
        cleaned = cls.MISTAKE_WHY_PATTERN.sub("", cleaned).strip(" -:.;")
        cleaned = cls.IMPACT_LINE_PATTERN.sub("", cleaned).strip(" -:.;")
        cleaned = cls.FIX_LINE_PATTERN.sub("", cleaned).strip(" -:.;")
        return cleaned

    @classmethod
    def _infer_mistake_headline(cls, value: Any, *, fallback_focus: str = "", index: int = 1) -> str:
        cleaned = cls._strip_mistake_markers(value)
        lowered = cleaned.casefold()
        if "diversif" in lowered:
            focus_text = f"{cleaned} {fallback_focus}".casefold()
            if "bond" in focus_text:
                return "Mistake: Not Diversifying Your Bond Portfolio"
            return "Mistake: Not Diversifying Your Portfolio"
        if "yield" in lowered or "return" in lowered:
            return "Mistake: Chasing High Returns"
        if "credit quality" in lowered or "rating" in lowered or "risk" in lowered:
            return "Mistake: Ignoring Quality"
        if "duration" in lowered or "timing" in lowered:
            return "Mistake: Ignoring Timing"
        if cleaned:
            if cls._is_generic_carousel_education_label(cleaned):
                cleaned = ""
            elif str(value).strip().casefold().startswith("mistake:"):
                return cls._normalize_metadata_text(str(value).strip(), limit=110)
            else:
                return f"Mistake: {cleaned}"
        focus = cls._normalize_metadata_text(fallback_focus, limit=90).strip(" -:.;")
        if focus:
            return f"Mistake: {focus}"
        return f"Mistake: Key issue {index}"

    @classmethod
    def _mistake_supporting_line(cls, *values: Any) -> str:
        for candidate in values:
            cleaned = cls._normalize_metadata_text(candidate, limit=220)
            if not cleaned:
                continue
            if (
                cls.MISTAKE_GROUP_START_PATTERN.match(cleaned)
                or cls.IMPACT_LINE_PATTERN.match(cleaned)
                or cls.FIX_LINE_PATTERN.match(cleaned)
                or cls._is_promotional_line(cleaned)
            ):
                continue
            cleaned = cls.MISTAKE_WHY_PATTERN.sub("", cleaned).strip(" -:.;")
            if cleaned:
                return cleaned
        return ""

    @classmethod
    def _mistake_detail_groups(
        cls,
        *,
        headline: str,
        supporting_line: str,
        proof_points: list[str],
        stat_highlights: list[str],
        body_sentences: list[str],
    ) -> list[dict[str, Any]]:
        groups: list[dict[str, Any]] = []
        current: dict[str, Any] | None = None
        labeled_stream = [*proof_points, *body_sentences]
        for item in labeled_stream:
            cleaned = cls._normalize_metadata_text(item, limit=220)
            if not cleaned:
                continue
            if cls.MISTAKE_GROUP_START_PATTERN.match(cleaned):
                if current and (current.get("headline") or current.get("supporting_line") or current.get("proof_points")):
                    groups.append(current)
                current = {
                    "headline": cls._infer_mistake_headline(cleaned, fallback_focus=headline, index=len(groups) + 1),
                    "supporting_line": "",
                    "proof_points": [],
                }
                continue
            if current is None:
                continue
            if not current.get("supporting_line") and not cls.IMPACT_LINE_PATTERN.match(cleaned) and not cls.FIX_LINE_PATTERN.match(cleaned):
                current["supporting_line"] = cls._mistake_supporting_line(cleaned)
            else:
                normalized_line = cls._normalize_metadata_text(cleaned, limit=180)
                if normalized_line and not cls._is_promotional_line(normalized_line):
                    current.setdefault("proof_points", []).append(normalized_line)
        if current and (current.get("headline") or current.get("supporting_line") or current.get("proof_points")):
            groups.append(current)
        if groups:
            normalized_groups: list[dict[str, Any]] = []
            seen_group_headlines: set[str] = set()
            for index, group in enumerate(groups, start=1):
                normalized_group = {
                    "headline": cls._infer_mistake_headline(group.get("headline"), fallback_focus=headline, index=index),
                    "supporting_line": cls._mistake_supporting_line(group.get("supporting_line"), supporting_line),
                    "proof_points": cls._normalize_metadata_list(group.get("proof_points"), limit=3),
                }
                group_key = cls._normalize_metadata_text(normalized_group.get("headline"), limit=120).casefold()
                if group_key and group_key in seen_group_headlines:
                    continue
                if group_key:
                    seen_group_headlines.add(group_key)
                normalized_groups.append(
                    {
                        **normalized_group,
                    }
                )
            return normalized_groups

        evidence_pool = [
            value
            for value in [*stat_highlights, *proof_points, *body_sentences]
            if cls._is_mistake_candidate_line(value)
        ]
        fallback_focus = next(
            (
                cls._strip_mistake_markers(value)
                for value in evidence_pool
                if cls._strip_mistake_markers(value) and not cls._is_generic_carousel_education_label(value)
            ),
            cls._strip_mistake_markers(headline) or cls._strip_mistake_markers(supporting_line),
        )
        wants_multiple = cls._prefers_multiple_mistake_slides(headline, supporting_line, *proof_points, *stat_highlights, *body_sentences)
        target_groups = max(1, len(evidence_pool), 3 if wants_multiple else 2)
        heuristics: list[dict[str, Any]] = []
        for index in range(target_groups):
            title_source = evidence_pool[index] if index < len(evidence_pool) else fallback_focus
            body_slice = body_sentences[index * 2 : index * 2 + 2]
            why_source = cls._mistake_supporting_line(*(body_slice or [supporting_line, title_source]))
            detail_points: list[str] = []
            for point in proof_points[index * 2 : index * 2 + 4]:
                normalized = cls._normalize_metadata_text(point, limit=180)
                if not normalized:
                    continue
                if normalized == cls._normalize_metadata_text(title_source, limit=180):
                    continue
                if cls._is_promotional_line(normalized):
                    continue
                detail_points.append(normalized)
            if not detail_points:
                for sentence in body_sentences[index * 2 + 1 : index * 2 + 4]:
                    normalized = cls._normalize_metadata_text(sentence, limit=180)
                    if normalized and normalized != why_source and not cls._is_promotional_line(normalized):
                        detail_points.append(normalized)
            heuristics.append(
                {
                    "headline": cls._infer_mistake_headline(title_source, fallback_focus=fallback_focus, index=index + 1),
                    "supporting_line": why_source,
                    "proof_points": detail_points[:3],
                }
            )
        return heuristics

    @classmethod
    def _repair_prompt_echo_text_payload(
        cls,
        payload: StructuredTextPayload,
        *,
        prompt: str,
    ) -> StructuredTextPayload:
        raw = payload.model_dump(mode="json")
        metadata = dict(raw.get("metadata") or {})
        proof_points = cls._normalize_metadata_list(metadata.get("proof_points"), limit=4)
        stat_highlights = cls._normalize_metadata_list(metadata.get("stat_highlights"), limit=3)
        prompt_topic = cls._prompt_topic_summary(prompt)
        mistake_style = cls._has_mistake_carousel_signals(
            prompt,
            raw.get("headline"),
            raw.get("body"),
            metadata.get("supporting_line"),
            *proof_points,
            *stat_highlights,
        )
        if cls._looks_like_prompt_echo(raw.get("body"), prompt):
            if proof_points:
                raw["body"] = ". ".join(point.rstrip(" .") for point in proof_points[:3]).strip() + "."
            elif stat_highlights:
                raw["body"] = ". ".join(item.rstrip(" .") for item in stat_highlights[:3]).strip() + "."
            elif prompt_topic:
                raw["body"] = cls._body_from_prompt_topic(prompt_topic)
        if cls._looks_like_prompt_echo(metadata.get("supporting_line"), prompt):
            if proof_points:
                metadata["supporting_line"] = proof_points[0]
            elif prompt_topic:
                metadata["supporting_line"] = cls._supporting_line_from_prompt_topic(prompt_topic)
            elif raw.get("body"):
                metadata["supporting_line"] = cls._sentences(raw.get("body"))[:1][0] if cls._sentences(raw.get("body")) else raw.get("body", "")
        if cls._looks_like_prompt_echo(raw.get("cta"), prompt):
            brand_name = cls._normalize_metadata_text(metadata.get("brand"), limit=48) or "the brand"
            metadata.setdefault("cta_repaired", True)
            raw["cta"] = f"Explore more with {brand_name}"[:72]
        if cls._looks_like_prompt_echo(raw.get("headline"), prompt):
            fallback_headline = (
                ""
                if mistake_style and cls._is_generic_carousel_education_label(metadata.get("section_label"))
                else cls._normalize_metadata_text(metadata.get("section_label"), limit=72)
            )
            if fallback_headline:
                raw["headline"] = fallback_headline
            elif prompt_topic:
                raw["headline"] = (
                    cls._infer_mistake_headline(prompt_topic, fallback_focus=prompt_topic)
                    if mistake_style
                    else cls._headline_from_prompt_topic(prompt_topic)
                )
        metadata["proof_points"] = proof_points or metadata.get("proof_points", [])
        raw["metadata"] = metadata
        return StructuredTextPayload.model_validate(raw)

    @staticmethod
    def _text_payload_prompt_dict(payload: Any) -> dict[str, Any]:
        if hasattr(payload, "model_dump"):
            try:
                dumped = payload.model_dump(mode="json")
                if isinstance(dumped, dict):
                    return dumped
            except TypeError:
                pass
        metadata = getattr(payload, "metadata", {})
        return {
            "headline": getattr(payload, "headline", ""),
            "body": getattr(payload, "body", ""),
            "cta": getattr(payload, "cta", ""),
            "metadata": metadata if isinstance(metadata, dict) else {},
        }

    @classmethod
    def _prompt_topic_summary(cls, prompt: str) -> str:
        text = cls._coerce_text_value(prompt)
        if not text:
            return ""
        text = re.sub(
            r"^(?:please\s+)?(?:create|make|design|generate|write|craft)\s+(?:(?:an?|the)\s+)?",
            "",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"\b(?:an?|the)?\s*(?:engaging|premium|professional|clean|high[- ]quality)\s+",
            "",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"\b(?:instagram|linkedin|facebook|social media|social|post|image|graphic|creative|story|poster|static|carousel|thumbnail)\b",
            " ",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(r"\bthat\s+(?:shares?|highlights?|explains?)\b", " ", text, flags=re.IGNORECASE)
        text = re.sub(r"\babout\b", " ", text, flags=re.IGNORECASE)
        text = " ".join(text.replace("\n", " ").split())
        return text.strip(" ,.;:-")

    @classmethod
    def _headline_from_prompt_topic(cls, topic: str) -> str:
        cleaned = cls._normalize_metadata_text(topic, limit=72)
        if not cleaned:
            return "Brand Update"
        headline = cleaned.title()
        headline = re.sub(r"\bAnd\b", "and", headline)
        headline = re.sub(r"\bFor\b", "for", headline)
        headline = re.sub(r"\bTo\b", "to", headline)
        return headline[:72].rstrip(" ,.;:")

    @classmethod
    def _body_from_prompt_topic(cls, topic: str) -> str:
        cleaned = cls._normalize_metadata_text(topic, limit=160)
        if not cleaned:
            return ""
        topic_kind, focus = cls._prompt_topic_focus(cleaned)
        lens = cls._topic_specific_detail_lens(focus or cleaned)
        if topic_kind == "action" and focus:
            return f"Want to {focus}? Start with {lens}."
        if topic_kind == "why" and focus:
            focus_text = focus[0].upper() + focus[1:]
            return f"{focus_text} matters more when people get {lens}."
        headline = cls._headline_from_prompt_topic(cleaned)
        return f"{headline} starts with {lens}."

    @classmethod
    def _supporting_line_from_prompt_topic(cls, topic: str) -> str:
        cleaned = cls._normalize_metadata_text(topic, limit=120)
        if not cleaned:
            return ""
        topic_kind, focus = cls._prompt_topic_focus(cleaned)
        lens = cls._topic_specific_detail_lens(focus or cleaned)
        if topic_kind == "why" and focus:
            return f"{focus[0].upper() + focus[1:]} needs {lens}"
        if topic_kind == "action" and focus:
            return f"Start with {lens}"
        return f"Start with {lens}"

    @classmethod
    def _fallback_topic_focus(
        cls,
        prompt: str,
        *,
        compiled_context: dict[str, Any] | None = None,
    ) -> str:
        prompt_topic = cls._normalize_metadata_text(cls._prompt_topic_summary(prompt), limit=140)
        if prompt_topic:
            return prompt_topic
        compiled_context = compiled_context if isinstance(compiled_context, dict) else {}
        objective_brief = cls._coerce_mapping(compiled_context.get("objective_brief"))
        brand_copy_brief = cls._coerce_mapping(compiled_context.get("brand_copy_brief"))
        knowledge_brief = compiled_context.get("knowledge_brief", []) or []
        knowledge_line = ""
        if knowledge_brief and isinstance(knowledge_brief[0], dict):
            knowledge_line = cls._normalize_metadata_text(knowledge_brief[0].get("content"), limit=140)
        return cls._normalize_metadata_text(
            objective_brief.get("name")
            or objective_brief.get("primary_goal")
            or objective_brief.get("description")
            or brand_copy_brief.get("objective_focus")
            or brand_copy_brief.get("brand_foundations")
            or brand_copy_brief.get("brand_description")
            or knowledge_line,
            limit=140,
        )

    @classmethod
    def _prompt_topic_focus(cls, topic: str) -> tuple[str, str]:
        cleaned = cls._normalize_metadata_text(topic, limit=160)
        lowered = cleaned.casefold()
        patterns: list[tuple[str, str]] = [
            (r"^(?:tips?(?:\s+and\s+strateg(?:y|ies))?|strateg(?:y|ies)|ways|steps|ideas)\s+to\s+(.+)$", "action"),
            (r"^(?:tips?(?:\s+and\s+strateg(?:y|ies))?|strateg(?:y|ies)|ways|steps|ideas|guide|checklist)\s+for\s+(.+)$", "topic"),
            (r"^how to\s+(.+)$", "action"),
            (r"^guide to\s+(.+)$", "action"),
            (r"^checklist for\s+(.+)$", "topic"),
            (r"^why\s+(.+)$", "why"),
        ]
        for pattern, topic_kind in patterns:
            match = re.match(pattern, lowered, flags=re.IGNORECASE)
            if not match:
                continue
            focus = cls._normalize_metadata_text(match.group(1), limit=140)
            if focus:
                return topic_kind, focus
        return "topic", cleaned

    @classmethod
    def _topic_specific_detail_lens(cls, topic: str) -> str:
        lowered = cls._normalize_metadata_text(topic, limit=160).casefold()
        if not lowered:
            return "specific details people can act on right away"
        if any(token in lowered for token in ("price", "pricing", "cost", "afford", "budget", "save", "savings", "cheaper", "lower")):
            return "the choices that change price the most"
        if any(token in lowered for token in ("risk", "trust", "confidence", "safe", "safety", "secure", "clarity", "opaque")):
            return "proof and plain-English clarity people can trust"
        if any(token in lowered for token in ("compare", "comparison", "versus", "vs ", "choose", "choice", "option")):
            return "the trade-offs that make the decision easier"
        if any(token in lowered for token in ("learn", "understand", "explain", "guide", "checklist", "how to", "tips", "strategy", "strategies")):
            return "plain-language takeaways people can use quickly"
        if any(token in lowered for token in ("grow", "improve", "scale", "increase", "launch", "build")):
            return "the moves that make progress feel real"
        return "specific details people can act on right away"

    @classmethod
    def _contextual_headline_fallback(
        cls,
        *,
        topic_focus: str,
        motivation: str,
        pain_point: str,
        research_highlight: str,
        brand_foundations: Any,
        knowledge_line: str,
        primary_goal: Any,
        semantic_support_phrase: str,
    ) -> str:
        normalized_topic = cls._normalize_metadata_text(topic_focus, limit=120)
        normalized_motivation = cls._normalize_metadata_text(motivation, limit=96)
        normalized_pain_point = cls._normalize_metadata_text(pain_point, limit=96)
        normalized_research = cls._normalize_metadata_text(research_highlight, limit=120)
        normalized_foundations = cls._normalize_metadata_text(brand_foundations, limit=120)
        normalized_knowledge = cls._normalize_metadata_text(knowledge_line, limit=120)
        normalized_goal = cls._normalize_metadata_text(primary_goal, limit=96)
        if normalized_topic:
            if normalized_motivation and normalized_research:
                return (
                    f"Frame '{normalized_topic}' around '{normalized_motivation}', using this audience truth as the proof: "
                    f"{normalized_research}"
                )
            if normalized_motivation and normalized_foundations:
                return (
                    f"Frame '{normalized_topic}' around '{normalized_motivation}' while reinforcing "
                    f"{normalized_foundations}."
                )
            if normalized_pain_point and normalized_research:
                return (
                    f"Lead '{normalized_topic}' by resolving '{normalized_pain_point}' with this audience truth: "
                    f"{normalized_research}"
                )
            if normalized_motivation:
                return (
                    f"Lead '{normalized_topic}' with the payoff of '{normalized_motivation}', not a generic benefit list."
                )
            if normalized_research:
                return f"Lead '{normalized_topic}' with this audience truth: {normalized_research}"
            if normalized_foundations:
                return f"Lead '{normalized_topic}' in a way that reinforces {normalized_foundations}."
            if normalized_knowledge:
                return f"Ground '{normalized_topic}' in this concrete fact: {normalized_knowledge}"
            if normalized_goal:
                return f"Lead '{normalized_topic}' in a way that moves people toward {normalized_goal}."
            return f"Lead '{normalized_topic}' with {semantic_support_phrase} so the value feels earned."
        if normalized_foundations and normalized_goal:
            return f"Anchor the message in {normalized_foundations} and connect it to {normalized_goal}."
        if normalized_research:
            return f"Anchor the message in this audience truth: {normalized_research}"
        if normalized_foundations:
            return f"Anchor the message in {normalized_foundations} so it stays distinctive."
        if normalized_knowledge:
            return f"Anchor the message in this concrete fact: {normalized_knowledge}"
        return "Anchor the message in a concrete audience payoff and believable proof."

    @classmethod
    def _contextual_supporting_fallback(
        cls,
        *,
        topic_focus: str,
        motivation: str,
        pain_point: str,
        objection: str,
        brand_foundations: Any,
        research_highlight: str,
        knowledge_line: str,
        semantic_support_phrase: str,
    ) -> str:
        normalized_topic = cls._normalize_metadata_text(topic_focus, limit=120)
        normalized_motivation = cls._normalize_metadata_text(motivation, limit=96)
        normalized_pain_point = cls._normalize_metadata_text(pain_point, limit=96)
        normalized_objection = cls._normalize_metadata_text(objection, limit=96)
        normalized_foundations = cls._normalize_metadata_text(brand_foundations, limit=120)
        normalized_research = cls._normalize_metadata_text(research_highlight, limit=120)
        normalized_knowledge = cls._normalize_metadata_text(knowledge_line, limit=120)
        if normalized_topic and normalized_objection and normalized_research:
            return (
                f"Back '{normalized_topic}' with concrete proof that answers '{normalized_objection}', "
                f"starting from this audience signal: {normalized_research}"
            )
        if normalized_topic and normalized_objection and normalized_knowledge:
            return (
                f"Back '{normalized_topic}' with concrete proof that answers '{normalized_objection}', "
                f"using this fact: {normalized_knowledge}"
            )
        if normalized_topic and normalized_pain_point and normalized_motivation:
            return (
                f"Show how '{normalized_topic}' moves people from '{normalized_pain_point}' to "
                f"'{normalized_motivation}' with concrete detail."
            )
        if normalized_topic and normalized_foundations and normalized_knowledge:
            return (
                f"Show how '{normalized_topic}' delivers on {normalized_foundations}, using this fact: "
                f"{normalized_knowledge}"
            )
        if normalized_topic and normalized_foundations:
            return f"Show how '{normalized_topic}' delivers on {normalized_foundations} with concrete detail."
        if normalized_topic and normalized_research:
            return f"Use this audience signal as the proof lens for '{normalized_topic}': {normalized_research}"
        if normalized_topic:
            return f"Back '{normalized_topic}' with {semantic_support_phrase}, so the message sounds useful rather than generic."
        if normalized_research:
            return f"Use this audience signal as the proof lens: {normalized_research}"
        if normalized_knowledge:
            return f"Build the support copy around this concrete fact: {normalized_knowledge}"
        if normalized_foundations:
            return f"Translate {normalized_foundations} into concrete proof the audience can picture."
        return f"Back the message with {semantic_support_phrase} so it feels earned."

    @classmethod
    def _contextual_cta_fallback(
        cls,
        *,
        topic_focus: str,
        primary_goal: Any,
        pain_point: str,
        objection: str,
    ) -> str:
        normalized_goal = cls._normalize_metadata_text(primary_goal, limit=80)
        normalized_topic = cls._normalize_metadata_text(topic_focus, limit=120)
        normalized_pain_point = cls._normalize_metadata_text(pain_point, limit=96)
        normalized_objection = cls._normalize_metadata_text(objection, limit=96)
        if normalized_goal and normalized_topic:
            return (
                f"Invite a low-friction next step that helps the audience act on '{normalized_topic}' "
                f"and move toward {normalized_goal}."
            )
        if normalized_goal and normalized_objection:
            return (
                f"Invite a low-friction next step that helps skeptical readers validate the claim "
                f"and move toward {normalized_goal}."
            )
        if normalized_goal:
            return f"Invite a low-friction next step that moves the audience toward {normalized_goal}."
        if normalized_topic and normalized_objection:
            return (
                f"Invite a low-friction next step tied to '{normalized_topic}' so skeptical readers can validate it "
                f"for themselves."
            )
        if normalized_topic and normalized_pain_point:
            return (
                f"Invite a low-friction next step tied to '{normalized_topic}' that reduces the feeling of "
                f"'{normalized_pain_point}'."
            )
        if normalized_topic:
            return f"Invite a low-friction next step tied to '{normalized_topic}' so the CTA feels useful, not generic."
        return "Invite a low-friction next step that helps the audience act with more clarity."

    @classmethod
    def _looks_like_fallback_copy_scaffold(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=220).casefold()
        if not text:
            return False
        if any(text.startswith(prefix) for prefix in cls.FALLBACK_COPY_INSTRUCTION_PREFIXES):
            return True
        return any(marker in text for marker in cls.FALLBACK_COPY_DESCRIPTOR_MARKERS)

    @classmethod
    def _usable_fallback_copy_text(
        cls,
        value: Any,
        *,
        limit: int,
        prompt: str,
    ) -> str:
        text = cls._normalize_metadata_text(value, limit=limit)
        if not text or text.casefold() == "missing":
            return ""
        if cls._looks_like_fallback_copy_scaffold(text):
            return ""
        if prompt and cls._looks_like_prompt_echo(text, prompt):
            return ""
        return text

    @classmethod
    def _fallback_copy_fragments(
        cls,
        candidates: list[Any],
        *,
        prompt: str,
        limit: int,
        max_items: int,
        exclude: list[str] | None = None,
    ) -> list[str]:
        fragments: list[str] = []
        seen = {
            cls._normalize_metadata_text(item, limit=limit).casefold()
            for item in (exclude or [])
            if cls._normalize_metadata_text(item, limit=limit)
        }
        for candidate in candidates:
            text = cls._usable_fallback_copy_text(candidate, limit=limit, prompt=prompt)
            if not text:
                continue
            key = text.casefold()
            if key in seen:
                continue
            fragments.append(text.rstrip())
            seen.add(key)
            if len(fragments) >= max_items:
                break
        return fragments

    @classmethod
    def _fallback_headline_copy(
        cls,
        *,
        prompt: str,
        claim_evidence_pairs: list[dict[str, str]],
        desired_outcomes: list[str],
        key_value_proposition: Any,
        headline_direction: Any,
        primary_campaign_theme: Any,
        core_audience_message: Any,
    ) -> str:
        candidates: list[Any] = [
            *desired_outcomes[:2],
            key_value_proposition,
            *[pair.get("claim") for pair in claim_evidence_pairs if isinstance(pair, dict)],
            primary_campaign_theme,
            headline_direction,
            core_audience_message,
        ]
        fragments = cls._fallback_copy_fragments(
            candidates,
            prompt=prompt,
            limit=80,
            max_items=1,
        )
        if fragments:
            return fragments[0].rstrip(" .!?")
        prompt_topic = cls._prompt_topic_summary(prompt)
        if prompt_topic:
            return cls._headline_from_prompt_topic(prompt_topic)
        return "Brand Update"

    @classmethod
    def _fallback_body_copy(
        cls,
        *,
        prompt: str,
        headline: str,
        core_audience_message: Any,
        claim_evidence_pairs: list[dict[str, str]],
        trust_builders: list[str],
        proof_points: list[str],
        research_highlights: list[str],
        supporting_copy_direction: Any,
        key_value_proposition: Any,
    ) -> str:
        claim_lines = cls._claim_evidence_pair_lines(claim_evidence_pairs, limit=2)
        fragments = cls._fallback_copy_fragments(
            [
                core_audience_message,
                *claim_lines,
                *trust_builders[:2],
                *proof_points[:2],
                *research_highlights[:2],
                supporting_copy_direction,
                key_value_proposition,
            ],
            prompt=prompt,
            limit=180,
            max_items=2,
            exclude=[headline],
        )
        if fragments:
            return cls._normalize_metadata_text(" ".join(fragments), limit=220)
        prompt_topic = cls._prompt_topic_summary(prompt)
        if prompt_topic:
            return cls._body_from_prompt_topic(prompt_topic)
        return "See the details in a concrete, audience-relevant way."

    @classmethod
    def _fallback_cta_copy(
        cls,
        *,
        prompt: str,
        cta_intent: Any,
        primary_goal: Any,
        topic_focus: str,
        comparison_points: list[str],
        proof_cues: list[str],
        trust_signals: list[str],
    ) -> str:
        direct_cta = cls._usable_fallback_copy_text(cta_intent, limit=44, prompt=prompt)
        if direct_cta and len(direct_cta.split()) <= 6:
            return direct_cta.rstrip(" .!?")

        normalized_goal = cls._normalize_metadata_text(primary_goal, limit=80).casefold()
        normalized_intent = cls._normalize_metadata_text(cta_intent, limit=120).casefold()
        normalized_topic = cls._normalize_metadata_text(topic_focus, limit=120).casefold()

        if any(token in normalized_goal or token in normalized_intent for token in ("demo", "consult", "call")):
            return "Book a demo"
        if any(token in normalized_goal or token in normalized_intent for token in ("download", "guide", "report", "ebook")):
            return "Get the guide"
        if any(token in normalized_goal or token in normalized_intent for token in ("sign up", "signup", "register", "join", "subscribe")):
            return "Sign up"
        if comparison_points or any(
            token in normalized_intent or token in normalized_topic
            for token in ("compare", "comparison", "versus", "vs", "option", "options", "trade-off", "tradeoff", "difference")
        ):
            return "Compare the options"
        if proof_cues or trust_signals or any(
            token in normalized_intent or token in normalized_topic
            for token in ("proof", "trust", "clarity", "confidence", "details", "risk", "validate")
        ):
            return "See the details"
        if any(
            token in normalized_intent or token in normalized_topic
            for token in ("learn", "understand", "explain", "guide", "checklist", "tips", "strategy", "strategies", "how to")
        ):
            return "Get the details"
        return "See how it works"

    @classmethod
    def _looks_like_objection_response(cls, value: Any) -> bool:
        text = cls._normalize_metadata_text(value, limit=180)
        if not text:
            return False
        lowered = text.casefold()
        if any(lowered.startswith(prefix) for prefix in cls.OBJECTION_RESPONSE_INSTRUCTION_PREFIXES):
            return False
        return any(marker in lowered for marker in cls.OBJECTION_RESPONSE_MARKERS)

    @classmethod
    def _fallback_objection_handling_copy(
        cls,
        *,
        objections: list[str],
        pain_points: list[str],
        proof_cues: list[str],
        trust_signals: list[str],
        comparison_points: list[str],
        research_highlights: list[str],
    ) -> str:
        objection = cls._normalize_metadata_text(objections[0] if objections else "", limit=160)
        pain_point = cls._normalize_metadata_text(pain_points[0] if pain_points else "", limit=140)
        proof_cue = cls._normalize_metadata_text(proof_cues[0] if proof_cues else "", limit=140)
        trust_signal = cls._normalize_metadata_text(trust_signals[0] if trust_signals else "", limit=140)
        comparison_point = cls._normalize_metadata_text(comparison_points[0] if comparison_points else "", limit=140)
        research_highlight = cls._normalize_metadata_text(research_highlights[0] if research_highlights else "", limit=140)
        objection_context = f"{objection} {pain_point}".casefold()

        if any(
            token in objection_context
            for token in ("switch", "switching", "migrate", "migration", "change", "onboarding", "implementation", "rollout")
        ):
            anchor = trust_signal or proof_cue or "Guided onboarding"
            return cls._normalize_metadata_text(
                f"{anchor.rstrip('.')} so the next step feels lower-risk without forcing an overnight change.",
                limit=180,
            )
        if any(
            token in objection_context
            for token in ("risk", "return", "returns", "trust", "confidence", "opaque", "clarity", "clear", "proof")
        ):
            anchor = proof_cue or trust_signal or research_highlight or comparison_point or "Transparent downside framing"
            return cls._normalize_metadata_text(
                f"{anchor.rstrip('.')} with transparent downside framing so the trade-off feels clearer and easier to trust.",
                limit=180,
            )
        if any(
            token in objection_context
            for token in ("price", "pricing", "cost", "budget", "expensive", "afford", "value")
        ):
            anchor = comparison_point or proof_cue or trust_signal or "Transparent price framing"
            return cls._normalize_metadata_text(
                f"{anchor.rstrip('.')} so the value is easier to compare without guesswork.",
                limit=180,
            )
        anchor = proof_cue or trust_signal or comparison_point or research_highlight
        if anchor:
            return cls._normalize_metadata_text(
                f"{anchor.rstrip('.')} so the next step feels supported and lower risk.",
                limit=180,
            )
        if pain_point:
            return cls._normalize_metadata_text(
                "Without extra complexity, the next step gives the audience a clearer path forward.",
                limit=180,
            )
        return ""

    @classmethod
    def _sync_scene_graph_copy_from_text_payload(
        cls,
        *,
        elements: list[dict[str, Any]],
        text_payload: dict[str, Any],
    ) -> list[dict[str, Any]]:
        metadata = cls._coerce_mapping(text_payload.get("metadata"))
        supporting_line = cls._normalize_metadata_text(
            metadata.get("supporting_line") or text_payload.get("body"),
            limit=220,
        )
        proof_points = cls._normalize_metadata_list(metadata.get("proof_points"), limit=4)
        stat_highlights = cls._normalize_metadata_list(metadata.get("stat_highlights"), limit=3)
        synced: list[dict[str, Any]] = []
        for element in elements:
            normalized = dict(element)
            role = str(normalized.get("role") or "").strip().lower()
            if role == "headline":
                normalized["text"] = text_payload.get("headline", "")
            elif role == "body":
                normalized["text"] = text_payload.get("body", "")
            elif role == "supporting_line":
                normalized["text"] = supporting_line
            elif role == "cta":
                normalized["text"] = text_payload.get("cta", "")
            elif role == "proof_points":
                normalized["text"] = proof_points or stat_highlights or cls._sentences(text_payload.get("body"))[:3]
            elif role == "stat_highlights":
                normalized["text"] = stat_highlights
            elif role == "section_label":
                normalized["text"] = cls._normalize_metadata_text(metadata.get("section_label"), limit=64)
            synced.append(normalized)
        return synced

    @classmethod
    def _contains_disallowed_glyphs(cls, value: str) -> bool:
        return bool(cls.DISALLOWED_GLYPH_PATTERN.search(value or "") or cls.MOJIBAKE_SYMBOL_PATTERN.search(value or ""))

    @staticmethod
    def _scene_graph_visible_elements(scene_graph: GenerationSceneGraph) -> list[Any]:
        return [element for element in scene_graph.elements if element.visible]

    def _should_apply_support_fallback(
        self,
        *,
        scene_graph: GenerationSceneGraph,
        validation_report: SceneGraphValidationReport,
    ) -> bool:
        visible_elements = self._scene_graph_visible_elements(scene_graph)
        content_elements = [element for element in visible_elements if element.role != "background"]
        severe_rules = {
            "missing_headline",
            "logo_required",
            "insufficient_scene_graph_structure",
            "missing_visual_emphasis",
            "asset_strategy_unfulfilled",
            "asset_strategy_overloaded",
            "icon_stamp_column",
            "icon_overuse_with_hero_image",
            "prompt_echo_copy",
            "topic_anchor_missing",
        }
        if len(content_elements) < 4:
            return True
        if any(issue.rule_id in severe_rules for issue in validation_report.issues):
            return True
        return False

    @staticmethod
    def _should_request_fresh_replan(validation_report: SceneGraphValidationReport) -> bool:
        severe_rules = {
            "missing_headline",
            "insufficient_scene_graph_structure",
            "missing_visual_emphasis",
            "topic_anchor_missing",
            "prompt_echo_copy",
        }
        return any(issue.rule_id in severe_rules for issue in validation_report.issues)

    @staticmethod
    def _fresh_replan_note(validation_report: SceneGraphValidationReport) -> str:
        issues = [str(issue.rule_id or "").strip() for issue in validation_report.issues if str(issue.rule_id or "").strip()]
        if not issues:
            return (
                "Discard the prior weak scene graph and create a fresh plan from the user prompt, "
                "brand knowledge, objective, and guardrails."
            )
        return (
            "Discard the prior weak scene graph instead of repairing around it. "
            "Create a fresh plan from the user prompt, brand knowledge, objective, and guardrails. "
            f"The prior plan failed on: {', '.join(issues)}."
        )

    @classmethod
    def _scene_graph_has_authoritative_geometry(cls, scene_graph: GenerationSceneGraph | None) -> bool:
        if not isinstance(scene_graph, GenerationSceneGraph):
            return False
        geometry_count = 0
        anchored_roles: set[str] = set()
        for element in scene_graph.elements:
            if not element.visible or element.role == "background":
                continue
            geometry = element.geometry or SceneGraphGeometry()
            if all(getattr(geometry, attr, None) is not None for attr in ("x", "y", "width", "height")):
                geometry_count += 1
                normalized_role = str(element.role or "").strip().lower()
                anchored_roles.add(normalized_role)
                if cls._scene_graph_element_is_visual_image_like(element):
                    anchored_roles.add("image")
        return geometry_count >= 3 or {"headline", "image", "cta"} <= anchored_roles

    @classmethod
    def _compiled_context_has_authoritative_layout(cls, compiled_context: dict[str, Any] | None) -> bool:
        context = dict(compiled_context or {})
        template_fit = cls._coerce_mapping(context.get("template_fit_brief"))
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        design_system = cls._coerce_mapping(brand_visual.get("design_system"))
        layout_dna = (
            template_fit.get("template_layout_dna")
            or design_system.get("template_layout_dna")
            or design_system.get("layout_dna")
        )
        sequence_pack = template_fit.get("sequence_pack") or design_system.get("template_sequence_pack")
        if isinstance(layout_dna, dict) and (
            layout_dna.get("zone_map")
            or layout_dna.get("zones")
            or layout_dna.get("layout_type")
        ):
            return True
        if isinstance(sequence_pack, dict) and (
            sequence_pack.get("pages")
            or sequence_pack.get("sequence")
            or sequence_pack.get("story_arc_roles")
            or sequence_pack.get("slides")
            or sequence_pack.get("sequence_cues")
        ):
            return True
        return False

    @classmethod
    def _scene_graph_element_is_visual_image_like(cls, element: SceneGraphElement | dict[str, Any] | None) -> bool:
        if element is None:
            return False
        if isinstance(element, dict):
            visible = bool(element.get("visible", True))
            role = str(element.get("role") or "").strip().casefold()
            element_type = str(element.get("element_type") or "").strip().casefold()
            asset_payload = element.get("asset") if isinstance(element.get("asset"), dict) else {}
        else:
            visible = bool(element.visible)
            role = str(element.role or "").strip().casefold()
            element_type = str(element.element_type or "").strip().casefold()
            asset_payload = (
                element.asset.model_dump(mode="json")
                if getattr(element, "asset", None) is not None
                else {}
            )
        if not visible or role == "background":
            return False
        if role == "image" or element_type == "image":
            return True
        image_like_roles = {
            "hero_visual",
            "hero_image",
            "primary_visual",
            "supporting_visual",
            "supporting_visuals",
            "illustration",
            "illustration_group",
            "infographic_cluster",
            "visual_cluster",
        }
        if role in image_like_roles:
            return True
        asset_role = str((asset_payload or {}).get("asset_role") or "").strip().casefold()
        return any(
            token in asset_role
            for token in ("image", "illustration", "photo", "render", "visual", "infographic")
        )

    @staticmethod
    def _compact_scene_graph_geometry(scene_graph: GenerationSceneGraph | None, limit: int = 8) -> str:
        if not isinstance(scene_graph, GenerationSceneGraph):
            return ""
        geometry_manifest: list[dict[str, Any]] = []
        for element in scene_graph.elements:
            if (
                not element.visible
                or element.role == "background"
                or str(element.role or "").strip().casefold() == "logo"
                or str(element.element_type or "").strip().casefold() == "logo"
                or str(element.element_type or "").strip().casefold() == "multi_slide_sequence"
            ):
                continue
            geometry = element.geometry or SceneGraphGeometry()
            if not all(getattr(geometry, attr, None) is not None for attr in ("x", "y", "width", "height")):
                continue
            entry = {
                "role": str(element.role or "").strip().lower(),
                "type": str(element.element_type or "").strip().lower(),
                "x": round(float(geometry.x), 3),
                "y": round(float(geometry.y), 3),
                "w": round(float(geometry.width), 3),
                "h": round(float(geometry.height), 3),
            }
            if geometry.anchor:
                entry["anchor"] = str(geometry.anchor)
            if geometry.z_index is not None:
                entry["z"] = int(geometry.z_index)
            if element.validation_hints:
                text_role = str((element.validation_hints or {}).get("text_role") or "").strip()
                if text_role:
                    entry["text_role"] = text_role
            geometry_manifest.append(entry)
            if len(geometry_manifest) >= limit:
                break
        if not geometry_manifest:
            return ""
        return json.dumps(geometry_manifest, separators=(",", ":"), ensure_ascii=True)

    @classmethod
    def _compact_layout_dna_contract(cls, compiled_context: dict[str, Any] | None, limit: int = 8) -> str:
        context = dict(compiled_context or {})
        template_fit = cls._coerce_mapping(context.get("template_fit_brief"))
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        design_system = cls._coerce_mapping(brand_visual.get("design_system"))
        layout_dna = (
            template_fit.get("template_layout_dna")
            or design_system.get("template_layout_dna")
            or design_system.get("layout_dna")
        )
        if not isinstance(layout_dna, dict):
            return ""
        payload: dict[str, Any] = {}
        layout_type = cls._normalize_metadata_text(layout_dna.get("layout_type"), limit=64)
        canvas_ratio = cls._normalize_metadata_text(layout_dna.get("canvas_ratio"), limit=32)
        if layout_type:
            payload["layout_type"] = layout_type
        if canvas_ratio:
            payload["ratio"] = canvas_ratio
        zones: list[dict[str, Any]] = []
        raw_zones = layout_dna.get("zone_map") or layout_dna.get("zones") or []
        if isinstance(raw_zones, dict):
            raw_zones = [
                {"role": key, **(value if isinstance(value, dict) else {})}
                for key, value in raw_zones.items()
            ]
        for item in raw_zones[:limit]:
            if not isinstance(item, dict):
                continue
            zone = {
                "role": cls._normalize_metadata_text(item.get("role") or item.get("zone_role"), limit=32),
                "x": item.get("x"),
                "y": item.get("y"),
                "w": item.get("width") if item.get("width") is not None else item.get("w"),
                "h": item.get("height") if item.get("height") is not None else item.get("h"),
            }
            if item.get("anchor"):
                zone["anchor"] = cls._normalize_metadata_text(item.get("anchor"), limit=24)
            if item.get("priority"):
                zone["priority"] = cls._normalize_metadata_text(item.get("priority"), limit=16)
            if all(zone.get(key) is not None for key in ("x", "y", "w", "h")) and zone.get("role"):
                for key in ("x", "y", "w", "h"):
                    zone[key] = round(float(zone[key]), 3)
                zones.append(zone)
        if zones:
            payload["zones"] = zones
        if not payload:
            return ""
        return json.dumps(payload, separators=(",", ":"), ensure_ascii=True)

    @classmethod
    def _final_render_grounding_sections(
        cls,
        *,
        request: AIOrchestrationRequest,
        creative_decision: CreativeDecisionPayload,
        text_payload: StructuredTextPayload,
        compiled_context: dict[str, Any] | None,
        reference_assets: list[dict[str, Any]] | None,
        allow_template_surface_imitation: bool = False,
    ) -> list[str]:
        compiled_context = dict(compiled_context or {})
        metadata = text_payload.metadata or {}
        visual_identity = request.resolved_brand_context.get("visual_identity", {}) or {}
        asset_strategy = (creative_decision.asset_strategy if creative_decision else {}) or {}
        template_surface_policy = cls._effective_template_surface_policy(
            request,
            creative_decision=creative_decision,
            metadata=metadata if isinstance(metadata, dict) else {},
        )
        design_style = cls._normalize_metadata_text(metadata.get("design_style"), limit=80)
        visual_direction = cls._normalize_metadata_text(metadata.get("visual_direction"), limit=180)
        preferred_scene = cls._normalize_metadata_text(metadata.get("image_prompt"), limit=220)
        layout_decision = cls._compact_layout_decision(request.layout_decision)
        visual_knowledge_brief = ContextCompilerService.coerce_visual_knowledge_brief(
            compiled_context.get("visual_knowledge_brief"),
        )
        direct_brand_grounding = cls._brand_knowledge_visual_grounding(visual_knowledge_brief)
        grounding_mode = cls._normalize_metadata_text(visual_knowledge_brief.get("grounding_mode"), limit=32)
        grounding_strength = cls._normalize_metadata_text(visual_knowledge_brief.get("grounding_strength"), limit=32)
        grounding_abstention_reason = cls._normalize_metadata_text(
            visual_knowledge_brief.get("abstention_reason"),
            limit=64,
        )
        template_suppressed = bool(visual_knowledge_brief.get("template_suppressed"))
        include_reference_system = bool(reference_assets) or bool(visual_identity.get("reusable_design_assets"))
        reusable_assets = cls._compact_named_items(visual_identity.get("reusable_design_assets"), limit=4)
        reference_summary = cls._compact_reference_assets(reference_assets or [])
        dominant_visual_system = cls._normalized_dominant_visual_system(asset_strategy) or "generated_image"
        supporting_visual_system = cls._normalized_supporting_visual_system(asset_strategy)
        include_reusable_asset_names = include_reference_system and template_surface_policy != "style_reference_only"
        sections = [
            (
                f"Brand knowledge grounding mode: {grounding_mode or 'brand_knowledge'} (strength: {grounding_strength or 'supported'})."
                if direct_brand_grounding
                else (
                    f"Brand knowledge grounding mode: llm_fallback (reason: {grounding_abstention_reason})."
                    if grounding_abstention_reason
                    else "Brand knowledge grounding mode: llm_fallback."
                )
            ),
            (
                f"Brand knowledge grounding: {direct_brand_grounding}. Treat these retrieved brand-knowledge cues as the primary visual grounding contract."
                if direct_brand_grounding
                else "Brand knowledge grounding: no retrieved brand knowledge is available, so infer the visual through the approved copy, message strategy, and brand system."
            ),
            (
                "If retrieved brand knowledge is present, do not override it with a generic invented scene. Use model reasoning only to combine the retrieved cues coherently."
                if direct_brand_grounding
                else "Because retrieved brand knowledge is absent, derive the visual direction from the approved copy, message strategy, and brand system."
            ),
            (
                "Template-derived cues were suppressed because stronger visual identity or mood-board evidence exists."
                if direct_brand_grounding and template_suppressed
                else ""
            ),
            (
                "If the active brand grounding is fallback-only, use template and metadata cues only for structure, palette, spacing, and composition. Do not literalize template copy."
                if direct_brand_grounding and grounding_strength == "fallback_only"
                else ""
            ),
            f"Layout approach: {layout_decision}.",
            f"Dominant visual system: {dominant_visual_system}.",
            f"Supporting visual system: {supporting_visual_system or 'none'}.",
            (
                f"Reusable brand design assets available as stylistic cues: {reusable_assets}."
                if include_reusable_asset_names and reusable_assets and reusable_assets != "None"
                else ""
            ),
            (
                f"Reference asset system available: {reference_summary}."
                if include_reference_system and reference_summary and template_surface_policy != "style_reference_only"
                else ""
            ),
            (
                "When the active template policy is style-reference-only, preserve the uploaded sample's composition skeleton, region proportions, negative space, sequencing, and craft direction as closely as possible while reinterpreting all artwork and text from scratch. Do not trace or copy the literal sample surface."
                if template_surface_policy == "style_reference_only" and not allow_template_surface_imitation
                else ""
            ),
            (f"Fallback design style hint: {design_style}." if design_style else ""),
            (f"Fallback visual direction hint: {visual_direction}." if visual_direction else ""),
            (f"Fallback preferred scene hint: {preferred_scene}." if preferred_scene else ""),
        ]
        return [section for section in sections if section]

    @classmethod
    def _research_editorial_prompt_section(
        cls,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any] | None = None,
    ) -> str:
        context = dict(compiled_context or {})
        request_brief = getattr(request, "research_editorial_brief", None)
        brief = (
            context.get("research_editorial_brief")
            if isinstance(context.get("research_editorial_brief"), dict)
            else request_brief
            if isinstance(request_brief, dict)
            else {}
        )
        if not isinstance(brief, dict):
            return (
                "Research discipline: prefer source-backed specificity when available, and never invent unsupported "
                "numbers, rankings, timelines, or market claims."
            )
        claim_pairs = cls._claim_evidence_pairs_from_research_brief(brief, limit=2)
        verified_facts = (
            (brief.get("fact_model") or {}).get("verified_facts")
            if isinstance(brief.get("fact_model"), dict)
            else []
        )
        if claim_pairs or verified_facts:
            return (
                "Research discipline: anchor specific claims to verified facts and approved claim-evidence pairs only. "
                "Keep the synthesis concise, and do not add extra statistics, rankings, or market assertions that are not supported."
            )
        needs_live_research = bool(brief.get("needs_live_research"))
        research_status = cls._normalize_metadata_text(brief.get("research_status"), limit=32).casefold()
        if needs_live_research or research_status in {"unavailable", "required", "missing"}:
            return (
                "Research discipline: when verified research is limited, stay descriptive and principle-led. "
                "Do not invent exact figures, dates, performance claims, or factual certainty."
            )
        return (
            "Research discipline: prefer source-backed specificity when available, and never invent unsupported "
            "numbers, rankings, timelines, or market claims."
        )

    @classmethod
    def _image_generation_anti_hallucination_prompt_section(
        cls,
        *,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any] | None = None,
    ) -> str:
        context = dict(compiled_context or {})
        source_texts: list[Any] = [getattr(request, "prompt", "")]
        for source in (
            getattr(request, "research_editorial_brief", None),
            getattr(request, "live_research", None),
            context.get("research_editorial_brief"),
            context.get("live_research"),
        ):
            if not isinstance(source, dict):
                continue
            fact_model = source.get("fact_model") if isinstance(source.get("fact_model"), dict) else source
            for fact in fact_model.get("verified_facts") or []:
                if isinstance(fact, dict):
                    source_texts.extend([fact.get("label"), fact.get("value"), fact.get("detail")])
                else:
                    source_texts.append(fact)
        supported_markers: set[str] = set()
        for text in source_texts:
            for marker in cls._exact_claim_markers(text):
                supported_markers.update(cls._exact_claim_marker_aliases(marker))
        supported_marker_line = (
            "Source-backed exact values allowed in visible facts/data: "
            + ", ".join(sorted(supported_markers)[:8])
            + ". Add no other numbers, dates, ranks, currency, percentages, or chart values."
            if supported_markers
            else (
                "No source-backed exact values are available for visible facts/data; keep data-like visuals qualitative "
                "and do not render numeric values, dates, rankings, percentages, currency amounts, axes, or chart labels."
            )
        )
        return (
            "Anti-hallucination guard: visible facts, data, objects, documents, UI, products, official marks, source labels, badges, maps, "
            "and charts must be directly supported by the user prompt, verified research, retrieved brand knowledge, references, or approved layout metadata. "
            "Approved copy guides theme and wording only; do not invent fake stats, dashboards, sources, certifications, brand marks, official symbols, "
            "product screens, unrelated industries, pseudo text, or adjacent claims. "
            "Unsupported specifics must become visual absence, neutral placeholders, or generic category-level shapes, not invented detail; do not create named organizations, countries, documents, app screens, people, awards, certificates, source mastheads, maps, UI controls, product labels, or identity marks unless explicitly supported. "
            + supported_marker_line
        )

    @staticmethod
    def _consultant_quality_contract(
        *,
        for_visual_only: bool,
        for_carousel: bool,
        for_static_infographic_ad: bool = False,
    ) -> list[str]:
        layout_target = (
            "Use an advanced explanatory slide composition with deliberate grouping, alignment, rhythm, and negative space; "
            "do not collapse into a generic top-heading, middle-image, bottom-footer layout."
            if for_carousel
            else "Use a simple, scroll-stopping social ad composition with one dominant focal idea, clear headline hierarchy, generous breathing room, and a visible CTA path; do not make it feel like a document page, dense report, or plain text poster."
            if for_static_infographic_ad
            else "Use an advanced explanatory composition with deliberate grouping, alignment, rhythm, and negative space; "
            "do not collapse into a generic top-heading, centered-visual, bottom-footer poster."
        )
        copy_target = (
            "Copy discipline: keep the message concise, high-signal, and editorially tight. Prefer one sharp headline, one supporting line, and only essential proof points. Remove filler, repetition, generic hype, and broad claims."
            if not for_visual_only
            else "Message discipline: make the visual support a concise, high-signal story rather than a vague or generic mood piece."
        )
        return [
            copy_target,
            f"Layout discipline: {layout_target}",
            "Brand and asset discipline: every image, icon, chart cue, or decorative asset must earn its place by explaining the message and matching the brand system. Prefer fewer stronger elements over decorative clutter or generic stock filler.",
        ]

    @classmethod
    def _social_media_ad_composition_contract(
        cls,
        *,
        format_name: Any,
        platform: Any,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold()
        normalized_platform = cls._normalize_metadata_text(platform, limit=48) or "social media"
        base = (
            f"Social media ad composition contract for {normalized_platform}: make the image feel like a native feed ad, not a document, slide, report, or template preview. "
            "Use a clean background, one immediate visual hook, strong readable type hierarchy, brand-color restraint, and a CTA treatment that is visible without overpowering the message. "
            "Keep the layout simple, modern, and creative: fewer elements, stronger focal path, no crowded paragraphs, no random icon clutter, and no generic stock-business fallback."
        )
        if normalized_format == "infographic":
            return (
                base
                + " For infographic posts, use a compact social infographic: 3-5 clear modules, icons/charts/diagrams only when they explain the prompt, short labels, clear section rhythm, and enough spacing for mobile readability."
            )
        if normalized_format == "static":
            return (
                base
                + " For static posts, use one bold central message, one supporting line at most, one topic-matched hero visual or metaphor, and one clean CTA button or CTA chip."
            )
        return base

    @classmethod
    def _image_hallucination_control_contract(
        cls,
        *,
        format_name: Any,
        use_backend_text_overlay: bool = False,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold() or "image"
        text_authority = (
            "Backend will place exact text later, so the image model must not create visible wording, numbers, logos, badges, source labels, or pseudo-text."
            if use_backend_text_overlay
            else "For static/infographic creatives, render only content that is present in the current user prompt, approved text payload, retrieved verified facts, live-research facts, or brand context."
        )
        return (
            f"Image hallucination control for {normalized_format}: treat every visible word, number, ranking, chart label, table row, country/company/person/product name, source label, badge, logo-like mark, legal claim, metric, screenshot, and UI detail as a factual claim. "
            "Do not invent, borrow, or carry over any such detail from model memory, previous requests, sample/template content, placeholder examples, or generic social media patterns. "
            "If a detail is unsupported, omit it or replace it with qualitative, non-specific visual language rather than fake specificity. "
            f"{text_authority} "
            "Every visual subject, icon, chart cue, object, and scene must stay tied to the current prompt and approved brand context; never introduce unrelated people, industries, countries, policy themes, template topics, or stale visual metaphors."
        )

    @classmethod
    def _compact_static_infographic_hallucination_guard(
        cls,
        *,
        request: AIOrchestrationRequest | None,
        format_name: Any,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold()
        if normalized_format not in {"static", "infographic"}:
            return ""
        topic_anchors = sorted(cls._final_render_request_topic_tokens(request))[:8] if request is not None else []
        anchors_summary = ", ".join(topic_anchors) if topic_anchors else "the current prompt topic"
        return (
            "Compact hallucination guard / Image hallucination control: treat every visible word, number, ranking, chart label, logo, source, name, metric, and UI detail as factual; each must come only from the prompt, approved copy, verified facts, live research, or brand context. "
            f"Do not invent, borrow, or carry over facts from samples, templates, placeholders, unrelated industries, or model memory; if unsupported, omit it or use qualitative visuals tied to {anchors_summary}. Never invent fake values, stale template topics, placeholders, unrelated industries, or model-memory facts."
        )

    @classmethod
    def _content_visual_explanation_contract(
        cls,
        *,
        request: AIOrchestrationRequest | None,
        format_name: Any,
        platform: Any,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold()
        normalized_platform = cls._normalize_metadata_text(platform, limit=48) or "social media"
        topic_anchors = sorted(cls._final_render_request_topic_tokens(request))[:8]
        anchors_summary = ", ".join(topic_anchors) if topic_anchors else "the current prompt topic"
        base = (
            f"Content + visual explanation contract for {normalized_platform}: the post must explain the topic through both concise readable content and topic-matched imagery. "
            "Use a two-channel composition: text states the idea; visuals show, compare, demonstrate, or symbolize the same idea. "
            "Do not produce a mostly text-only poster, a blank card layout, or a beautiful image with weak token copy. "
            f"Derive the visual metaphor, icons, charts, objects, or diagram logic from these prompt anchors: {anchors_summary}."
        )
        if normalized_format == "infographic":
            return (
                base
                + " For infographic output, pair each major text module with an explanatory visual cue such as an icon, mini chart, flow connector, comparison bar, map-like cue, or diagram shape when it helps the topic; maintain visual hierarchy so the reader can learn by scanning."
            )
        if normalized_format == "static":
            return (
                base
                + " For static output, use one strong hero visual or metaphor, one sharp headline, one short supporting line, and one visible CTA path; the hero visual must carry meaning, not decoration."
            )
        return base

    @classmethod
    def _creative_topic_3d_visual_contract(
        cls,
        *,
        request: AIOrchestrationRequest | None,
        format_name: Any,
        compiled_context: dict[str, Any] | None,
        reference_assets: list[dict[str, Any]] | None = None,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold()
        if normalized_format not in {"static", "infographic"}:
            return ""
        policy = cls._compiled_visual_style_policy(compiled_context, format_name=normalized_format)
        selected_reference_profile = cls._select_reference_visual_profile(
            compiled_context,
            reference_assets=reference_assets,
        )
        policy_three_d_usage = cls._normalize_metadata_text(policy.get("three_d_usage"), limit=24).casefold()
        dominant_image_mode = cls._normalize_metadata_text(policy.get("dominant_image_mode"), limit=24).casefold()
        dominant_depth_mode = cls._normalize_metadata_text(policy.get("dominant_depth_mode"), limit=24).casefold()
        dominant_rendering_mode = cls._normalize_metadata_text(policy.get("dominant_rendering_mode"), limit=24).casefold()
        selected_values = {
            cls._normalize_metadata_text(selected_reference_profile.get("image_mode"), limit=24).casefold(),
            cls._normalize_metadata_text(selected_reference_profile.get("depth_mode"), limit=24).casefold(),
            cls._normalize_metadata_text(selected_reference_profile.get("rendering_mode"), limit=24).casefold(),
        }
        selected_values.discard("")
        selected_reference_is_3d = bool(selected_values & {"3d", "true_3d", "3d_render", "isometric", "2.5d"})
        selected_reference_is_flat_or_photo = bool(
            selected_values
            and not selected_reference_is_3d
            and selected_values & {"flat", "photo", "photo_led", "vector", "2d", "illustration"}
        )
        policy_blocks_3d = (
            policy_three_d_usage == "none"
            or selected_reference_is_flat_or_photo
            or (
                dominant_depth_mode == "flat"
                and dominant_rendering_mode in {"photo", "vector", "illustration"}
                and dominant_image_mode not in {"3d", "isometric"}
            )
        )
        if policy_blocks_3d:
            return ""

        topic_anchors = sorted(cls._final_render_request_topic_tokens(request))[:8] if request is not None else []
        anchors_summary = ", ".join(topic_anchors) if topic_anchors else "the current prompt topic"
        return (
            "Creative topic-specific 3D visual direction: prefer premium 3D/2.5D/isometric topic visuals built from "
            f"{anchors_summary}. Use custom rendered objects, material depth, lighting, and spatial metaphors; "
            "avoid generic coins, arrows, stock dashboards, business portraits, random icon scatter, or unrelated 3D decor."
        )

    @classmethod
    def _final_render_static_infographic_quality_floor_contract(
        cls,
        *,
        request: AIOrchestrationRequest | None,
        format_name: Any,
    ) -> str:
        normalized_format = cls._normalize_metadata_text(format_name, limit=32).casefold()
        if normalized_format not in {"static", "infographic"}:
            return ""
        topic_anchors = sorted(cls._final_render_request_topic_tokens(request))[:8]
        anchors_summary = ", ".join(topic_anchors) if topic_anchors else "the current prompt topic"
        base = (
            "Minimum output quality floor for final static/infographic image: finished premium social creative at thumbnail size and full size; "
            "clear focal path, crisp contrast, deliberate spacing, clean module edges, coherent visual treatment, and at least one topic-specific visual unit tied to "
            f"{anchors_summary}; never blank, text-only, generic-stock, or random-icon output. "
            "Layout discipline: use a simple, scroll-stopping social ad composition."
        )
        if normalized_format == "infographic":
            return (
                base
                + " Infographic floor: show a scannable section rhythm with visible row/card/module structure, paired visual cues, and mobile-readable labels."
            )
        return (
            base
            + " Static floor: show one dominant topic-specific hero concept with concise readable copy support, clear CTA path, and no clutter competing with the main message."
        )

    @classmethod
    def _multimodal_balance_contract(
        cls,
        *,
        format_name: str,
        supporting_line: str = "",
        proof_points: list[str] | None = None,
        claim_evidence_pairs: list[dict[str, str]] | None = None,
        for_visual_only: bool,
    ) -> list[str]:
        normalized_format = str(format_name or "").strip().casefold()
        proof_count = len([item for item in (proof_points or []) if cls._normalize_metadata_text(item, limit=140)])
        claim_count = len(
            [
                pair
                for pair in (claim_evidence_pairs or [])
                if isinstance(pair, dict)
                and (
                    cls._normalize_metadata_text(pair.get("claim"), limit=140)
                    or cls._normalize_metadata_text(pair.get("evidence"), limit=180)
                )
            ]
        )
        has_supporting_line = bool(cls._normalize_metadata_text(supporting_line, limit=220))
        evidence_density = proof_count + claim_count + (1 if has_supporting_line else 0)

        if for_visual_only:
            base = (
                "Premium multimodal balance: build one dominant explanatory visual system with one controlled supporting layer. "
                "Keep enough calm negative space for the approved text regions, and do not let decorative visuals overpower the message."
            )
        elif normalized_format == "carousel":
            base = (
                "Premium multimodal balance: each slide should feel visually led but editorially grounded. "
                "Let the main image or explainer structure carry the concept, while headline, supporting line, and proof modules add only the necessary meaning."
            )
        elif normalized_format == "infographic":
            base = (
                "Premium multimodal balance: make the canvas a true visual explainer, not a text slab and not a decorative poster. "
                "Distribute evidence across modular visual sections with one clear focal path."
            )
        else:
            base = (
                "Premium multimodal balance: keep the creative visually led with concise text support. "
                "Do not turn the layout into either a text-heavy block or an empty hero image with token copy."
            )

        sections = [base]
        if evidence_density >= 4:
            sections.append(
                "Evidence-density rule: because the content carries multiple proof or claim modules, use deliberate evidence containers or callout regions instead of stacking all copy into one dense paragraph block."
            )
        else:
            sections.append(
                "Restraint rule: keep supporting evidence selective and high-signal so the composition stays premium rather than crowded."
            )
        sections.append(
            "Do not duplicate the same message in every modality. The visual should explain something the text does not fully restate, and the text should clarify what the visual implies."
        )
        return sections

    @staticmethod
    def _element_normalized_area(element: Any) -> float:
        geometry = getattr(element, "geometry", None)
        if geometry is None:
            return 0.0
        try:
            width = float(geometry.width if geometry.width is not None else 0.0)
            height = float(geometry.height if geometry.height is not None else 0.0)
        except (TypeError, ValueError):
            return 0.0
        if width <= 0 or height <= 0:
            return 0.0
        units = str(getattr(geometry, "units", "") or "normalized").strip().lower()
        if units == "normalized" or max(abs(width), abs(height)) <= 1.5:
            return max(min(width * height, 1.0), 0.0)
        return 0.0

    @classmethod
    def _scene_graph_text_like_element(cls, element: Any) -> bool:
        role = str(getattr(element, "role", "") or getattr(element, "element_type", "")).strip().lower()
        element_type = str(getattr(element, "element_type", "")).strip().lower()
        return role in {
            "headline",
            "supporting_line",
            "body",
            "proof_points",
            "stat_highlights",
            "cta",
            "section_label",
            "footer",
            "legal",
        } or element_type in {"text", "text_block", "text_group", "headline"}

    @classmethod
    def _multimodal_balance_issue(
        cls,
        scene_graph: GenerationSceneGraph,
        *,
        format_name: str,
    ) -> str:
        normalized_format = str(format_name or "").strip().casefold()
        if normalized_format not in {"static", "carousel", "infographic", "story", "poster"}:
            return ""
        visible_elements = [element for element in scene_graph.elements if element.visible and element.role != "background"]
        if not visible_elements:
            return ""
        text_elements = [element for element in visible_elements if cls._scene_graph_text_like_element(element)]
        image_elements = [element for element in visible_elements if cls._scene_graph_element_is_visual_image_like(element)]
        if not text_elements or not image_elements:
            return ""
        text_area = sum(cls._element_normalized_area(element) for element in text_elements)
        image_area = sum(cls._element_normalized_area(element) for element in image_elements)
        if text_area >= 0.58 and image_area <= 0.18:
            return "text_heavy"
        if len(text_elements) >= 4 and text_area >= 0.32 and image_area <= 0.05:
            return "text_heavy"
        if image_area >= 0.78 and text_area <= 0.1 and len(text_elements) <= 2:
            return "image_heavy"
        return ""

    @classmethod
    def _reference_family_zone_boxes(cls, value: Any, *, limit: int = 10) -> list[dict[str, Any]]:
        zone_boxes: list[dict[str, Any]] = []
        for item in cls._coerce_list(value)[:limit]:
            if not isinstance(item, dict):
                continue
            role = cls._normalize_metadata_text(item.get("role"), limit=32).casefold()
            if not role:
                continue
            try:
                x = float(item.get("x"))
                y = float(item.get("y"))
                w = float(item.get("w") if item.get("w") is not None else item.get("width"))
                h = float(item.get("h") if item.get("h") is not None else item.get("height"))
            except (TypeError, ValueError):
                continue
            if w <= 0 or h <= 0:
                continue
            zone_boxes.append(
                {
                    "role": role,
                    "x": round(x, 3),
                    "y": round(y, 3),
                    "w": round(w, 3),
                    "h": round(h, 3),
                }
            )
        return zone_boxes

    @classmethod
    def _reference_family_zone_role_candidates(cls, role: str) -> list[str]:
        normalized = str(role or "").strip().casefold()
        mapping = {
            "headline": ["headline"],
            "supporting_line": ["supporting_line", "body"],
            "body": ["body", "supporting_line", "proof_points"],
            "proof_points": ["proof_points", "stat_highlights", "body"],
            "stat_highlights": ["stat_highlights", "proof_points"],
            "cta": ["cta", "footer"],
            "footer": ["footer", "cta", "legal"],
            "legal": ["legal", "footer"],
            "logo": ["logo"],
            "image": ["image", "hero_visual", "hero_image", "primary_visual", "illustration"],
            "hero_visual": ["hero_visual", "image", "hero_image", "primary_visual"],
            "hero_image": ["hero_image", "hero_visual", "image", "primary_visual"],
            "primary_visual": ["primary_visual", "hero_visual", "image", "hero_image"],
            "illustration": ["illustration", "primary_visual", "hero_visual", "image"],
        }
        return mapping.get(normalized, [normalized])

    @classmethod
    def _reference_family_role_box(
        cls,
        zone_boxes: list[dict[str, Any]],
        role: str,
        *,
        image_like: bool = False,
    ) -> dict[str, Any]:
        candidates = cls._reference_family_zone_role_candidates(role)
        if image_like:
            candidates = [
                *candidates,
                "hero_visual",
                "hero_image",
                "primary_visual",
                "illustration",
                "image",
            ]
        desired = {candidate for candidate in candidates if candidate}
        for zone in zone_boxes:
            zone_role = str(zone.get("role") or "").strip().casefold()
            if zone_role in desired:
                return zone
        return {}

    @staticmethod
    def _normalized_geometry_iou(current: dict[str, Any], target: dict[str, Any]) -> float:
        try:
            current_x = float(current.get("x"))
            current_y = float(current.get("y"))
            current_w = float(current.get("width") if current.get("width") is not None else current.get("w"))
            current_h = float(current.get("height") if current.get("height") is not None else current.get("h"))
            target_x = float(target.get("x"))
            target_y = float(target.get("y"))
            target_w = float(target.get("width") if target.get("width") is not None else target.get("w"))
            target_h = float(target.get("height") if target.get("height") is not None else target.get("h"))
        except (TypeError, ValueError):
            return 0.0
        if min(current_w, current_h, target_w, target_h) <= 0:
            return 0.0
        intersection_x1 = max(current_x, target_x)
        intersection_y1 = max(current_y, target_y)
        intersection_x2 = min(current_x + current_w, target_x + target_w)
        intersection_y2 = min(current_y + current_h, target_y + target_h)
        intersection_w = max(0.0, intersection_x2 - intersection_x1)
        intersection_h = max(0.0, intersection_y2 - intersection_y1)
        intersection = intersection_w * intersection_h
        if intersection <= 0:
            return 0.0
        current_area = current_w * current_h
        target_area = target_w * target_h
        union = current_area + target_area - intersection
        if union <= 0:
            return 0.0
        return intersection / union

    @classmethod
    def _reference_family_active_slide_profile(
        cls,
        compiled_context: dict[str, Any] | None,
    ) -> dict[str, Any]:
        profile = cls._reference_family_profile(compiled_context)
        slide_profiles = [dict(item) for item in profile.get("slide_profiles", []) if isinstance(item, dict)]
        return slide_profiles[0] if slide_profiles else {}

    @classmethod
    def _apply_reference_family_scene_defaults(
        cls,
        scene_graph_payload: dict[str, Any],
        *,
        compiled_context: dict[str, Any] | None,
    ) -> dict[str, Any]:
        payload = dict(scene_graph_payload or {})
        profile = cls._reference_family_profile(compiled_context)
        slide_profile = cls._reference_family_active_slide_profile(compiled_context) if profile else {}
        zone_boxes = cls._reference_family_zone_boxes(slide_profile.get("zone_boxes") or profile.get("zone_boxes"))
        reference_template_lock = False
        reference_template_layout_type = ""
        if not zone_boxes:
            context = cls._coerce_mapping(compiled_context)
            adaptation_profile = cls._coerce_mapping(context.get("reference_adaptation_profile"))
            source_family = cls._normalize_metadata_text(adaptation_profile.get("source_format_family"), limit=32).casefold()
            output_family = cls._normalize_metadata_text(adaptation_profile.get("output_format_family"), limit=32).casefold()
            if source_family == output_family and output_family in {"static", "infographic"}:
                template_structure = cls._coerce_mapping(adaptation_profile.get("template_structure"))
                sample_page_blueprint = cls._coerce_mapping(template_structure.get("sample_page_blueprint"))
                layout_dna = cls._coerce_mapping(template_structure.get("layout_dna"))
                reference_template_layout_type = (
                    cls._normalize_metadata_text(layout_dna.get("layout_type"), limit=64)
                    or cls._normalize_metadata_text(sample_page_blueprint.get("layout_category"), limit=64)
                )
                zone_boxes = cls._reference_family_zone_boxes(
                    layout_dna.get("zones")
                    or sample_page_blueprint.get("zones")
                    or sample_page_blueprint.get("image_zones")
                )
                reference_template_lock = bool(zone_boxes)
        if not zone_boxes:
            return payload
        lock_strength = cls._normalize_metadata_text(profile.get("layout_lock_strength"), limit=24).casefold()
        if reference_template_lock and lock_strength in {"", "light"}:
            lock_strength = "strong"
        minimum_iou = {"strict": 0.62, "strong": 0.45, "guided": 0.3}.get(lock_strength, 0.0)
        normalized_elements: list[dict[str, Any]] = []
        for element in cls._coerce_list(payload.get("elements")):
            if not isinstance(element, dict):
                normalized_elements.append(element)
                continue
            element_copy = dict(element)
            if not bool(element_copy.get("visible", True)):
                normalized_elements.append(element_copy)
                continue
            role = str(element_copy.get("role") or "").strip().casefold()
            if role == "background":
                normalized_elements.append(element_copy)
                continue
            target_box = cls._reference_family_role_box(
                zone_boxes,
                role,
                image_like=cls._scene_graph_element_is_visual_image_like(element_copy),
            )
            if not target_box:
                normalized_elements.append(element_copy)
                continue
            geometry = cls._coerce_mapping(element_copy.get("geometry"))
            current_iou = cls._normalized_geometry_iou(geometry, target_box) if geometry else 0.0
            if not geometry or current_iou < minimum_iou:
                element_copy["geometry"] = {
                    "x": target_box["x"],
                    "y": target_box["y"],
                    "width": target_box["w"],
                    "height": target_box["h"],
                    "units": "normalized",
                }
            validation_hints = cls._coerce_mapping(element_copy.get("validation_hints"))
            validation_hints.setdefault("reference_zone_role", str(target_box.get("role") or ""))
            validation_hints["reference_family_lock_strength"] = lock_strength or "guided"
            if reference_template_lock:
                validation_hints["reference_template_layout_locked"] = True
            if validation_hints:
                element_copy["validation_hints"] = validation_hints
            normalized_elements.append(element_copy)
        styles = cls._coerce_mapping(payload.get("styles"))
        if not styles.get("layout_archetype"):
            styles["layout_archetype"] = (
                cls._normalize_metadata_text(slide_profile.get("layout_type"), limit=64)
                or next(iter(cls._normalize_metadata_list(profile.get("layout_archetypes"), limit=1)), "")
                or reference_template_layout_type
            )
        styles["reference_family_lock_strength"] = lock_strength or "guided"
        if reference_template_lock:
            styles["reference_template_layout_locked"] = True
        payload["styles"] = styles
        payload["elements"] = normalized_elements
        payload = cls._apply_context_visual_craft_hints(
            payload,
            compiled_context=compiled_context,
        )
        return payload

    @classmethod
    def _apply_sequence_pack_scene_defaults(
        cls,
        scene_graph_payload: dict[str, Any],
        *,
        request: AIOrchestrationRequest | None,
        creative_decision: CreativeDecisionPayload | None,
    ) -> dict[str, Any]:
        payload = dict(scene_graph_payload or {})
        if request is None:
            return payload
        if str(request.studio_panel.get("format") or "").strip().lower() != "carousel":
            return payload
        template_context = request.template_context if isinstance(request.template_context, dict) else {}
        direct_sequence_pack = template_context.get("sequence_pack") if isinstance(template_context.get("sequence_pack"), dict) else {}
        sequence_pack = (
            direct_sequence_pack
            if direct_sequence_pack.get("slides")
            else cls._template_sequence_pack(request, creative_decision=creative_decision)
        )
        if not isinstance(sequence_pack, dict):
            return payload
        surface_policy = cls._normalize_metadata_text(sequence_pack.get("surface_policy"), limit=32).casefold()
        if surface_policy not in {"style_reference_only", "lock_template_surface", "sequence_pack_locked"} and not cls._should_force_sequence_pack(
            request,
            creative_decision=creative_decision,
        ):
            return payload
        sequence_slides = [dict(item) for item in sequence_pack.get("slides", []) if isinstance(item, dict)]
        if not sequence_slides:
            return payload
        active_slide = sequence_slides[0]
        zone_map = cls._coerce_mapping(active_slide.get("zone_map"))
        zone_boxes = cls._reference_family_zone_boxes(zone_map.get("zones"))
        if not zone_boxes:
            return payload
        minimum_iou = {
            "lock_template_surface": 0.7,
            "sequence_pack_locked": 0.7,
            "style_reference_only": 0.5,
        }.get(surface_policy, 0.55)
        normalized_elements: list[dict[str, Any]] = []
        for element in cls._coerce_list(payload.get("elements")):
            if not isinstance(element, dict):
                normalized_elements.append(element)
                continue
            element_copy = dict(element)
            if not bool(element_copy.get("visible", True)):
                normalized_elements.append(element_copy)
                continue
            role = str(element_copy.get("role") or "").strip().casefold()
            if role == "background":
                normalized_elements.append(element_copy)
                continue
            target_box = cls._reference_family_role_box(
                zone_boxes,
                role,
                image_like=cls._scene_graph_element_is_visual_image_like(element_copy),
            )
            if not target_box:
                normalized_elements.append(element_copy)
                continue
            geometry = cls._coerce_mapping(element_copy.get("geometry"))
            current_iou = cls._normalized_geometry_iou(geometry, target_box) if geometry else 0.0
            if not geometry or current_iou < minimum_iou:
                element_copy["geometry"] = {
                    "x": target_box["x"],
                    "y": target_box["y"],
                    "width": target_box["w"],
                    "height": target_box["h"],
                    "units": "normalized",
                }
            validation_hints = cls._coerce_mapping(element_copy.get("validation_hints"))
            validation_hints["reference_zone_role"] = str(target_box.get("role") or "")
            validation_hints["sequence_pack_layout_locked"] = True
            validation_hints["reference_family_lock_strength"] = validation_hints.get("reference_family_lock_strength") or "strong"
            element_copy["validation_hints"] = validation_hints
            normalized_elements.append(element_copy)
        styles = cls._coerce_mapping(payload.get("styles"))
        layout_type = cls._normalize_metadata_text(zone_map.get("layout_type"), limit=64)
        if layout_type:
            styles["layout_archetype"] = layout_type
            styles["layout_type"] = layout_type
        styles["sequence_pack_layout_locked"] = True
        payload["styles"] = styles
        payload["elements"] = normalized_elements
        validation_hints = cls._coerce_mapping(payload.get("validation_hints"))
        validation_hints["sequence_pack_layout_locked"] = True
        validation_hints["template_surface_policy"] = surface_policy or validation_hints.get("template_surface_policy") or ""
        payload["validation_hints"] = validation_hints
        return payload

    @classmethod
    def _context_visual_craft_hints(
        cls,
        compiled_context: dict[str, Any] | None,
    ) -> dict[str, Any]:
        context = cls._coerce_mapping(compiled_context)
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        design_system = cls._coerce_mapping(brand_visual.get("design_system"))
        profile = cls._reference_family_profile(compiled_context)

        visual_craft = cls._coerce_mapping(
            design_system.get("visual_craft")
            or brand_visual.get("visual_craft")
            or profile.get("visual_craft")
        )
        composition_logic = cls._coerce_mapping(
            design_system.get("composition_logic")
            or brand_visual.get("composition_logic")
            or profile.get("composition_logic")
        )
        subject_semantics = cls._coerce_mapping(
            design_system.get("subject_semantics")
            or brand_visual.get("subject_semantics")
            or profile.get("subject_semantics")
        )

        def first_value(mapping: dict[str, Any], *keys: str) -> str:
            for key in keys:
                value = mapping.get(key)
                if isinstance(value, list):
                    value = next((item for item in value if str(item or "").strip()), "")
                text = cls._normalize_metadata_text(value, limit=80).casefold()
                if text:
                    return text
            return ""

        hints: dict[str, Any] = {}
        for target_key, source_keys in {
            "visual_depth_style": ("depth_styles", "depth_style"),
            "visual_rendering_style": ("rendering_styles", "rendering_style"),
            "visual_lighting_mode": ("lighting_modes", "lighting"),
            "visual_polish_level": ("polish_levels", "polish_level"),
            "composition_balance": ("balances", "balance"),
            "composition_framing": ("framings", "framing"),
            "composition_layering": ("layerings", "layering"),
            "subject_scene_type": ("scene_types", "scene_type"),
            "subject_abstraction_level": ("abstraction_levels", "abstraction_level"),
        }.items():
            source_mapping = (
                visual_craft
                if target_key.startswith("visual_")
                else composition_logic
                if target_key.startswith("composition_")
                else subject_semantics
            )
            value = first_value(source_mapping, *source_keys)
            if value:
                hints[target_key] = value

        primary_subjects = cls._normalize_metadata_list(subject_semantics.get("primary_subjects"), limit=4)
        financial_objects = cls._normalize_metadata_list(subject_semantics.get("financial_objects"), limit=4)
        material_cues = cls._normalize_metadata_list(visual_craft.get("material_cues"), limit=4)
        dimensionality_cues = cls._normalize_metadata_list(visual_craft.get("dimensionality_cues"), limit=4)
        if primary_subjects:
            hints["primary_subjects"] = primary_subjects
        if financial_objects:
            hints["financial_objects"] = financial_objects
        if material_cues:
            hints["material_cues"] = material_cues
        if dimensionality_cues:
            hints["dimensionality_cues"] = dimensionality_cues
        return hints

    @classmethod
    def _apply_context_visual_craft_hints(
        cls,
        scene_graph_payload: dict[str, Any],
        *,
        compiled_context: dict[str, Any] | None,
    ) -> dict[str, Any]:
        hints = cls._context_visual_craft_hints(compiled_context)
        if not hints:
            return scene_graph_payload
        payload = dict(scene_graph_payload or {})
        normalized_elements: list[dict[str, Any]] = []
        for element in cls._coerce_list(payload.get("elements")):
            if not isinstance(element, dict):
                normalized_elements.append(element)
                continue
            element_copy = dict(element)
            if cls._scene_graph_element_is_visual_image_like(element_copy):
                validation_hints = cls._coerce_mapping(element_copy.get("validation_hints"))
                for key, value in hints.items():
                    validation_hints.setdefault(key, value)
                element_copy["validation_hints"] = validation_hints
            normalized_elements.append(element_copy)
        payload["elements"] = normalized_elements
        return payload

    @classmethod
    def _reference_family_closeness(
        cls,
        scene_graph: GenerationSceneGraph,
        *,
        compiled_context: dict[str, Any] | None,
    ) -> dict[str, Any]:
        profile = cls._reference_family_profile(compiled_context)
        if not profile:
            return {"score": 1.0, "issues": []}
        slide_profile = cls._reference_family_active_slide_profile(compiled_context)
        zone_boxes = cls._reference_family_zone_boxes(slide_profile.get("zone_boxes") or profile.get("zone_boxes"))
        visible_roles: set[str] = set()
        for element in scene_graph.elements:
            if not element.visible:
                continue
            role = str(element.role or "").strip().casefold()
            if role:
                visible_roles.add(role)
            hint_role = cls._normalize_metadata_text((element.validation_hints or {}).get("reference_zone_role"), limit=32).casefold()
            if hint_role:
                visible_roles.add(hint_role)
            if cls._scene_graph_element_is_visual_image_like(element):
                visible_roles.update({"image", "hero_visual"})
        active_profile = slide_profile or profile
        expected_roles = {
            str(role or "").strip().casefold()
            for role in cls._normalize_metadata_list(
                active_profile.get("zone_roles")
                or active_profile.get("preferred_zone_roles")
                or profile.get("preferred_zone_roles"),
                limit=12,
            )
            if str(role or "").strip()
        }
        expected_image_roles = {
            str(role or "").strip().casefold()
            for role in cls._normalize_metadata_list(
                active_profile.get("approved_image_zone_roles")
                or profile.get("approved_image_zone_roles"),
                limit=6,
            )
            if str(role or "").strip()
        }
        module_patterns = {
            str(role or "").strip().casefold()
            for role in cls._normalize_metadata_list(
                active_profile.get("module_patterns")
                or profile.get("module_patterns"),
                limit=8,
            )
            if str(role or "").strip()
        }
        issues: list[str] = []
        score = 1.0
        if expected_roles:
            overlap = len(expected_roles & visible_roles)
            coverage = overlap / max(len(expected_roles), 1)
            if coverage < 0.55:
                score -= 0.18
                issues.append("reference_family_zone_drift")
            elif coverage < 0.8:
                score -= 0.08
        if expected_image_roles and not (expected_image_roles & visible_roles):
            score -= 0.14
            issues.append("reference_family_image_zone_drift")
        current_archetype = str((scene_graph.styles or {}).get("layout_archetype") or (scene_graph.styles or {}).get("layout_type") or "").strip().casefold()
        target_archetypes = {
            str(item or "").strip().casefold()
            for item in cls._normalize_metadata_list(profile.get("layout_archetypes"), limit=6)
            if str(item or "").strip()
        }
        if current_archetype and target_archetypes and current_archetype not in target_archetypes:
            score -= 0.08
            issues.append("reference_family_layout_drift")
        module_role_map = {
            "cover_hero_split": {"headline", "image", "hero_visual"},
            "proof_grid": {"proof_points", "proof_point", "proof_module"},
            "stat_callout": {"stat_highlights", "stat_highlight"},
            "closing_cta_strip": {"cta", "footer"},
            "comparison_module": {"comparison", "body", "proof_points"},
            "sequence_explainer": {"body", "proof_points", "supporting_line"},
            "icon_label_stack": {"icon", "image"},
        }
        missing_modules = 0
        for pattern in module_patterns:
            expected = module_role_map.get(pattern, set())
            if expected and not (expected & visible_roles):
                missing_modules += 1
        if module_patterns and missing_modules >= max(1, len(module_patterns) // 2):
            score -= 0.12
            issues.append("reference_family_module_drift")
        if zone_boxes:
            geometry_matches = 0
            geometry_scores: list[float] = []
            for zone in zone_boxes[:6]:
                role = str(zone.get("role") or "").strip().casefold()
                if not role:
                    continue
                best_iou = 0.0
                for element in scene_graph.elements:
                    if not element.visible or element.role == "background":
                        continue
                    candidates = {
                        str(element.role or "").strip().casefold(),
                        cls._normalize_metadata_text((element.validation_hints or {}).get("reference_zone_role"), limit=32).casefold(),
                    }
                    if cls._scene_graph_element_is_visual_image_like(element):
                        candidates.update({"image", "hero_visual", "hero_image", "primary_visual", "illustration"})
                    if role not in candidates:
                        continue
                    geometry = element.geometry or SceneGraphGeometry()
                    best_iou = max(
                        best_iou,
                        cls._normalized_geometry_iou(
                            {
                                "x": geometry.x,
                                "y": geometry.y,
                                "width": geometry.width,
                                "height": geometry.height,
                            },
                            zone,
                        ),
                    )
                if best_iou >= 0.45:
                    geometry_matches += 1
                geometry_scores.append(best_iou)
            if geometry_scores:
                average_iou = sum(geometry_scores) / len(geometry_scores)
                if geometry_matches < max(1, min(len(geometry_scores), 2)) or average_iou < 0.34:
                    score -= 0.14
                    issues.append("reference_family_geometry_drift")
        return {"score": max(round(score, 2), 0.0), "issues": issues}

    @classmethod
    def _prompt_sequence_pack(cls, compiled_context: dict[str, Any] | None) -> dict[str, Any]:
        context = dict(compiled_context or {})
        template_fit = cls._coerce_mapping(context.get("template_fit_brief"))
        for candidate in (
            template_fit.get("sequence_pack"),
            template_fit.get("template_sequence_pack"),
            context.get("sequence_pack"),
        ):
            mapping = cls._coerce_mapping(candidate)
            if mapping and (
                mapping.get("slides")
                or mapping.get("family_name")
                or mapping.get("sequence_kind")
                or mapping.get("sequence_cues")
            ):
                return mapping
        return {}

    @classmethod
    def _reference_family_profile(cls, compiled_context: dict[str, Any] | None) -> dict[str, Any]:
        context = dict(compiled_context or {})
        profile = cls._coerce_mapping(context.get("reference_family_profile"))
        return profile if profile else {}

    @classmethod
    def _reference_family_slide_profile(
        cls,
        profile: dict[str, Any],
        slide: dict[str, Any] | None,
    ) -> dict[str, Any]:
        if not isinstance(profile, dict) or not isinstance(slide, dict):
            return {}
        slide_profiles = [dict(item) for item in profile.get("slide_profiles", []) if isinstance(item, dict)]
        if not slide_profiles:
            return {}
        slide_metadata = slide.get("metadata") if isinstance(slide.get("metadata"), dict) else {}
        target_index = cls._int_or_none(slide_metadata.get("reference_slide_index")) or cls._int_or_none(slide.get("slide_index"))
        if target_index is not None:
            for candidate in slide_profiles:
                if cls._int_or_none(candidate.get("slide_index")) == target_index:
                    return candidate
        return slide_profiles[0]

    @classmethod
    def _reference_family_contract_sections(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        slide: dict[str, Any] | None = None,
        for_visual_only: bool,
    ) -> list[str]:
        profile = cls._reference_family_profile(compiled_context)
        if not profile:
            return []
        family_name = cls._normalize_metadata_text(profile.get("family_name"), limit=96)
        format_family = cls._normalize_metadata_text(profile.get("format_family"), limit=24)
        sequence_kind = cls._normalize_metadata_text(profile.get("sequence_kind"), limit=64)
        lock_strength = cls._normalize_metadata_text(profile.get("layout_lock_strength"), limit=24)
        preferred_zone_roles = cls._normalize_metadata_list(profile.get("preferred_zone_roles"), limit=8)
        image_zone_roles = cls._normalize_metadata_list(profile.get("approved_image_zone_roles"), limit=4)
        module_patterns = cls._normalize_metadata_list(profile.get("module_patterns"), limit=6)
        density_target = cls._normalize_metadata_text(profile.get("density_target"), limit=32)
        balance_target = cls._normalize_metadata_text(profile.get("image_text_balance_target"), limit=48)
        spacing_rhythm = cls._normalize_metadata_text(profile.get("spacing_rhythm"), limit=180)
        composition_summary = cls._normalize_metadata_text(profile.get("composition_summary"), limit=180)
        visual_craft_summary = cls._normalize_metadata_text(profile.get("visual_craft_summary"), limit=180)
        subject_summary = cls._normalize_metadata_text(profile.get("subject_semantics_summary"), limit=180)
        sections: list[str] = []
        descriptor = " / ".join(part for part in [family_name, sequence_kind] if part)
        if descriptor:
            sections.append(
                f"Reference family contract: {descriptor}. Treat this as a first-class target, not optional inspiration."
            )
        if lock_strength:
            sections.append(
                f"Reference family layout lock: {lock_strength}. Stay inside the approved family system rather than inventing a fresh layout grammar."
            )
        if preferred_zone_roles:
            sanitized_roles = [r if r != "logo" else "corner_safe_zone" for r in preferred_zone_roles]
            sections.append(f"Reference family zone grammar: {', '.join(sanitized_roles)}.")
        if image_zone_roles:
            sections.append(
                f"Approved image zones only: generated imagery should live inside these family roles only: {', '.join(image_zone_roles)}."
            )
        if module_patterns:
            sections.append(
                f"Reference family module grammar: {', '.join(module_patterns)}. Compose from these approved module types instead of ad-hoc blocks."
            )
        if density_target or balance_target:
            sections.append(
                f"Reference family density target: {density_target or 'balanced'}. Image/text balance target: {balance_target or 'editorial_balanced'}."
            )
        if spacing_rhythm:
            sections.append(f"Reference family spacing rhythm: {spacing_rhythm}.")
        if composition_summary:
            sections.append(f"Reference family composition target: {composition_summary}.")
        if visual_craft_summary:
            sections.append(f"Reference family craft target: {visual_craft_summary}.")
        if subject_summary and not for_visual_only:
            sections.append(f"Reference family subject target: {subject_summary}.")

        slide_profile = cls._reference_family_slide_profile(profile, slide)
        if slide_profile:
            slide_roles = cls._normalize_metadata_list(slide_profile.get("zone_roles"), limit=8)
            slide_image_roles = cls._normalize_metadata_list(slide_profile.get("approved_image_zone_roles"), limit=4)
            slide_patterns = cls._normalize_metadata_list(slide_profile.get("module_patterns"), limit=6)
            slide_headline_hint = cls._normalize_metadata_text(slide_profile.get("headline_hint"), limit=96)
            slide_story_role = cls._normalize_metadata_text(slide_profile.get("story_role"), limit=40)
            if slide_story_role:
                sections.append(f"Reference family slide role target: {slide_story_role}.")
            if slide_headline_hint and not for_visual_only:
                sections.append(f"Reference family slide headline pattern: {slide_headline_hint}.")
            if slide_roles:
                sections.append(f"Reference family slide zone roles: {', '.join(slide_roles)}.")
            if slide_image_roles:
                sections.append(f"Reference family slide image zones: {', '.join(slide_image_roles)}.")
            if slide_patterns:
                sections.append(f"Reference family slide module patterns: {', '.join(slide_patterns)}.")
        elif format_family:
            sections.append(
                f"Reference family format target: {format_family}. Match its native layout behavior rather than a generic social post fallback."
            )
        return sections

    @classmethod
    def _sequence_pack_slide_authority(
        cls,
        sequence_pack: dict[str, Any],
        slide: dict[str, Any] | None,
    ) -> dict[str, Any]:
        if not isinstance(sequence_pack, dict) or not isinstance(slide, dict):
            return {}
        slides = [dict(item) for item in sequence_pack.get("slides", []) if isinstance(item, dict)]
        if not slides:
            return {}
        slide_metadata = slide.get("metadata") if isinstance(slide.get("metadata"), dict) else {}
        target_index = cls._int_or_none(slide_metadata.get("reference_slide_index")) or cls._int_or_none(slide.get("slide_index"))
        target_name = cls._normalize_metadata_text(
            slide_metadata.get("reference_template_name") or slide.get("template_name"),
            limit=96,
        ).casefold()
        if target_index is not None:
            for candidate in slides:
                if cls._int_or_none(candidate.get("slide_index")) == target_index:
                    return candidate
        if target_name:
            for candidate in slides:
                if cls._normalize_metadata_text(candidate.get("template_name"), limit=96).casefold() == target_name:
                    return candidate
        return slides[0]

    @classmethod
    def _sequence_pack_mapping_summary(
        cls,
        value: Any,
        *,
        scalar_keys: tuple[str, ...],
        list_keys: tuple[str, ...],
        limit: int = 6,
        text_limit: int = 200,
    ) -> str:
        mapping = value if isinstance(value, dict) else {}
        parts: list[str] = []
        seen: set[str] = set()
        for key in scalar_keys:
            text = cls._normalize_metadata_text(mapping.get(key), limit=80)
            if text:
                normalized = text.casefold()
                if normalized not in seen:
                    seen.add(normalized)
                    parts.append(text)
            if len(parts) >= limit:
                break
        if len(parts) < limit:
            for key in list_keys:
                for item in cls._normalize_metadata_list(mapping.get(key), limit=limit):
                    normalized = item.casefold()
                    if normalized in seen:
                        continue
                    seen.add(normalized)
                    parts.append(item)
                    if len(parts) >= limit:
                        break
                if len(parts) >= limit:
                    break
        return cls._normalize_metadata_text(", ".join(parts), limit=text_limit)

    @classmethod
    def _sequence_blueprint_alignment_sections(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        slide: dict[str, Any] | None = None,
        for_carousel: bool,
        for_visual_only: bool,
    ) -> list[str]:
        sequence_pack = cls._prompt_sequence_pack(compiled_context)
        if not sequence_pack:
            return []
        family_name = cls._normalize_metadata_text(sequence_pack.get("family_name"), limit=96)
        sequence_kind = cls._normalize_metadata_text(sequence_pack.get("sequence_kind"), limit=64)
        surface_policy = cls._normalize_metadata_text(sequence_pack.get("surface_policy"), limit=32).casefold()
        slide_count = cls._int_or_none(sequence_pack.get("slide_count")) or 0
        story_roles = cls._normalize_metadata_list(sequence_pack.get("story_roles"), limit=8)
        sequence_cues = cls._normalize_metadata_list(sequence_pack.get("sequence_cues"), limit=8)
        headline_hints = cls._normalize_metadata_list(sequence_pack.get("headline_hints"), limit=4)

        sections: list[str] = []
        authority_label = " / ".join(part for part in [family_name, sequence_kind] if part)
        if authority_label or slide_count:
            sections.append(
                f"Sequence blueprint authority: {authority_label or 'approved sample sequence'}"
                f"{f' ({slide_count} slides)' if slide_count else ''}. "
                "This output must feel sample-driven and brand-driven, not like a generic social template."
            )
        if story_roles:
            sections.append(
                f"Sequence narrative rhythm: {' -> '.join(story_roles)}. Preserve this editorial progression in hierarchy, pacing, and information density."
            )
        if sequence_cues:
            sections.append(
                f"Sequence structural cues from the approved sample: {', '.join(sequence_cues)}."
            )
        if headline_hints and not for_visual_only:
            sections.append(
                f"Approved sample headline intents: {', '.join(headline_hints)}. Keep the visual explanation aligned to this level of specificity."
            )
        if surface_policy == "style_reference_only":
            sections.append(
                (
                    "Sample-driven enforcement: use the uploaded sample intelligence as the governing contract for composition, spacing rhythm, negative space, image treatment, and editorial pacing. "
                    "Rebuild the artwork from scratch, but do not downgrade into a generic carousel, infographic, or static social post."
                )
            )

        slide_authority = cls._sequence_pack_slide_authority(sequence_pack, slide)
        if not slide_authority:
            return sections

        reference_index = cls._int_or_none(slide_authority.get("slide_index"))
        story_role = cls._normalize_metadata_text(slide_authority.get("story_role"), limit=48)
        headline_hint = cls._normalize_metadata_text(slide_authority.get("headline_hint"), limit=96)
        structural_cues = cls._normalize_metadata_list(slide_authority.get("structural_cues"), limit=4)
        sequence_summary = cls._normalize_metadata_text(slide_authority.get("sequence_summary"), limit=160)
        zone_map = cls._coerce_mapping(slide_authority.get("zone_map"))
        composition_logic = cls._coerce_mapping(slide_authority.get("composition_logic"))
        visual_craft = cls._coerce_mapping(slide_authority.get("visual_craft"))
        subject_semantics = cls._coerce_mapping(slide_authority.get("subject_semantics"))
        editorial_dna = cls._coerce_mapping(slide_authority.get("editorial_dna"))

        slide_descriptor = []
        if reference_index is not None:
            slide_descriptor.append(f"slide {reference_index}")
        if slide_count:
            slide_descriptor.append(f"of {slide_count}")
        if story_role:
            slide_descriptor.append(f"role {story_role}")
        if slide_descriptor:
            sections.append(
                f"Current sample slide authority: {' '.join(slide_descriptor)}."
            )
        if headline_hint:
            sections.append(
                f"Current sample slide headline intent: {headline_hint}."
            )
        if structural_cues:
            sections.append(
                f"Current sample slide structural cues: {', '.join(structural_cues)}."
            )
        if sequence_summary and not for_visual_only:
            sections.append(
                f"Current sample slide explanation summary: {sequence_summary}."
            )
        layout_type = cls._normalize_metadata_text(zone_map.get("layout_type"), limit=64)
        if layout_type:
            sections.append(
                f"Current sample slide layout type: {layout_type}. Keep the image region, text-safe spacing, and composition balance consistent with this reference logic."
            )
        composition_summary = cls._sequence_pack_mapping_summary(
            composition_logic,
            scalar_keys=("balance", "framing", "layering"),
            list_keys=("depth_cues", "focal_path"),
            limit=6,
            text_limit=180,
        )
        if composition_summary:
            sections.append(f"Current sample slide composition cues: {composition_summary}.")
        visual_craft_summary = cls._sequence_pack_mapping_summary(
            visual_craft,
            scalar_keys=("depth_style", "rendering_style", "lighting", "polish_level"),
            list_keys=("material_cues", "dimensionality_cues"),
            limit=6,
            text_limit=180,
        )
        if visual_craft_summary:
            sections.append(f"Current sample slide craft cues: {visual_craft_summary}.")
        subject_summary = cls._sequence_pack_mapping_summary(
            subject_semantics,
            scalar_keys=("scene_type", "human_presence", "environment", "abstraction_level"),
            list_keys=("primary_subjects", "domain_cues", "financial_objects"),
            limit=7,
            text_limit=200,
        )
        if subject_summary:
            sections.append(f"Current sample slide subject cues: {subject_summary}.")
        editorial_summary = cls._sequence_pack_mapping_summary(
            editorial_dna,
            scalar_keys=("storytelling_mode", "copy_density", "closing_style"),
            list_keys=("story_arc_roles", "headline_patterns", "supporting_patterns", "editorial_signals", "explanation_styles"),
            limit=7,
            text_limit=200,
        )
        if editorial_summary:
            sections.append(f"Current sample slide editorial cues: {editorial_summary}.")
        return sections

    @classmethod
    def _sample_visual_alignment_sections(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        for_carousel: bool,
    ) -> list[str]:
        context = dict(compiled_context or {})
        template_fit = cls._coerce_mapping(context.get("template_fit_brief"))
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        design_system = cls._coerce_mapping(brand_visual.get("design_system"))
        sequence_pack = cls._prompt_sequence_pack(compiled_context)
        layout_dna = cls._coerce_mapping(
            template_fit.get("template_layout_dna")
            or design_system.get("template_layout_dna")
            or design_system.get("layout_dna")
        )
        composition_logic = cls._coerce_mapping(
            template_fit.get("template_composition_logic")
            or design_system.get("template_composition_logic")
            or design_system.get("composition_logic")
        )
        visual_craft = cls._coerce_mapping(
            template_fit.get("template_visual_craft")
            or design_system.get("template_visual_craft")
            or design_system.get("visual_craft")
        )
        subject_semantics = cls._coerce_mapping(
            template_fit.get("template_subject_semantics")
            or design_system.get("template_subject_semantics")
            or design_system.get("subject_semantics")
        )
        editorial_dna = cls._coerce_mapping(
            template_fit.get("template_editorial_dna")
            or design_system.get("template_editorial_dna")
        )

        def _joined_terms(*values: Any, limit: int = 6, text_limit: int = 180) -> str:
            collected: list[str] = []
            seen: set[str] = set()
            for value in values:
                for item in cls._normalize_metadata_list(value, limit=limit):
                    key = item.casefold()
                    if key in seen:
                        continue
                    seen.add(key)
                    collected.append(item)
                    if len(collected) >= limit:
                        break
                if len(collected) >= limit:
                    break
            return cls._normalize_metadata_text(", ".join(collected), limit=text_limit)

        active_authority = cls._normalize_metadata_text(
            template_fit.get("template_name")
            or sequence_pack.get("family_name")
            or design_system.get("dominant_layout_family"),
            limit=96,
        )
        zone_roles = cls._normalize_metadata_list(
            template_fit.get("template_zone_roles")
            or design_system.get("preferred_zone_roles"),
            limit=6,
        )
        hierarchy_summary = cls._normalize_metadata_text(
            design_system.get("hierarchy_summary"),
            limit=180,
        )
        content_structure_summary = cls._normalize_metadata_text(
            design_system.get("content_structure_summary"),
            limit=180,
        )
        visual_craft_summary = cls._normalize_metadata_text(
            design_system.get("visual_craft_summary")
            or _joined_terms(
                visual_craft.get("depth_styles") or visual_craft.get("depth_style"),
                visual_craft.get("rendering_styles") or visual_craft.get("rendering_style"),
                visual_craft.get("lighting_modes") or visual_craft.get("lighting"),
                visual_craft.get("polish_levels") or visual_craft.get("polish_level"),
                visual_craft.get("material_cues"),
                visual_craft.get("dimensionality_cues"),
                limit=7,
            ),
            limit=200,
        )
        composition_summary = cls._normalize_metadata_text(
            design_system.get("composition_logic_summary")
            or _joined_terms(
                composition_logic.get("balances") or composition_logic.get("balance"),
                composition_logic.get("framings") or composition_logic.get("framing"),
                composition_logic.get("layerings") or composition_logic.get("layering"),
                composition_logic.get("depth_cues"),
                composition_logic.get("focal_path"),
            ),
            limit=200,
        )
        subject_summary = cls._normalize_metadata_text(
            design_system.get("subject_semantics_summary")
            or _joined_terms(
                subject_semantics.get("scene_types") or subject_semantics.get("scene_type"),
                subject_semantics.get("primary_subjects"),
                subject_semantics.get("financial_objects"),
                subject_semantics.get("domain_cues"),
                subject_semantics.get("abstraction_levels") or subject_semantics.get("abstraction_level"),
                subject_semantics.get("environment"),
                limit=7,
            ),
            limit=200,
        )
        editorial_summary = cls._normalize_metadata_text(
            design_system.get("editorial_story_arc_summary")
            or design_system.get("editorial_style_summary")
            or _joined_terms(
                editorial_dna.get("story_arc_roles"),
                editorial_dna.get("headline_patterns"),
                editorial_dna.get("supporting_patterns"),
                editorial_dna.get("explanation_styles"),
                editorial_dna.get("storytelling_mode"),
                editorial_dna.get("editorial_signals"),
                editorial_dna.get("closing_style"),
                limit=6,
            ),
            limit=200,
        )
        layout_type = cls._normalize_metadata_text(layout_dna.get("layout_type"), limit=64)
        canvas_ratio = cls._normalize_metadata_text(layout_dna.get("canvas_ratio"), limit=32)

        sections: list[str] = []
        sections.append(
            (
                "Anti-generic rule: do not reduce this slide to a basic hero-left/text-right finance post, a flat 2D vector explainer, a smiling office-worker poster, or an arrow-and-bar-chart composition unless the approved sample explicitly uses that language."
                if for_carousel
                else "Anti-generic rule: do not default to flat 2D vector finance explainers, smiling office workers, isolated coin or plant metaphors, dashboard-tile collages, or rising-arrow hero scenes unless the approved sample explicitly uses that language."
            )
        )
        if active_authority:
            sections.append(
                f"Active sample/template authority: {active_authority}. Match its editorial hierarchy, spacing rhythm, and image-to-text balance instead of inventing a new generic finance layout."
            )
        if layout_type or canvas_ratio:
            descriptor = " ".join(part for part in [layout_type, canvas_ratio] if part).strip()
            sections.append(
                f"Sample layout DNA: {descriptor}. Preserve this composition archetype rather than reverting to a flat generic explainer layout."
            )
        if zone_roles:
            sanitized_roles = [r if r != "logo" else "corner_safe_zone" for r in zone_roles]
            sections.append(
                f"Preferred zone-role rhythm from the selected sample: {', '.join(sanitized_roles)}. Keep these role neighborhoods distinct and do not collapse the slide into one hero-plus-text poster block."
            )
        if hierarchy_summary:
            sections.append(
                f"Sample hierarchy cues: {hierarchy_summary}. Keep the same focal emphasis and whitespace discipline."
            )
        if content_structure_summary:
            sections.append(
                f"Sample content-density cues: {content_structure_summary}. Preserve the same editorial pacing instead of overfilling the canvas."
            )
        if visual_craft_summary:
            sections.append(
                f"Sample visual-craft cues: {visual_craft_summary}. Favor dimensional, premium, editorially polished imagery with controlled depth and material detail when the sample allows it; do not fall back to flat low-detail vector treatment unless the sample is clearly minimal by design."
            )
        if composition_summary:
            sections.append(
                f"Sample composition cues: {composition_summary}. Preserve framing, layering, and negative-space behavior instead of centering one generic finance icon or illustration."
            )
        if subject_summary:
            sections.append(
                f"Sample subject cues: {subject_summary}. Choose topic-specific scenes and objects from this vocabulary instead of generic office workers, random coins, abstract arrows, or dashboard stickers."
            )
        if editorial_summary:
            sections.append(
                f"Sample editorial rhythm: {editorial_summary}. Avoid repeating the same slide composition or generic social-poster formula."
            )
        return [section for section in sections if section]

    @classmethod
    def _compiled_visual_style_policy(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        format_name: str,
    ) -> dict[str, Any]:
        context = dict(compiled_context or {})
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        design_system = cls._coerce_mapping(brand_visual.get("design_system"))
        format_profiles = brand_visual.get("format_visual_style_profiles")
        if not isinstance(format_profiles, dict):
            format_profiles = (
                design_system.get("format_visual_style_profiles")
                if isinstance(design_system.get("format_visual_style_profiles"), dict)
                else {}
            )
        if isinstance(format_profiles, dict):
            format_policy = cls._coerce_mapping(format_profiles.get(str(format_name or "").strip().lower()))
            if format_policy:
                return format_policy
        policy = cls._coerce_mapping(brand_visual.get("visual_style_policy"))
        if policy:
            return policy
        return cls._coerce_mapping(design_system.get("visual_style_policy"))

    @classmethod
    def _compiled_reference_visual_profiles(
        cls,
        compiled_context: dict[str, Any] | None,
    ) -> list[dict[str, Any]]:
        context = dict(compiled_context or {})
        brand_visual = cls._coerce_mapping(context.get("brand_visual_brief"))
        raw_profiles = brand_visual.get("reference_visual_profiles")
        if not isinstance(raw_profiles, list):
            raw_profiles = []
        return [cls._coerce_mapping(item) for item in raw_profiles if isinstance(item, dict)]

    @classmethod
    def _select_reference_visual_profile(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        reference_assets: list[dict[str, Any]] | None = None,
        slide: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        profiles = cls._compiled_reference_visual_profiles(compiled_context)
        if not profiles:
            return {}
        reference_ids = {
            cls._normalize_metadata_text(item.get("asset_id"), limit=96).casefold()
            for item in (reference_assets or [])
            if isinstance(item, dict) and cls._normalize_metadata_text(item.get("asset_id"), limit=96)
        }
        if reference_ids:
            for profile in profiles:
                asset_id = cls._normalize_metadata_text(profile.get("asset_id"), limit=96).casefold()
                if asset_id and asset_id in reference_ids:
                    return profile
        slide_metadata = slide.get("metadata") if isinstance(slide, dict) and isinstance(slide.get("metadata"), dict) else {}
        story_role = cls._normalize_metadata_text(
            (slide_metadata.get("story_role") if isinstance(slide_metadata, dict) else None)
            or (slide.get("role") if isinstance(slide, dict) else None),
            limit=48,
        ).casefold()
        if story_role:
            for profile in profiles:
                profile_role = cls._normalize_metadata_text(profile.get("story_visual_role"), limit=48).casefold()
                if profile_role and profile_role == story_role:
                    return profile
        if len(profiles) == 1:
            return profiles[0]
        return {}

    @classmethod
    def _visual_style_evidence_summary(
        cls,
        mapping: dict[str, Any] | None,
        *,
        policy_mode: bool,
    ) -> str:
        source = cls._coerce_mapping(mapping)
        if not source:
            return ""
        keys = {
            "image mode": "dominant_image_mode" if policy_mode else "image_mode",
            "depth mode": "dominant_depth_mode" if policy_mode else "depth_mode",
            "rendering mode": "dominant_rendering_mode" if policy_mode else "rendering_mode",
            "subject mode": "dominant_subject_mode" if policy_mode else "subject_mode",
            "support mode": "dominant_support_mode" if policy_mode else "support_mode",
        }
        parts: list[str] = []
        for label, key in keys.items():
            value = cls._normalize_metadata_text(source.get(key), limit=32)
            if value:
                parts.append(f"{label} {value}")
        if policy_mode:
            style_consistency = cls._normalize_metadata_text(source.get("style_consistency"), limit=24)
            three_d_usage = cls._normalize_metadata_text(source.get("three_d_usage"), limit=24)
            if style_consistency:
                parts.append(f"style consistency {style_consistency}")
            if three_d_usage:
                parts.append(f"3D usage {three_d_usage}")
        else:
            story_role = cls._normalize_metadata_text(source.get("story_visual_role"), limit=32)
            if story_role:
                parts.append(f"story role {story_role}")
        return "; ".join(parts)

    @classmethod
    def _visual_style_policy_prompt_sections(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        format_name: str,
        reference_assets: list[dict[str, Any]] | None = None,
        slide: dict[str, Any] | None = None,
    ) -> list[str]:
        policy = cls._compiled_visual_style_policy(compiled_context, format_name=format_name)
        if not policy:
            return []
        selected_reference_profile = cls._select_reference_visual_profile(
            compiled_context,
            reference_assets=reference_assets,
            slide=slide,
        )
        reference_priority = cls._normalize_metadata_text(
            policy.get("reference_pattern_priority"),
            limit=32,
        ).casefold()
        dominant_image_mode = cls._normalize_metadata_text(policy.get("dominant_image_mode"), limit=24).casefold()
        dominant_depth_mode = cls._normalize_metadata_text(policy.get("dominant_depth_mode"), limit=24).casefold()
        dominant_rendering_mode = cls._normalize_metadata_text(policy.get("dominant_rendering_mode"), limit=24).casefold()
        style_consistency = cls._normalize_metadata_text(policy.get("style_consistency"), limit=24).casefold()
        three_d_usage = cls._normalize_metadata_text(policy.get("three_d_usage"), limit=24).casefold()
        selected_image_mode = cls._normalize_metadata_text(selected_reference_profile.get("image_mode"), limit=24).casefold()
        selected_depth_mode = cls._normalize_metadata_text(selected_reference_profile.get("depth_mode"), limit=24).casefold()
        selected_rendering_mode = cls._normalize_metadata_text(selected_reference_profile.get("rendering_mode"), limit=24).casefold()
        selected_is_3d = any(
            value in {"3d", "true_3d", "3d_render"}
            for value in [selected_image_mode, selected_depth_mode, selected_rendering_mode]
        )
        sections = [
            "Dynamic visual-style policy: follow the observed brand image language from analyzed carousel/reference samples instead of defaulting to generic 3D, generic flat vector, or unrelated stock styles.",
        ]
        policy_summary = cls._visual_style_evidence_summary(policy, policy_mode=True)
        if policy_summary:
            sections.append(f"Observed brand style evidence: {policy_summary}.")
        if reference_priority == "brand_dominant" and style_consistency in {"strong", "moderate"}:
            sections.append(
                "Brand-dominant execution: stay inside this dominant image family across the generated visual unless the selected reference evidence for this run clearly points elsewhere."
            )
        elif reference_priority == "reference_specific":
            if selected_reference_profile:
                sections.append(
                    "Reference-specific override: this brand uses multiple visual families, so follow the selected reference image pattern for image language, depth, and rendering instead of averaging across all samples."
                )
            else:
                sections.append(
                    "Mixed-style brand rule: this brand uses multiple visual families, so do not hardcode one image treatment; resolve the final image language from the selected reference evidence when available."
                )
        selected_summary = cls._visual_style_evidence_summary(selected_reference_profile, policy_mode=False)
        if selected_summary:
            sections.append(f"Selected reference visual profile: {selected_summary}.")
        if selected_reference_profile:
            if selected_is_3d:
                sections.append(
                    "Selected-reference execution: keep this run inside the chosen dimensional family and do not flatten it into a generic photo-led or flat vector scene."
                )
            else:
                sections.append(
                    "Selected-reference execution: keep this run inside the chosen photo-led or flatter family and do not force 3D or isometric rendering."
                )
        elif three_d_usage == "none":
            sections.append(
                "3D restraint: do not force 3D, isometric, or rendered object scenes when the analyzed brand/reference samples are primarily photo-led or flat."
            )
        elif three_d_usage == "often" or any(
            value in {"3d", "true_3d", "3d_render"}
            for value in [dominant_image_mode, dominant_depth_mode, dominant_rendering_mode]
        ):
            sections.append(
                "3D execution: the analyzed brand/reference samples regularly use true 3D or dimensional rendering, so preserve that depth language instead of flattening the scene into generic 2D artwork."
            )
        elif three_d_usage == "sometimes":
            sections.append(
                "Conditional 3D rule: use 3D or dimensional rendering only when the selected reference or slide-specific evidence points there; do not force it onto every slide or brand."
            )
        if not selected_reference_profile and dominant_depth_mode == "flat" and dominant_rendering_mode in {"photo", "vector"}:
            sections.append(
                "Flat-style guardrail: preserve the brand's flatter or photo-led image treatment and do not inject artificial pseudo-3D depth unless the selected reference evidence clearly supports it."
            )
        return [section for section in sections if section]

    @classmethod
    def _should_ignore_scene_graph_for_final_render(
        cls,
        *,
        generation_path: str,
        fresh_replan_attempted: bool,
        validation_report: SceneGraphValidationReport,
        scene_graph: GenerationSceneGraph,
        compiled_context: dict[str, Any] | None = None,
        style_reference_final_render_active: bool = False,
    ) -> bool:
        if generation_path == "image_led_social" and style_reference_final_render_active:
            return True
        return (
            generation_path == "image_led_social"
            and fresh_replan_attempted
            and cls._should_request_fresh_replan(validation_report)
            and not cls._scene_graph_has_authoritative_geometry(scene_graph)
            and not cls._compiled_context_has_authoritative_layout(compiled_context)
        )

    @staticmethod
    def _final_render_ignore_note(validation_report: SceneGraphValidationReport) -> str:
        issues = [str(issue.rule_id or "").strip() for issue in validation_report.issues if str(issue.rule_id or "").strip()]
        if not issues:
            return (
                "Ignore the prior weak scene graph because it lacked enough usable geometry. Rebuild the composition around the extracted sample layout skeleton, "
                "brand system, and scene-safe geometry contract instead of improvising a new composition."
            )
        return (
            "Ignore the prior weak scene graph because it lacked enough usable geometry. Rebuild the composition around the extracted sample layout skeleton, "
            "brand system, and scene-safe geometry contract instead of improvising a new composition. "
            f"Do not repeat these failed planning traits: {', '.join(issues)}."
        )

    @staticmethod
    def _coerce_mapping(value: Any) -> dict[str, Any]:
        if isinstance(value, dict):
            return dict(value)
        if value is None:
            return {}
        if isinstance(value, (list, tuple, set)):
            merged: dict[str, Any] = {}
            text_items: list[str] = []
            for item in value:
                if isinstance(item, dict):
                    merged.update(item)
                else:
                    text = str(item).strip()
                    if text:
                        text_items.append(text)
            if merged:
                if text_items:
                    merged.setdefault("notes", "; ".join(text_items[:8]))
                return merged
            if text_items:
                return {"notes": "; ".join(text_items[:8])}
            return {}
        text = str(value).strip()
        return {"notes": text} if text else {}

    @staticmethod
    def _coerce_list(value: Any) -> list[Any]:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        if isinstance(value, set):
            return list(value)
        return [value]

    @staticmethod
    def _normalize_trace_payload(payload: Any) -> Any:
        if isinstance(payload, str):
            return AIOrchestratorService._repair_common_mojibake(payload)
        if isinstance(payload, dict):
            return {
                key: AIOrchestratorService._normalize_trace_payload(value)
                for key, value in payload.items()
            }
        if isinstance(payload, list):
            return [AIOrchestratorService._normalize_trace_payload(value) for value in payload]
        if isinstance(payload, tuple):
            return [AIOrchestratorService._normalize_trace_payload(value) for value in payload]
        return payload

    @staticmethod
    def _trace_payload(trace_id: str | None, tracer: GenerationTraceService, filename: str, payload: Any) -> None:
        tracer.write_payload(
            trace_id,
            filename,
            AIOrchestratorService._normalize_trace_payload(payload),
        )

    @staticmethod
    def _trace_event(trace_id: str | None, tracer: GenerationTraceService, event: str, payload: Any | None = None) -> None:
        tracer.append_event(trace_id, event, payload)

    @classmethod
    def _compiled_font_families(cls, compiled_context: dict[str, Any]) -> list[str]:
        families: list[str] = []
        for item in (compiled_context.get("brand_visual_brief", {}) or {}).get("font_families", []) or []:
            normalized = cls._normalize_metadata_text(item, limit=64)
            if normalized and normalized not in families:
                families.append(normalized)
        return families

    @classmethod
    def _extract_font_sizes_from_brand_context(cls, brand_context: dict[str, Any]) -> dict[str, int]:
        """Extract font sizes from analyzed reference samples (typography_dna)"""
        # Default font sizes (fallback if not extracted)
        defaults = {
            "headline": 58,
            "subheading": 36,
            "body": 24,
            "caption": 16,
            "footer": 8
        }

        # Try to extract from reference creatives' typography_dna
        visual_identity = brand_context.get("visual_identity", {})
        reference_creatives = visual_identity.get("reference_creatives", [])

        for reference in reference_creatives:
            style_chars = reference.get("style_characteristics", {})
            typography_dna = style_chars.get("typography_dna", {})
            font_size_palette = typography_dna.get("font_size_palette", {})

            if font_size_palette:
                # Found font size palette from vision analysis!
                return {
                    "headline": int(font_size_palette.get("headline_pt", defaults["headline"])),
                    "subheading": int(font_size_palette.get("subheading_pt", defaults["subheading"])),
                    "body": int(font_size_palette.get("body_pt", defaults["body"])),
                    "caption": int(font_size_palette.get("caption_pt", defaults["caption"])),
                    "footer": int(font_size_palette.get("footer_pt", defaults["footer"]))
                }

        # Fallback to defaults if not found in references
        return defaults

    @classmethod
    def _extract_layout_dna_from_brand_context(cls, brand_context: dict[str, Any], format_hint: str) -> dict[str, Any] | None:
        """Extract layout DNA from reference creatives"""
        visual_identity = brand_context.get("visual_identity", {})
        reference_creatives = visual_identity.get("reference_creatives", [])

        for reference in reference_creatives:
            layout_structure = reference.get("layout_structure", {})
            dna = layout_structure.get("layout_dna")
            if dna and dna.get("zones"):
                return dna

        return None

    @classmethod
    def _extract_layout_dna_from_compiled_context(cls, compiled_context: dict[str, Any], format_hint: str) -> dict[str, Any] | None:
        brand_visual_brief = compiled_context.get("brand_visual_brief", {}) if isinstance(compiled_context, dict) else {}
        template_fit_brief = compiled_context.get("template_fit_brief", {}) if isinstance(compiled_context, dict) else {}
        candidates = [
            (template_fit_brief.get("template_layout_dna") if isinstance(template_fit_brief, dict) else {}),
            (brand_visual_brief.get("template_layout_dna") if isinstance(brand_visual_brief, dict) else {}),
            (
                ((brand_visual_brief.get("design_system") or {}).get("template_layout_dna"))
                if isinstance((brand_visual_brief.get("design_system") if isinstance(brand_visual_brief, dict) else {}), dict)
                else {}
            ),
        ]
        for candidate in candidates:
            if isinstance(candidate, dict) and candidate.get("zones"):
                return candidate
        return None

    @classmethod
    def _build_profile_from_layout_dna(cls, layout_dna: dict[str, Any], layout_type: str, format_name: str) -> dict[str, Any]:
        """Build layout profile from extracted layout DNA"""
        raw_zones = layout_dna.get("zones", {})
        spacing = layout_dna.get("spacing", {})
        zones: dict[str, dict[str, Any]] = {}

        if isinstance(raw_zones, dict):
            for role_name, zone in raw_zones.items():
                if not isinstance(zone, dict):
                    continue
                normalized = zone.get("normalized") if isinstance(zone.get("normalized"), dict) else {}
                zone_copy = dict(zone)
                zone_copy.setdefault("role", str(role_name))
                if normalized:
                    zone_copy["normalized"] = normalized
                elif all(zone.get(key) is not None for key in ("x", "y", "w", "h")):
                    zone_copy["normalized"] = {
                        "x": zone.get("x"),
                        "y": zone.get("y"),
                        "w": zone.get("w"),
                        "h": zone.get("h"),
                    }
                zones[str(role_name)] = zone_copy
        elif isinstance(raw_zones, list):
            for zone in raw_zones:
                if not isinstance(zone, dict):
                    continue
                role_name = str(zone.get("role") or zone.get("zone_role") or "").strip()
                if not role_name:
                    continue
                normalized = zone.get("normalized") if isinstance(zone.get("normalized"), dict) else {}
                zone_copy = dict(zone)
                zone_copy.setdefault("role", role_name)
                if normalized:
                    zone_copy["normalized"] = normalized
                elif all(zone.get(key) is not None for key in ("x", "y", "w", "h")):
                    zone_copy["normalized"] = {
                        "x": zone.get("x"),
                        "y": zone.get("y"),
                        "w": zone.get("w"),
                        "h": zone.get("h"),
                    }
                elif all(zone.get(key) is not None for key in ("x", "y", "width", "height")):
                    zone_copy["normalized"] = {
                        "x": zone.get("x"),
                        "y": zone.get("y"),
                        "w": zone.get("width"),
                        "h": zone.get("height"),
                    }
                zones[role_name] = zone_copy

        profile = {
            "layout_type": layout_type,
            "layout_archetype": cls._sanitize_scene_element_name(
                str(layout_dna.get("layout_type") or "extracted_from_sample")
            ) or "extracted_from_sample",
        }

        # Map zone roles to profile keys
        role_mapping = {
            "headline": "headline",
            "supporting_line": "supporting_line",
            "body": "supporting_line",
            "proof_points": "proof_points",
            "stat_highlights": "proof_points",
            "image": "hero_image",
            "hero_visual": "hero_image",
            "hero_image": "hero_image",
            "primary_visual": "hero_image",
            "logo": "logo",
            "cta": "cta",
        }

        for zone_role, profile_key in role_mapping.items():
            zone = zones.get(zone_role)
            if zone:
                normalized = zone.get("normalized", {})
                profile[profile_key] = cls._normalized_box(
                    normalized.get("x", 0),
                    normalized.get("y", 0),
                    normalized.get("w", 1),
                    normalized.get("h", 0.1)
                )

        content_boxes: list[dict[str, float]] = []
        for role_name, zone in zones.items():
            if not isinstance(zone, dict):
                continue
            normalized = zone.get("normalized", {}) if isinstance(zone.get("normalized"), dict) else {}
            if role_name in {"image", "logo"}:
                continue
            if all(isinstance(normalized.get(key), (int, float)) for key in ("x", "y", "w", "h")):
                content_boxes.append(normalized)
        if content_boxes:
            min_x = min(float(box.get("x") or 0.0) for box in content_boxes)
            min_y = min(float(box.get("y") or 0.0) for box in content_boxes)
            max_x = max(float(box.get("x") or 0.0) + float(box.get("w") or 0.0) for box in content_boxes)
            max_y = max(float(box.get("y") or 0.0) + float(box.get("h") or 0.0) for box in content_boxes)
            pad_x = float(spacing.get("x_padding") or spacing.get("padding_x") or 0.03)
            pad_y = float(spacing.get("y_padding") or spacing.get("padding_y") or 0.03)
            profile["overlay_panel"] = cls._normalized_box(
                max(min_x - pad_x, 0.0),
                max(min_y - pad_y, 0.0),
                min(max_x - min_x + pad_x * 2, 0.96),
                min(max_y - min_y + pad_y * 2, 0.96),
            )

        # Add proof_points fallback if body zone exists (typically below supporting line)
        if "proof_points" not in profile and "body" in zones:
            body_zone = zones["body"]
            normalized = body_zone.get("normalized", {})
            y_start = normalized.get("y", 0) + normalized.get("h", 0) + 0.05
            profile["proof_points"] = cls._normalized_box(0.08, y_start, 0.84, 0.3)

        overlay_panel = profile.get("overlay_panel") if isinstance(profile.get("overlay_panel"), dict) else {}
        if overlay_panel:
            panel_x = float(overlay_panel.get("x") or 0.05)
            panel_y = float(overlay_panel.get("y") or 0.08)
            panel_w = float(overlay_panel.get("width") or 0.84)
            panel_h = float(overlay_panel.get("height") or 0.76)
        else:
            panel_x, panel_y, panel_w, panel_h = 0.05, 0.08, 0.84, 0.76

        if "headline" not in profile:
            profile["headline"] = cls._normalized_box(panel_x, panel_y, min(panel_w, 0.62), 0.12)
        headline_box = profile.get("headline") if isinstance(profile.get("headline"), dict) else cls._normalized_box(panel_x, panel_y, min(panel_w, 0.62), 0.12)
        headline_y_end = float(headline_box.get("y") or panel_y) + float(headline_box.get("height") or 0.12)

        if "supporting_line" not in profile:
            profile["supporting_line"] = cls._normalized_box(
                panel_x,
                min(headline_y_end + 0.04, 0.86),
                min(panel_w, 0.72),
                0.1,
            )
        supporting_box = profile.get("supporting_line") if isinstance(profile.get("supporting_line"), dict) else {}
        supporting_y_end = float(supporting_box.get("y") or headline_y_end) + float(supporting_box.get("height") or 0.1)

        if "proof_points" not in profile:
            profile["proof_points"] = cls._normalized_box(
                panel_x,
                min(supporting_y_end + 0.04, 0.88),
                min(panel_w, 0.78),
                min(max(panel_h - (supporting_y_end - panel_y) - 0.18, 0.12), 0.24),
            )
        if "cta" not in profile:
            proof_box = profile.get("proof_points") if isinstance(profile.get("proof_points"), dict) else {}
            proof_y_end = float(proof_box.get("y") or supporting_y_end) + float(proof_box.get("height") or 0.16)
            profile["cta"] = cls._normalized_box(
                panel_x,
                min(proof_y_end + 0.04, 0.9),
                min(panel_w * 0.45, 0.34),
                0.08,
            )
        if "logo" not in profile:
            profile["logo"] = cls._normalized_box(min(panel_x + panel_w - 0.18, 0.78), max(panel_y - 0.04, 0.04), 0.16, 0.06)
        if "hero_image" not in profile:
            profile["hero_image"] = cls._normalized_box(min(panel_x + panel_w + 0.03, 0.56), 0.12, 0.32, 0.34)
        if "overlay_panel" not in profile:
            profile["overlay_panel"] = cls._normalized_box(panel_x, panel_y, panel_w, panel_h)

        return profile

    @staticmethod
    def _default_font_role_for_role(role: str) -> str:
        normalized = str(role or "").strip().lower()
        if normalized == "headline":
            return "heading_sans"
        if normalized == "cta":
            return "cta_sans"
        if normalized in {"footer", "legal"}:
            return "caption_sans"
        return "body_sans"

    @classmethod
    def _normalize_text_style_for_brand(
        cls,
        style: dict[str, Any],
        *,
        role: str,
        allowed_font_families: list[str],
        validation_hints: dict[str, Any],
    ) -> dict[str, Any]:
        normalized = dict(style or {})
        requested_family = str(
            normalized.get("font_family")
            or normalized.get("family")
            or normalized.get("fontFamily")
            or ""
        ).strip()
        normalized["font_role"] = str(normalized.get("font_role") or cls._default_font_role_for_role(role)).strip()
        if not requested_family:
            normalized.pop("font_family", None)
            return normalized
        validation_hints.setdefault("font_family_requested", requested_family)
        matched = next(
            (family for family in allowed_font_families if family.casefold() == requested_family.casefold()),
            None,
        )
        if matched:
            normalized["font_family"] = matched
            validation_hints["font_family_resolved"] = matched
            return normalized
        if allowed_font_families:
            normalized["font_family"] = allowed_font_families[0]
            validation_hints["font_family_resolved"] = allowed_font_families[0]
            validation_hints["font_family_normalized_from"] = requested_family
            return normalized
        normalized.pop("font_family", None)
        validation_hints["font_family_strategy"] = "renderer_fallback"
        return normalized

    @staticmethod
    def _major_asset_strategy_flags(asset_strategy: dict[str, Any]) -> dict[str, bool]:
        strategy = asset_strategy or {}
        return {
            "generated_image": bool(strategy.get("use_generated_image")),
            "template_background": bool(strategy.get("use_template_background")),
            "reference_assets": bool(strategy.get("use_brand_reference_assets")),
            "icon_sequence": bool(strategy.get("icon_sequence")),
        }

    @staticmethod
    def _normalized_dominant_visual_system(asset_strategy: dict[str, Any]) -> str:
        value = str((asset_strategy or {}).get("dominant_visual_system") or "").strip().lower()
        aliases = {
            "image_led": "generated_image",
            "generated_image": "generated_image",
            "hero_image": "generated_image",
            "template_led": "template_background",
            "exact_template": "template_background",
            "adapted_template": "template_background",
            "template_background": "template_background",
            "asset_led": "reference_assets",
            "reference_led": "reference_assets",
            "reference_assets": "reference_assets",
            "icon_led": "icon_sequence",
            "icon_sequence": "icon_sequence",
            "type_led": "type_led",
        }
        return aliases.get(value, value or "")

    @staticmethod
    def _normalized_supporting_visual_system(asset_strategy: dict[str, Any]) -> str:
        value = str(
            (asset_strategy or {}).get("supporting_visual_system")
            or (asset_strategy or {}).get("type_led_supporting_system")
            or ""
        ).strip().lower()
        aliases = {
            "iconography": "icon_sequence",
            "icons": "icon_sequence",
            "icon_led": "icon_sequence",
            "icon_sequence": "icon_sequence",
            "reference_assets": "reference_assets",
            "reference_led": "reference_assets",
            "asset_led": "reference_assets",
        }
        return aliases.get(value, value or "")

    @staticmethod
    def _visual_explanation_plan(
        request: AIOrchestrationRequest,
        text_payload: Any,
        creative_decision: CreativeDecisionPayload | None = None,
        reference_images: list[dict[str, Any]] | None = None,
        message_strategy: MessageStrategyPayload | None = None,
    ) -> dict[str, str]:
        metadata = getattr(text_payload, "metadata", None)
        metadata = metadata if isinstance(metadata, dict) else {}
        strategy_payload = message_strategy.model_dump(mode="json") if isinstance(message_strategy, MessageStrategyPayload) else {}
        asset_strategy = (creative_decision.asset_strategy if isinstance(creative_decision, CreativeDecisionPayload) else {}) or {}
        format_name = str((getattr(request, "studio_panel", {}) or {}).get("format") or "static").strip().lower()
        text = " ".join(
            AIOrchestratorService._coerce_text_value(part)
            for part in [
                getattr(request, "prompt", ""),
                getattr(text_payload, "headline", ""),
                getattr(text_payload, "body", ""),
                getattr(text_payload, "cta", ""),
                metadata.get("supporting_line"),
                metadata.get("visual_direction"),
                metadata.get("image_prompt"),
                metadata.get("proof_points"),
                metadata.get("stat_highlights"),
                strategy_payload.get("primary_campaign_theme"),
                strategy_payload.get("core_audience_message"),
                strategy_payload.get("important_keywords"),
            ]
            if AIOrchestratorService._coerce_text_value(part)
        ).casefold()
        proof_points = AIOrchestratorService._normalize_metadata_list(metadata.get("proof_points"), limit=6)
        supporting_visual_system = AIOrchestratorService._normalized_supporting_visual_system(asset_strategy)
        has_reference_images = bool(reference_images)
        user_explicit_data_visual_request = AIOrchestratorService._has_explicit_data_visual_request(
            getattr(request, "prompt", ""),
            text_payload=None,
        )
        explicit_data_visual_request = AIOrchestratorService._has_explicit_data_visual_request(
            getattr(request, "prompt", ""),
            text_payload=text_payload,
        )
        template_surface_policy = AIOrchestratorService._effective_template_surface_policy(
            request,
            creative_decision=creative_decision,
            metadata=metadata,
        )

        beginner_terms = (
            "first-time",
            "first time",
            "beginner",
            "beginners",
            "new investor",
            "new investors",
            "approachable",
            "easy start",
            "getting started",
            "start investing",
            "guided",
            "onboarding",
            "entry point",
            "entry-level",
            "simple access",
            "market is approachable",
            "free market is approachable",
        )
        process_terms = (
            "tips",
            "checklist",
            "steps",
            "step-by-step",
            "how to",
            "strategy",
            "strategies",
            "playbook",
            "roadmap",
            "journey",
            "process",
            "guide",
        )
        comparison_terms = (
            "compare",
            "comparison",
            "versus",
            " vs ",
            "before and after",
            "before/after",
            "confusion to clarity",
            "risk return",
            "risk-return",
            "risk and return",
            "old vs new",
            "trade-off",
            "tradeoff",
        )
        data_terms = (
            "market trend",
            "market trends",
            "trend",
            "trends",
            "graph",
            "chart",
            "data",
            "metric",
            "metrics",
            "percentage",
            "%",
        )

        def has_term(term: str) -> bool:
            normalized = term.strip().casefold()
            if not normalized:
                return False
            if normalized == "%":
                return "%" in text
            return bool(re.search(rf"(?<![a-z0-9]){re.escape(normalized)}(?![a-z0-9])", text))

        def has_any(terms: tuple[str, ...]) -> bool:
            return any(has_term(term) for term in terms)

        if (
            template_surface_policy == "style_reference_only"
            and has_reference_images
            and not user_explicit_data_visual_request
        ):
            return {
                "mode": "sample_page_adaptation",
                "need": "high",
                "density": "match_sample",
                "rationale": "Selected sample page controls visual structure; do not infer charts or generic finance modules from numeric facts alone.",
            }
        if has_any(beginner_terms):
            return {
                "mode": "beginner_path",
                "need": "high",
                "density": "medium",
                "rationale": "Prompt asks for first-time, approachable, or guided-entry understanding.",
            }
        if has_any(comparison_terms):
            return {
                "mode": "comparison",
                "need": "medium",
                "density": "low" if format_name == "static" else "medium",
                "rationale": "Message benefits from a clear contrast or before-after transformation.",
            }
        if explicit_data_visual_request or has_any(data_terms):
            return {
                "mode": "data_cue",
                "need": "high" if format_name == "infographic" else "medium",
                "density": "medium" if format_name != "infographic" else "high",
                "rationale": "Message explicitly asks for chart-worthy information, numeric visualization, or diagrammatic evidence.",
            }
        if has_any(process_terms):
            return {
                "mode": "process_steps",
                "need": "high",
                "density": "medium",
                "rationale": "Message is instructional and should read visually as a simple sequence.",
            }
        if format_name in {"carousel", "infographic"} or supporting_visual_system == "icon_sequence":
            return {
                "mode": "icon_support",
                "need": "medium",
                "density": "low" if format_name == "static" else "medium",
                "rationale": "Format or proof points can benefit from restrained supporting symbols without a full diagram.",
            }
        if has_reference_images:
            return {
                "mode": "minimal_brand_scene",
                "need": "low",
                "density": "low",
                "rationale": "Reference assets can provide style while the message does not require extra explanation.",
            }
        return {
            "mode": "minimal_brand_scene",
            "need": "low",
            "density": "low",
            "rationale": "Message can be served by a clean brand scene without forced explanatory devices.",
        }

    @staticmethod
    def _has_explicit_data_visual_request(
        prompt: str,
        *,
        text_payload: StructuredTextPayload | None = None,
    ) -> bool:
        metadata = (text_payload.metadata or {}) if isinstance(text_payload, StructuredTextPayload) else {}
        combined = " ".join(
            part
            for part in [
                AIOrchestratorService._coerce_text_value(prompt),
                AIOrchestratorService._coerce_text_value(getattr(text_payload, "headline", "") if text_payload else ""),
                AIOrchestratorService._coerce_text_value(getattr(text_payload, "body", "") if text_payload else ""),
                AIOrchestratorService._coerce_text_value(metadata.get("supporting_line")),
                AIOrchestratorService._coerce_text_value(metadata.get("proof_points")),
                AIOrchestratorService._coerce_text_value(metadata.get("stat_highlights")),
            ]
            if AIOrchestratorService._coerce_text_value(part)
        ).casefold()
        if not combined:
            return False
        explicit_visual_terms = (
            "bar chart",
            "bar graph",
            "line chart",
            "line graph",
            "pie chart",
            "donut chart",
            "area chart",
            "graph",
            "chart",
            "timeline",
            "diagram",
            "visualization",
            "data viz",
            "infographic",
            "table",
            "matrix",
            "checklist",
            "step-by-step",
            "steps",
            "process",
            "flow",
        )
        def contains_explicit_visual_term(term: str) -> bool:
            normalized = term.strip().casefold()
            if not normalized:
                return False
            return bool(re.search(rf"(?<![a-z0-9]){re.escape(normalized)}(?![a-z0-9])", combined))

        if any(contains_explicit_visual_term(term) for term in explicit_visual_terms):
            return True
        if re.search(r"\b\d{4}\b", combined) and re.search(r"\b(chart|graph|trend|timeline|growth|decline|increase|decrease)\b", combined):
            return True
        if "%" in combined and re.search(r"\b(chart|graph|compare|comparison|trend|data|metric)\b", combined):
            return True
        return False

    @classmethod
    def _infographic_surface_intent(
        cls,
        *,
        prompt: Any,
        format_name: str,
        visual_plan: dict[str, Any] | None = None,
    ) -> bool:
        if str(format_name or "").strip().casefold() != "infographic":
            return False
        text = cls._normalize_metadata_text(prompt, limit=720).casefold()
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        mode = cls._normalize_metadata_text(plan.get("mode"), limit=40).casefold()
        if mode in {"comparison", "data_cue", "process_steps"}:
            return True
        if cls._has_explicit_data_visual_request(text, text_payload=None):
            return True
        return bool(
            re.search(
                r"\b(top\s+\d{1,2}|rank(?:ed|ing)?|compar(?:e|ing|ison)|versus|vs\.?|by\s+[a-z0-9 -]{2,80})\b",
                text,
                flags=re.IGNORECASE,
            )
        )

    @classmethod
    def _explicit_top_n_item_count(cls, *values: Any) -> int | None:
        text = cls._normalize_metadata_text(" ".join(cls._coerce_text_value(value) for value in values), limit=900)
        if not text:
            return None
        match = re.search(r"\btop\s+(\d{1,2})\b", text, flags=re.IGNORECASE)
        if not match:
            return None
        try:
            value = int(match.group(1))
        except (TypeError, ValueError):
            return None
        return value if 1 <= value <= 20 else None

    @classmethod
    def _data_list_surface_available_count(cls, metadata: Any) -> int:
        if not isinstance(metadata, dict):
            return 0
        counts = [
            cls._rough_collection_length(metadata.get("proof_points")),
            cls._rough_collection_length(metadata.get("stat_highlights")),
            cls._rough_collection_length(metadata.get("claim_evidence_pairs")),
        ]
        static_panel_spec = metadata.get("static_panel_spec")
        if isinstance(static_panel_spec, dict):
            counts.extend(
                [
                    cls._rough_collection_length(static_panel_spec.get("proof_points")),
                    cls._rough_collection_length(static_panel_spec.get("stat_highlights")),
                    cls._rough_collection_length(static_panel_spec.get("claim_evidence_pairs")),
                ]
            )
        infographic_sections = metadata.get("infographic_section_specs")
        if isinstance(infographic_sections, list):
            valid_sections = [section for section in infographic_sections if isinstance(section, dict)]
            counts.append(len(valid_sections))
            for section in valid_sections:
                counts.extend(
                    [
                        cls._rough_collection_length(section.get("body_points")),
                        cls._rough_collection_length(section.get("proof_points")),
                        cls._rough_collection_length(section.get("stat_highlights")),
                        cls._rough_collection_length(section.get("claim_evidence_pairs")),
                    ]
                )
        return max(counts or [0])

    @classmethod
    def _data_list_surface_intent(
        cls,
        *,
        prompt: Any,
        format_name: str,
        metadata: dict[str, Any] | None = None,
        text_payload: StructuredTextPayload | None = None,
        visual_plan: dict[str, Any] | None = None,
    ) -> bool:
        normalized_format = str(format_name or "").strip().casefold()
        if normalized_format not in {"static", "infographic"}:
            return False
        metadata = metadata if isinstance(metadata, dict) else {}
        if cls._explicit_top_n_item_count(prompt, metadata):
            return True
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        mode = cls._normalize_metadata_text(plan.get("mode"), limit=40).casefold()
        if mode in {"comparison", "data_cue", "process_steps"}:
            return True
        if cls._has_explicit_data_visual_request(str(prompt or ""), text_payload=text_payload):
            return True
        combined = " ".join(
            cls._coerce_text_value(value)
            for value in (
                prompt,
                metadata.get("panel_goal"),
                metadata.get("visual_focus"),
                metadata.get("proof_points"),
                metadata.get("stat_highlights"),
                metadata.get("claim_evidence_pairs"),
                metadata.get("static_panel_spec"),
                metadata.get("infographic_section_specs"),
            )
            if cls._coerce_text_value(value)
        ).casefold()
        if not combined:
            return False
        return bool(
            re.search(
                r"\b("
                r"rank(?:ed|ing)?|compar(?:e|ing|ison)|versus|vs\.?|"
                r"list(?:ing)?|checklist|scorecard|matrix|table|"
                r"rules?|requirements?|criteria|fees?|charges?|rates?|penalt(?:y|ies)|"
                r"key\s+(?:rules|points|factors|takeaways)|"
                r"options?|items?|categories|providers"
                r")\b",
                combined,
                flags=re.IGNORECASE,
            )
        )

    @classmethod
    def _data_list_surface_contract(
        cls,
        *,
        prompt: Any,
        format_name: str,
        metadata: dict[str, Any] | None = None,
        text_payload: StructuredTextPayload | None = None,
        visual_plan: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        normalized_format = str(format_name or "").strip().casefold()
        if not cls._data_list_surface_intent(
            prompt=prompt,
            format_name=normalized_format,
            metadata=metadata,
            text_payload=text_payload,
            visual_plan=visual_plan,
        ):
            return None
        metadata = metadata if isinstance(metadata, dict) else {}
        top_n = cls._explicit_top_n_item_count(prompt, metadata)
        available_count = cls._data_list_surface_available_count(metadata)
        requested_count = top_n or max(available_count, 3)
        module_cap = 10 if normalized_format == "static" and top_n else 6 if normalized_format == "static" else 10
        module_count = max(1, min(module_cap, requested_count))
        intent = "top_n_list" if top_n else "comparison_or_list"
        ranking_surface = bool(
            top_n
            or re.search(
                r"\b(rank(?:ed|ing)?|table|scorecard|matrix|compar(?:e|ing|ison)|versus|vs\.?)\b",
                cls._coerce_text_value(prompt).casefold(),
            )
        )
        return {
            "intent": intent,
            "format": normalized_format,
            "surface_mode": "ranking_table" if ranking_surface and module_count >= 7 else "comparison_cards",
            "requested_count": requested_count,
            "available_count": available_count,
            "module_count": module_count,
        }

    @classmethod
    def _sanitize_infographic_surface_visual_metadata_fields(
        cls,
        metadata: dict[str, Any],
        *,
        request_prompt: Any,
        format_name: str,
    ) -> tuple[dict[str, Any], list[str]]:
        cleaned = dict(metadata or {})
        if not cleaned or not cls._infographic_surface_intent(
            prompt=request_prompt,
            format_name=format_name,
        ):
            return cleaned, []

        prompt_text = cls._normalize_metadata_text(request_prompt, limit=720)
        prompt_keywords = cls._topic_anchor_keywords(prompt_text, limit=14)
        prompt_allows_photo_scene = bool(
            re.search(
                r"\b(photo|photographic|realistic|portrait|lifestyle|image[- ]led|environment)\b",
                prompt_text,
                flags=re.IGNORECASE,
            )
        )
        removed_fields: list[str] = []
        for field, limit in cls.VISUAL_METADATA_FIELD_LIMITS.items():
            text = cls._normalize_metadata_text(cleaned.get(field), limit=limit)
            cleaned[field] = text
            if not text:
                continue
            treatment, _source = cls._visual_treatment_from_text(text)
            field_keywords = cls._visual_metadata_keywords(text, limit=12)
            shared_topic = bool(field_keywords & prompt_keywords)
            scene_led = treatment == "photo_composite" or bool(
                re.search(
                    r"\b(full[- ]bleed|single[- ]subject|lifestyle|portrait|backdrop|environment)\b",
                    text,
                    flags=re.IGNORECASE,
                )
            )
            if scene_led and not prompt_allows_photo_scene and not shared_topic:
                cleaned[field] = ""
                removed_fields.append(field)
        return cleaned, removed_fields

    @classmethod
    def _infographic_surface_enforcement_section(
        cls,
        *,
        request: AIOrchestrationRequest,
        format_name: str,
        structured_visual_metadata: Any = None,
        visual_plan: dict[str, Any] | None = None,
    ) -> str:
        if not cls._infographic_surface_intent(
            prompt=getattr(request, "prompt", ""),
            format_name=format_name,
            visual_plan=visual_plan,
        ):
            return ""
        structured = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        strict_anchors = structured.get("data_anchors") if isinstance(structured.get("data_anchors"), list) else []
        top_n = cls._explicit_top_n_item_count(getattr(request, "prompt", ""))
        top_n_rule = (
            f"Top-N comparison contract: the prompt asks for {top_n} item slot(s); represent that count with {top_n} visible comparison modules, cards, rows, or grouped list slots when the layout budget allows."
            if top_n
            else "Comparison contract: represent the requested compared categories with visible modules, cards, rows, or grouped list slots when the layout budget allows."
        )
        data_rule = (
            "Strict anchors are present: any table, bar, metric, ranking, label, value, axis, or legend must use only those approved anchors."
            if strict_anchors
            else "No strict approved data_anchors are present: keep the comparison qualitative and non-numeric; do not invent item labels, values, axes, bars, rankings, legends, dashboard tiles, or map-data values."
        )
        return (
            "Infographic surface enforcement: selected format is infographic, so the visual must be a module-first infographic surface with clear comparison structure, not an unrelated single-scene backdrop or generic image-led poster. "
            f"{top_n_rule} "
            "Show the relationship between compared items through ranked/list/card/module structure, connectors, dividers, grouped panels, or a non-numeric matrix that matches the user prompt intent. "
            f"{data_rule} "
            "Decorative imagery must stay secondary to the data/comparison surface. Keep title, modules, icons, and any comparison structure outside backend header/logo and footer/disclaimer safe areas."
        )

    @classmethod
    def _data_visualization_requested(cls, *values: Any) -> bool:
        combined = " ".join(
            cls._normalize_metadata_text(value, limit=520)
            for value in values
            if cls._normalize_metadata_text(value, limit=520)
        ).casefold()
        if not combined:
            return False
        return any(term in combined for term in cls.DATA_VISUAL_TERMS)

    @classmethod
    def _numeric_data_visualization_requested(cls, *values: Any) -> bool:
        combined = " ".join(
            cls._normalize_metadata_text(value, limit=520)
            for value in values
            if cls._normalize_metadata_text(value, limit=520)
        ).casefold()
        if not combined:
            return False
        return any(term in combined for term in cls.NUMERIC_DATA_VISUAL_TERMS)

    @classmethod
    def _data_visualization_anchor_lines(
        cls,
        *values: Any,
        limit: int = 10,
    ) -> list[str]:
        anchors: list[str] = []
        for value in values:
            if isinstance(value, dict):
                for key in (
                    "claim",
                    "evidence",
                    "headline",
                    "body",
                    "supporting_line",
                    "dominant_message",
                    "visual_focus",
                ):
                    text = cls._normalize_metadata_text(value.get(key), limit=260)
                    if text:
                        anchors.append(text)
                for key in (
                    "body_points",
                    "proof_points",
                    "stat_highlights",
                    "claim_evidence_pairs",
                    "static_panel_spec",
                    "infographic_section_specs",
                ):
                    nested = value.get(key)
                    if nested:
                        anchors.extend(cls._data_visualization_anchor_lines(nested, limit=limit))
                continue
            if isinstance(value, list):
                for item in value:
                    anchors.extend(cls._data_visualization_anchor_lines(item, limit=limit))
                continue
            text = cls._normalize_metadata_text(value, limit=260)
            if text:
                anchors.append(text)
        deduped: list[str] = []
        seen: set[str] = set()
        for anchor in anchors:
            key = anchor.casefold()
            if key in seen:
                continue
            seen.add(key)
            deduped.append(anchor)
            if len(deduped) >= limit:
                break
        return deduped

    @classmethod
    def _data_visualization_has_content_anchor(
        cls,
        *,
        request: AIOrchestrationRequest,
        anchors: list[str],
    ) -> bool:
        if not anchors:
            return False
        topic_tokens = cls._content_topic_tokens(request)
        for anchor in anchors:
            if cls._exact_claim_markers(anchor):
                return True
            if cls._content_line_is_evidence_anchor(anchor, request=request):
                return True
            if topic_tokens and (set(cls._normalized_prompt_tokens(anchor)) & topic_tokens):
                return True
        return False

    @classmethod
    def _data_visualization_contract(
        cls,
        *,
        request: AIOrchestrationRequest,
        visual_intent: Any,
        anchors: list[str],
        format_name: str,
    ) -> str:
        if not cls._data_visualization_requested(request.prompt, visual_intent, *anchors):
            return ""
        numeric_requested = cls._numeric_data_visualization_requested(request.prompt, visual_intent, *anchors)
        exact_markers: set[str] = set()
        for anchor in anchors:
            exact_markers.update(cls._exact_claim_markers(anchor))
        anchor_summary = "; ".join(f'"{item}"' for item in anchors[:5]) or "no approved anchors"
        has_content_anchor = cls._data_visualization_has_content_anchor(
            request=request,
            anchors=anchors,
        )
        if not has_content_anchor:
            return (
                f"Data visualization execution contract for {format_name}: no approved data/content anchors are available. "
                "Strict prohibition: do not render a table, tabular layout, chart, graph, dashboard, scorecard, timeline, metric module, fake UI analytics panel, matrix, generic bars, fake axes, random percentages, placeholder numbers, or unlabeled data shapes. "
                "Use a non-data visual treatment tied to the approved headline/body instead."
            )
        value_rule = (
            "Numeric charting is allowed only for the exact values present in these anchors; do not add any extra values, percentages, axes, or rankings."
            if exact_markers
            else "No exact numeric series is approved here, so do not render numeric axes, bars, lines, percentages, currency amounts, rankings, or trend graphs. Use only qualitative modules, labeled comparison cards, process blocks, or a non-numeric matrix tied to the approved anchors."
        )
        type_rule = (
            "Choose table/matrix for comparisons, bar chart for ranked categories with real values, line chart for dated trends, flowchart for sequences, dashboard/scorecard modules for qualitative evidence, and callout cards for single proof points."
            if numeric_requested
            else "If a data-like structure helps, keep it as readable cards/modules tied to the content instead of decorative chart furniture."
        )
        return (
            f"Data visualization execution contract for {format_name}: approved data/content anchors are {anchor_summary}. "
            f"{value_rule} {type_rule} Every row, column, axis, legend, label, metric, or module heading must map to one approved anchor; never render generic bars, fake axes, random dashboard tiles, placeholder numbers, or unlabeled chart shapes."
        )

    @classmethod
    def _broad_visual_context_prompt_section(cls, lines: Any, *, limit: int = 5) -> str:
        context_lines = cls._normalize_metadata_list(lines, limit=limit)
        if not context_lines:
            return ""
        return (
            "Broad visual/layout context hints, not strict data anchors: "
            + "; ".join(context_lines)
            + ". Use these only for composition, hierarchy, and subject context; they cannot unlock charts, dashboards, numeric callouts, or data visuals."
        )

    @classmethod
    def _sample_visual_permissions(cls, sample_page_blueprint: Any) -> dict[str, Any]:
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}
        permissions = blueprint.get("visual_permissions") if isinstance(blueprint.get("visual_permissions"), dict) else {}
        return dict(permissions)

    @classmethod
    def _sample_permission_allows_visual_type(
        cls,
        *,
        sample_page_blueprint: Any,
        visual_type: str,
    ) -> bool:
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}
        permissions = cls._sample_visual_permissions(blueprint)
        if not blueprint or not permissions:
            return True
        normalized_type = visual_type.strip().casefold()
        if normalized_type == "table":
            return bool(permissions.get("table_allowed", True))
        if normalized_type == "dashboard":
            return bool(permissions.get("dashboard_allowed", True))
        if normalized_type == "chart":
            observed_keys = [
                key
                for key in ("chart_or_graph_allowed", "metric_tiles_allowed", "dashboard_allowed")
                if key in permissions
            ]
            if not observed_keys:
                return True
            return any(bool(permissions.get(key)) for key in observed_keys)
        if normalized_type in {"3d", "isometric"}:
            observed_keys = [
                key
                for key in (
                    "three_d_allowed",
                    "3d_allowed",
                    "dimensional_allowed",
                    "depth_allowed",
                    "isometric_allowed",
                )
                if key in permissions
            ]
            if not observed_keys:
                return True
            return any(bool(permissions.get(key)) for key in observed_keys)
        if normalized_type == "icon_system":
            observed_keys = [
                key
                for key in ("icon_system_allowed", "icons_allowed", "iconography_allowed")
                if key in permissions
            ]
            if not observed_keys:
                return True
            return any(bool(permissions.get(key)) for key in observed_keys)
        if normalized_type == "photo_composite":
            observed_keys = [
                key
                for key in ("photo_allowed", "photography_allowed", "image_composite_allowed")
                if key in permissions
            ]
            if not observed_keys:
                return True
            return any(bool(permissions.get(key)) for key in observed_keys)
        return True

    @classmethod
    def _prompt_has_explicit_data_anchor(cls, prompt: Any) -> bool:
        text = cls._normalize_metadata_text(prompt, limit=520)
        if not text:
            return False
        if cls._exact_claim_markers(text):
            return True
        return bool(
            re.search(
                r"\b(?:table|matrix|comparison|compare|versus|vs\.?)\b.{0,120}\b(?:by|across|between|for)\b",
                text,
                flags=re.IGNORECASE,
            )
        )

    @classmethod
    def _structured_visual_anchor_source_allowed(cls, source: Any) -> bool:
        source_label = cls._normalize_metadata_text(source, limit=64).casefold()
        return source_label in cls.STRUCTURED_VISUAL_APPROVED_ANCHOR_SOURCES

    @classmethod
    def _structured_visual_anchor_lines(
        cls,
        value: Any,
        *,
        source_label: str,
        limit: int = 8,
    ) -> list[str]:
        lines: list[str] = []
        seen: set[str] = set()
        normalized_source = cls._normalize_metadata_text(source_label, limit=64).casefold()

        def append_line(candidate: Any) -> None:
            if len(lines) >= limit:
                return
            text = cls._normalize_metadata_text(candidate, limit=260)
            if not text:
                return
            key = text.casefold()
            if key in seen:
                return
            seen.add(key)
            lines.append(text)

        def collect(item: Any) -> None:
            if len(lines) >= limit:
                return
            if isinstance(item, dict):
                if normalized_source in {"claim_evidence", "claim_evidence_pairs", "nested_claim_evidence_pairs"}:
                    for key in ("claim", "evidence"):
                        append_line(item.get(key))
                    return
                if "verified" in normalized_source or normalized_source.endswith("evidence"):
                    for key in ("fact", "statement", "text", "claim", "evidence", "value"):
                        append_line(item.get(key))
                    return
                if normalized_source in {"stat_highlight", "stat_highlights", "nested_stat_highlights"}:
                    for key in ("text", "value", "stat", "fact", "evidence"):
                        append_line(item.get(key))
                    return
                for key in ("text", "value", "fact", "statement"):
                    append_line(item.get(key))
                return
            if isinstance(item, (list, tuple, set)):
                for nested in item:
                    collect(nested)
                    if len(lines) >= limit:
                        break
                return
            append_line(item)

        collect(value)
        return lines[:limit]

    @classmethod
    def _structured_visual_nested_anchor_sources(cls, *containers: Any) -> list[tuple[str, Any]]:
        buckets: dict[str, list[Any]] = {}

        def add(source: str, value: Any) -> None:
            if value is None:
                return
            buckets.setdefault(source, []).append(value)

        def collect(value: Any) -> None:
            if isinstance(value, dict):
                for key in cls.STRUCTURED_VISUAL_NESTED_ANCHOR_KEYS:
                    if key in value:
                        add(f"nested_{key}", value.get(key))
                fact_model = value.get("fact_model") if isinstance(value.get("fact_model"), dict) else {}
                if fact_model:
                    for key in ("verified_facts", "evidence", "verified_evidence", "approved_evidence"):
                        if key in fact_model:
                            add(f"nested_{key}", fact_model.get(key))
                return
            if isinstance(value, (list, tuple, set)):
                for item in value:
                    collect(item)

        for container in containers:
            collect(container)
        return [(source, values) for source, values in buckets.items() if values]

    @classmethod
    def _structured_visual_data_anchor_sources(
        cls,
        metadata: Any,
        *,
        prompt: Any = "",
        request: AIOrchestrationRequest | None = None,
    ) -> list[tuple[str, Any]]:
        sources: list[tuple[str, Any]] = []
        prompt_text = prompt
        if not prompt_text and request is not None:
            prompt_text = request.prompt
        if prompt_text and cls._prompt_has_explicit_data_anchor(prompt_text):
            sources.append(("user_prompt", prompt_text))
        if not isinstance(metadata, dict):
            return sources

        for key in cls.STRUCTURED_VISUAL_PRIMARY_ANCHOR_KEYS:
            sources.append((key, metadata.get(key)))

        fact_model = metadata.get("fact_model") if isinstance(metadata.get("fact_model"), dict) else {}
        if fact_model:
            for key in ("verified_facts", "evidence", "verified_evidence", "approved_evidence"):
                if key in fact_model:
                    sources.append((key, fact_model.get(key)))

        sources.extend(
            cls._structured_visual_nested_anchor_sources(
                metadata.get("infographic_section_specs"),
                metadata.get("static_panel_spec"),
            )
        )
        return sources

    @classmethod
    def _structured_visual_anchor_entries(
        cls,
        sources: list[tuple[str, Any]],
        *,
        request: AIOrchestrationRequest | None = None,
        limit: int = 8,
    ) -> list[dict[str, Any]]:
        entries: list[dict[str, Any]] = []
        seen: set[str] = set()
        for source, value in sources:
            source_label = cls._normalize_metadata_text(source, limit=48) or "metadata"
            if not cls._structured_visual_anchor_source_allowed(source_label):
                continue
            for line in cls._structured_visual_anchor_lines(value, source_label=source_label, limit=limit):
                normalized = cls._normalize_metadata_text(line, limit=260)
                if not normalized:
                    continue
                key = normalized.casefold()
                if key in seen:
                    continue
                seen.add(key)
                entries.append(
                    {
                        "source": source_label,
                        "text": normalized,
                        "has_exact_value": bool(cls._exact_claim_markers(normalized)),
                    }
                )
                if len(entries) >= limit:
                    break
            if len(entries) >= limit:
                break
        if not entries:
            return []
        if request is not None and not cls._data_visualization_has_content_anchor(
            request=request,
            anchors=[entry["text"] for entry in entries],
        ):
            return []
        return entries[:limit]

    @classmethod
    def _brand_visual_grounding_evidence(
        cls,
        *,
        visual_identity: Any,
        reference_assets: Any = None,
        asset_catalog: Any = None,
        compiled_context: dict[str, Any] | None = None,
        limit: int = 5,
        include_reusable_design_assets: bool = True,
    ) -> list[str]:
        evidence: list[str] = []

        def add(value: Any, *, item_limit: int = 120) -> None:
            normalized = cls._normalize_metadata_text(value, limit=item_limit)
            if not normalized:
                return
            if any(normalized.casefold() == item.casefold() for item in evidence):
                return
            evidence.append(cls._scrub_image_prompt_brand_mark_triggers(normalized, replacement="reserved space"))

        if isinstance(visual_identity, dict):
            for key in ("visual_style", "brand_mood", "illustration_style", "design_style", "composition_style"):
                add(visual_identity.get(key), item_limit=90)
            reusable_assets = visual_identity.get("reusable_design_assets")
            if include_reusable_design_assets and isinstance(reusable_assets, list):
                for asset in reusable_assets[:6]:
                    if not isinstance(asset, dict):
                        add(asset, item_limit=80)
                        continue
                    asset_parts = [
                        asset.get("name"),
                        asset.get("label"),
                        asset.get("asset_kind"),
                        asset.get("style"),
                        ", ".join(str(tag) for tag in asset.get("tags", [])[:4]) if isinstance(asset.get("tags"), list) else "",
                    ]
                    add(" ".join(str(part).strip() for part in asset_parts if str(part or "").strip()), item_limit=120)
                    if len(evidence) >= limit:
                        break

        reference_asset_items = reference_assets if isinstance(reference_assets, list) else []
        asset_catalog_items = asset_catalog if isinstance(asset_catalog, list) else []
        for asset in [*reference_asset_items[:4], *asset_catalog_items[:4]]:
            if not isinstance(asset, dict):
                continue
            label = cls._reference_asset_display_label(asset)
            role = cls._normalize_metadata_text(asset.get("asset_role"), limit=48)
            add(" ".join(part for part in [role, label] if part), item_limit=120)
            if len(evidence) >= limit:
                break

        visual_knowledge_brief = ContextCompilerService.coerce_visual_knowledge_brief(
            (compiled_context or {}).get("visual_knowledge_brief"),
        )
        for item in (visual_knowledge_brief.get("items") or [])[:4]:
            if not isinstance(item, dict):
                continue
            add(item.get("content"), item_limit=140)
            if len(evidence) >= limit:
                break

        return evidence[:limit]

    @classmethod
    def _visual_treatment_from_text(cls, value: Any) -> tuple[str, str]:
        text = cls._normalize_metadata_text(value, limit=900).casefold()
        if not text:
            return "brand_led", "default"
        if re.search(r"\b(isometric|2\.5d|2-5d|axonometric)\b", text):
            return "isometric", "text"
        if re.search(r"\b(3d|three[- ]dimensional|volumetric|depth|dimensional|rendered object)\b", text):
            return "3d", "text"
        if re.search(r"\b(product dashboard|dashboard|analytics panel|platform surface|app surface|laptop|screen ui|ui panel)\b", text):
            return "product_dashboard", "text"
        if re.search(r"\b(icon system|icon set|icons|pictogram|glyph)\b", text):
            return "icon_system", "text"
        if re.search(r"\b(table|chart|graph|scorecard|metric module|data module|matrix)\b", text):
            return "data_module", "text"
        if re.search(r"\b(photo|photographic|image-led|lifestyle|portrait|environment)\b", text):
            return "photo_composite", "text"
        if re.search(r"\b(document|evidence|paper|report|contract|file|certificate)\b", text):
            return "document_evidence", "text"
        if re.search(r"\b(flat|editorial|magazine|poster|minimal|minimalist|illustration)\b", text):
            return "flat_editorial", "text"
        if re.search(r"\b(2d|two[- ]dimensional)\b", text):
            return "2d", "text"
        return "brand_led", "default"

    @classmethod
    def _resolve_visual_treatment_preference(
        cls,
        *,
        prompt_text: Any = "",
        combined_intent: Any = "",
        visual_plan: dict[str, Any] | None = None,
        raw_preference: Any = None,
        sample_page_blueprint: Any = None,
        brand_grounding: list[str] | None = None,
        table_requested: bool = False,
        chart_requested: bool = False,
        table_allowed: bool = False,
        chart_allowed: bool = False,
        anchor_count: int = 0,
        format_name: str = "",
    ) -> dict[str, Any]:
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        grounding = list(brand_grounding or [])
        scores = {value: 0.0 for value in cls.VISUAL_TREATMENT_PREFERENCE_VALUES}
        evidence: dict[str, list[str]] = {value: [] for value in cls.VISUAL_TREATMENT_PREFERENCE_VALUES}
        evidence_sources: dict[str, list[str]] = {value: [] for value in cls.VISUAL_TREATMENT_PREFERENCE_VALUES}

        def add_score(treatment: str, amount: float, source: str, reason: str) -> None:
            if treatment not in scores or amount <= 0:
                return
            scores[treatment] += amount
            compact_reason = cls._normalize_metadata_text(reason, limit=80)
            if compact_reason and compact_reason not in evidence[treatment]:
                evidence[treatment].append(compact_reason)
            if source and source not in evidence_sources[treatment]:
                evidence_sources[treatment].append(source)

        treatment_patterns: tuple[tuple[str, str, str], ...] = (
            ("isometric", r"\b(isometric|2\.5d|2-5d|axonometric)\b", "isometric/dimensional system cue"),
            ("3d", r"\b(3d|three[- ]dimensional|volumetric|true[- ]3d|rendered object|soft surfaces|depth)\b", "3d/depth cue"),
            ("product_dashboard", r"\b(product dashboard|dashboard|analytics panel|platform surface|app surface|laptop|screen ui|ui panel|product surface)\b", "product/ui surface cue"),
            ("icon_system", r"\b(icon system|icon set|icons|pictogram|glyph|iconography|symbol system)\b", "icon-system cue"),
            ("data_module", r"\b(table|chart|graph|scorecard|metric module|data module|matrix|dashboard tile|axis|axes)\b", "data/module cue"),
            ("photo_composite", r"\b(photo|photographic|image-led|lifestyle|portrait|environment|realistic scene)\b", "photo/composite cue"),
            ("document_evidence", r"\b(document|evidence|paper|report|contract|file|certificate|record)\b", "document/evidence cue"),
            ("flat_editorial", r"\b(flat|editorial|magazine|poster|minimal|minimalist|illustration|campaign)\b", "flat/editorial cue"),
            ("2d", r"\b(2d|two[- ]dimensional|vector|line art)\b", "2d cue"),
        )

        def score_text(source: str, value: Any, weight: float) -> None:
            text = cls._normalize_metadata_text(value, limit=900)
            if not text:
                return
            lowered = text.casefold()
            matched = False
            for treatment, pattern, reason in treatment_patterns:
                if re.search(pattern, lowered):
                    add_score(treatment, weight, source, reason)
                    matched = True
            if not matched and source in {"sample_layout", "fallback_context"}:
                add_score("brand_led", max(weight * 0.4, 1.0), source, "general context fit")

        score_text("user_prompt", prompt_text, 90.0)
        score_text("metadata", combined_intent, 42.0)
        score_text(
            "visual_plan",
            " ".join(
                cls._coerce_text_value(plan.get(key))
                for key in ("mode", "need", "rationale", "density")
                if cls._coerce_text_value(plan.get(key)).strip()
            ),
            28.0,
        )

        existing = raw_preference if isinstance(raw_preference, dict) else {}
        existing_preferred = cls._normalize_metadata_text(existing.get("preferred"), limit=40).casefold()
        if existing_preferred in cls.VISUAL_TREATMENT_PREFERENCE_VALUES:
            add_score(existing_preferred, 36.0, "structured_metadata", "existing structured preference")

        for item in grounding[:6]:
            score_text("brand_context", item, 62.0)

        counts = blueprint.get("module_counts") if isinstance(blueprint.get("module_counts"), dict) else {}
        layout_parts: list[str] = [
            cls._normalize_metadata_text(blueprint.get("layout_category"), limit=80),
            cls._normalize_metadata_text(blueprint.get("layout_mode"), limit=80),
            cls._normalize_metadata_text(blueprint.get("density"), limit=32),
        ]
        for zone_key in ("image_zones", "zones", "content_zones"):
            zones = blueprint.get(zone_key)
            if isinstance(zones, list):
                for zone in zones[:6]:
                    if isinstance(zone, dict):
                        layout_parts.extend(
                            cls._normalize_metadata_text(zone.get(key), limit=40)
                            for key in ("role", "name", "label", "zone_role")
                            if cls._normalize_metadata_text(zone.get(key), limit=40)
                        )
        score_text("sample_layout", " ".join(part for part in layout_parts if part), 30.0)
        try:
            small_icon_count = int(counts.get("small_icon_like_count") or 0)
            card_count = int(counts.get("card_like_count") or 0)
            visual_count = int(counts.get("large_visual_count") or 0)
        except (TypeError, ValueError):
            small_icon_count = card_count = visual_count = 0
        if small_icon_count > 0:
            add_score("icon_system", 22.0, "sample_layout", "sample has icon-like modules")
        if card_count > 0:
            add_score("flat_editorial", 12.0, "sample_layout", "sample has card/callout modules")
        if visual_count > 0 and not any(scores[value] for value in ("3d", "isometric", "photo_composite")):
            add_score("brand_led", 8.0, "sample_layout", "sample has visual slot")

        intent_text = cls._normalize_metadata_text(" ".join([cls._coerce_text_value(prompt_text), cls._coerce_text_value(combined_intent)]), limit=900).casefold()
        if re.search(r"\b(process|workflow|steps|sequence|journey|system|flow)\b", intent_text):
            add_score("icon_system", 20.0, "fallback_context", "process/workflow clarity cue")
            add_score("isometric", 12.0, "fallback_context", "process/workflow dimensional cue")
        if re.search(r"\b(compare|comparison|versus|vs\.?|before[- ]after|trade[- ]off)\b", intent_text):
            add_score("flat_editorial", 20.0, "fallback_context", "comparison clarity cue")
        if re.search(r"\b(service|explain|explanation|educat|guide|clarity)\b", intent_text):
            add_score("flat_editorial", 16.0, "fallback_context", "clarity-first explanation cue")
        if str(format_name or "").strip().casefold() in {"carousel", "infographic", "poster"}:
            add_score("flat_editorial", 8.0, "fallback_context", "format needs clear composition")

        if (table_requested or chart_requested) and anchor_count and (table_allowed or chart_allowed):
            add_score("data_module", 110.0, "approved_data_anchors", "strict data anchors and permissions")

        def product_context_present() -> bool:
            return bool(
                re.search(
                    r"\b(product|platform|app|screen|dashboard|ui|interface|analytics panel|laptop)\b",
                    intent_text + " " + " ".join(item.casefold() for item in grounding[:4]),
                )
            )

        blocked_reasons: list[str] = []

        def permission_allowed(treatment: str) -> bool:
            if treatment == "product_dashboard":
                if not product_context_present():
                    blocked_reasons.append("product_dashboard blocked: no product/ui context evidence")
                    return False
                if not cls._sample_permission_allows_visual_type(sample_page_blueprint=blueprint, visual_type="dashboard"):
                    blocked_reasons.append("product_dashboard blocked by sample visual_permissions")
                    return False
                return True
            if treatment == "data_module":
                if not anchor_count:
                    blocked_reasons.append("data_module blocked: no strict data anchors")
                    return False
                if not ((table_requested and table_allowed) or (chart_requested and chart_allowed)):
                    blocked_reasons.append("data_module blocked by data intent or sample permissions")
                    return False
                return True
            if treatment in {"3d", "isometric", "icon_system", "photo_composite"}:
                if not cls._sample_permission_allows_visual_type(sample_page_blueprint=blueprint, visual_type=treatment):
                    blocked_reasons.append(f"{treatment} blocked by sample visual_permissions")
                    return False
            return True

        ranked = sorted(
            ((treatment, score) for treatment, score in scores.items() if score > 0),
            key=lambda item: item[1],
            reverse=True,
        )
        preferred = ""
        preferred_score = 0.0
        for treatment, score in ranked:
            if permission_allowed(treatment):
                preferred = treatment
                preferred_score = score
                break

        fallback_reason = ""
        if not preferred:
            if blueprint:
                preferred = "flat_editorial"
                fallback_reason = "sample layout present without stronger allowed treatment evidence"
            else:
                preferred = "brand_led"
                fallback_reason = "no stronger treatment evidence"
            preferred_score = scores.get(preferred, 0.0)
            if preferred_score <= 0:
                add_score(preferred, 12.0, "fallback_context", fallback_reason)
                preferred_score = scores.get(preferred, 12.0)

        source_priority = ("user_prompt", "brand_context", "approved_data_anchors", "metadata", "visual_plan", "structured_metadata", "sample_layout", "fallback_context")
        preferred_sources = evidence_sources.get(preferred) or ["fallback_context"]
        if preferred == "data_module" and anchor_count:
            source = "data_anchors"
        else:
            source = next((candidate for candidate in source_priority if candidate in preferred_sources), preferred_sources[0])
            if source == "approved_data_anchors":
                source = "data_anchors"
        confidence = round(min(max(preferred_score / 120.0, 0.05), 0.99), 2)
        decision_evidence = evidence.get(preferred)[:5]
        if not fallback_reason and "fallback_context" in preferred_sources and source == "fallback_context":
            fallback_reason = "context-derived fallback"

        return {
            "preferred": preferred,
            "allowed": True,
            "source": source,
            "brand_asset_grounding": grounding,
            "layout_obedience": "sample_layout_first" if blueprint else "approved_layout_slots_first",
            "decision_evidence": decision_evidence,
            "blocked_reasons": list(dict.fromkeys(blocked_reasons))[:5],
            "fallback_reason": fallback_reason,
            "confidence": confidence,
        }

    @classmethod
    def _creativity_signal_lines(cls, value: Any, *, brand_grounding: list[str], limit: int = 5) -> list[str]:
        text = cls._normalize_metadata_text(value, limit=900)
        lowered = text.casefold()
        signals: list[str] = []
        for label, pattern in (
            ("creative_prompt", r"\b(creative|attractive|premium|high-end|polished|dynamic|engaging|attention-grabbing)\b"),
            ("dimensional_visual", r"\b(3d|three[- ]dimensional|isometric|2\.5d|depth|volumetric)\b"),
            ("editorial_visual", r"\b(editorial|magazine|campaign|poster|flat|minimal)\b"),
            ("structured_visual", r"\b(table|chart|graph|dashboard|matrix|scorecard|comparison)\b"),
            ("asset_grounded", r"\b(reference|asset|visual identity|brand system|icon|illustration)\b"),
        ):
            if re.search(pattern, lowered):
                signals.append(label)
        if brand_grounding:
            signals.append("brand_asset_context")
        deduped: list[str] = []
        for signal in signals:
            if signal not in deduped:
                deduped.append(signal)
            if len(deduped) >= limit:
                break
        return deduped

    @classmethod
    def _normalize_structured_visual_metadata(
        cls,
        *,
        metadata: dict[str, Any],
        request: AIOrchestrationRequest | None = None,
        visual_intent: Any = "",
        anchor_entries: list[dict[str, Any]] | None = None,
        format_name: str = "",
        sample_page_blueprint: Any = None,
        visual_plan: dict[str, Any] | None = None,
        visual_identity: Any = None,
        reference_assets: Any = None,
        asset_catalog: Any = None,
        compiled_context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        raw = metadata.get("structured_visual_metadata") if isinstance(metadata, dict) else {}
        raw = raw if isinstance(raw, dict) else {}
        blueprint = (
            sample_page_blueprint
            if isinstance(sample_page_blueprint, dict)
            else metadata.get("sample_page_blueprint")
            if isinstance(metadata.get("sample_page_blueprint"), dict)
            else {}
        )
        prompt_text = request.prompt if request is not None else ""
        combined_intent = " ".join(
            part
            for part in [
                cls._coerce_text_value(prompt_text),
                cls._coerce_text_value(visual_intent),
                cls._coerce_text_value(metadata.get("visual_focus")),
                cls._coerce_text_value(metadata.get("visual_direction")),
                cls._coerce_text_value(metadata.get("design_style")),
                cls._coerce_text_value(metadata.get("image_prompt")),
            ]
            if cls._coerce_text_value(part).strip()
        )
        lowered_intent = combined_intent.casefold()
        table_requested = bool(re.search(r"\b(table|tabular|matrix|comparison grid)\b", lowered_intent))
        chart_requested = bool(
            re.search(
                r"\b(chart|graph|dashboard|scorecard|metric module|metrics module|timeline|axis|axes|data visuali[sz]ation|data viz)\b",
                lowered_intent,
            )
        )
        numeric_requested = cls._numeric_data_visualization_requested(combined_intent)
        data_anchors = list(anchor_entries or [])
        if not data_anchors and isinstance(raw.get("data_anchors"), list):
            for item in raw.get("data_anchors", [])[:8]:
                if isinstance(item, dict):
                    text = cls._normalize_metadata_text(item.get("text"), limit=260)
                    source_label = cls._normalize_metadata_text(item.get("source"), limit=48) or "structured_visual_metadata"
                else:
                    text = cls._normalize_metadata_text(item, limit=260)
                    source_label = "structured_visual_metadata"
                if text and cls._structured_visual_anchor_source_allowed(source_label):
                    data_anchors.append(
                        {
                            "source": source_label,
                            "text": text,
                            "has_exact_value": bool(cls._exact_claim_markers(text)),
                        }
                    )
        anchor_count = len(data_anchors)
        prompt_explicit_visual = bool(request and cls._has_explicit_data_visual_request(prompt_text, text_payload=None))
        explicit_anchor_override = bool(prompt_explicit_visual and anchor_count)
        sample_table_allowed = cls._sample_permission_allows_visual_type(
            sample_page_blueprint=blueprint,
            visual_type="table",
        )
        sample_chart_allowed = cls._sample_permission_allows_visual_type(
            sample_page_blueprint=blueprint,
            visual_type="chart",
        )
        table_allowed = bool(table_requested and anchor_count and (sample_table_allowed or explicit_anchor_override))
        chart_allowed = bool(chart_requested and anchor_count and (sample_chart_allowed or explicit_anchor_override))
        brand_grounding = cls._brand_visual_grounding_evidence(
            visual_identity=visual_identity,
            reference_assets=reference_assets,
            asset_catalog=asset_catalog,
            compiled_context=compiled_context,
            include_reusable_design_assets=not bool(blueprint),
        )
        existing_preference = raw.get("visual_treatment_preference") if isinstance(raw.get("visual_treatment_preference"), dict) else {}
        treatment_preference = cls._resolve_visual_treatment_preference(
            prompt_text=prompt_text,
            combined_intent=combined_intent,
            visual_plan=visual_plan,
            raw_preference=existing_preference,
            sample_page_blueprint=blueprint,
            brand_grounding=brand_grounding,
            table_requested=table_requested,
            chart_requested=chart_requested,
            table_allowed=table_allowed,
            chart_allowed=chart_allowed,
            anchor_count=anchor_count,
            format_name=format_name,
        )
        preferred_treatment = cls._normalize_metadata_text(
            treatment_preference.get("preferred"),
            limit=40,
        ).casefold()
        creativity_signals = cls._creativity_signal_lines(
            combined_intent,
            brand_grounding=brand_grounding,
        )
        needs_attractive_visual = bool(
            creativity_signals
            or preferred_treatment in {"3d", "isometric", "flat_editorial", "photo_composite", "document_evidence"}
            or str(format_name or "").strip().casefold() in {"carousel", "infographic", "poster"}
        )
        source = "user_prompt" if prompt_explicit_visual else "metadata" if (table_requested or chart_requested) else "none"
        return {
            "schema_version": cls.STRUCTURED_VISUAL_METADATA_SCHEMA_VERSION,
            "table_intent": {
                "requested": table_requested,
                "allowed": table_allowed,
                "requires_data_anchors": True,
                "anchor_count": anchor_count if table_requested else 0,
                "source": source if table_requested else "none",
            },
            "chart_intent": {
                "requested": chart_requested,
                "allowed": chart_allowed,
                "numeric": numeric_requested,
                "requires_data_anchors": True,
                "anchor_count": anchor_count if chart_requested else 0,
                "source": source if chart_requested else "none",
            },
            "data_anchors": data_anchors[:8],
            "creativity_signals": {
                "needs_attractive_visual": needs_attractive_visual,
                "signals": creativity_signals,
                "source": "user_prompt" if creativity_signals and prompt_text else "brand_context" if brand_grounding else "metadata",
            },
            "visual_treatment_preference": {
                **treatment_preference,
            },
        }

    @classmethod
    def _structured_visual_metadata_prompt_section(cls, structured_visual_metadata: Any) -> str:
        metadata = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        if not metadata:
            return ""
        compact = json.dumps(metadata, ensure_ascii=True, separators=(",", ":"))
        preference = metadata.get("visual_treatment_preference") if isinstance(metadata.get("visual_treatment_preference"), dict) else {}
        table_intent = metadata.get("table_intent") if isinstance(metadata.get("table_intent"), dict) else {}
        chart_intent = metadata.get("chart_intent") if isinstance(metadata.get("chart_intent"), dict) else {}
        grounding = preference.get("brand_asset_grounding") if isinstance(preference.get("brand_asset_grounding"), list) else []
        grounding_text = "; ".join(cls._normalize_metadata_text(item, limit=120) for item in grounding[:4] if cls._normalize_metadata_text(item, limit=120))
        restrictions: list[str] = [
            f"Structured visual metadata contract JSON: {compact}.",
            "Layout obedience is stronger than creativity: apply the preferred visual treatment only inside approved layout, image, module, or visual slots; never invent new regions.",
            "Do not bypass sample visual_permissions; when a table/chart/dashboard intent is not allowed or has anchor_count=0, render a non-data visual treatment instead.",
        ]
        if grounding_text:
            restrictions.append(
                f"Brand-grounded visual treatment preference: {preference.get('preferred')} from {preference.get('source')}; grounding cues: {grounding_text}."
            )
        if (table_intent.get("requested") and not table_intent.get("allowed")) or (chart_intent.get("requested") and not chart_intent.get("allowed")):
            restrictions.append(
                "Table/chart request is blocked for this surface unless approved anchors and sample permissions both support it; do not draw tables, charts, axes, dashboards, or metric furniture."
            )
        return " ".join(part for part in restrictions if part)

    @classmethod
    def _dynamic_visual_art_direction_section(
        cls,
        *,
        request: AIOrchestrationRequest | None = None,
        format_name: str = "",
        semantic_visual_brief: Any = "",
        visual_intent: Any = "",
        structured_visual_metadata: Any = None,
        visual_plan: dict[str, Any] | None = None,
        visual_identity: Any = None,
        data_visualization_anchor_lines: list[str] | None = None,
        sample_page_blueprint: Any = None,
        slide_purpose: Any = "",
        reference_assets: Any = None,
        asset_catalog: Any = None,
        compiled_context: dict[str, Any] | None = None,
    ) -> str:
        metadata = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        preference = metadata.get("visual_treatment_preference") if isinstance(metadata.get("visual_treatment_preference"), dict) else {}
        creativity = metadata.get("creativity_signals") if isinstance(metadata.get("creativity_signals"), dict) else {}
        table_intent = metadata.get("table_intent") if isinstance(metadata.get("table_intent"), dict) else {}
        chart_intent = metadata.get("chart_intent") if isinstance(metadata.get("chart_intent"), dict) else {}
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}

        prompt_text = getattr(request, "prompt", "") if request is not None else ""
        communicate = cls._normalize_metadata_text(
            semantic_visual_brief
            or visual_intent
            or prompt_text,
            limit=260,
        )
        if not communicate:
            return ""

        plan_parts = [
            cls._normalize_metadata_text(format_name, limit=40),
            cls._normalize_metadata_text(slide_purpose, limit=120),
            cls._normalize_metadata_text(plan.get("mode"), limit=40),
            cls._normalize_metadata_text(plan.get("rationale"), limit=140),
        ]
        purpose = cls._normalize_metadata_text(
            " | ".join(part for part in plan_parts if part),
            limit=240,
        )
        preferred = cls._normalize_metadata_text(preference.get("preferred"), limit=40).casefold()
        if preferred not in cls.VISUAL_TREATMENT_PREFERENCE_VALUES:
            preferred, _ = cls._visual_treatment_from_text(
                " ".join(
                    part
                    for part in [
                        cls._coerce_text_value(visual_intent),
                        communicate,
                        purpose,
                    ]
                    if cls._coerce_text_value(part).strip()
                )
            )
        treatment_allowed = bool(preference.get("allowed", True))
        treatment = preferred if treatment_allowed else f"{preferred} blocked by layout permissions"

        grounding = preference.get("brand_asset_grounding") if isinstance(preference.get("brand_asset_grounding"), list) else []
        brand_cues: list[str] = []
        for item in grounding[:4]:
            cue = cls._normalize_metadata_text(item, limit=120)
            if cue and cue not in brand_cues:
                brand_cues.append(cue)
        if not brand_cues:
            brand_cues = cls._brand_visual_grounding_evidence(
                visual_identity=visual_identity,
                reference_assets=reference_assets,
                asset_catalog=asset_catalog,
                compiled_context=compiled_context,
                limit=4,
            )
        brand_cue_text = "; ".join(brand_cues[:4]) or "derive from approved copy, palette, typography, and current visual identity"

        data_lines = data_visualization_anchor_lines if isinstance(data_visualization_anchor_lines, list) else []
        def anchor_count_value(value: Any) -> int:
            try:
                return int(value or 0)
            except (TypeError, ValueError):
                return 0

        anchor_count = max(
            anchor_count_value(table_intent.get("anchor_count")),
            anchor_count_value(chart_intent.get("anchor_count")),
            len(metadata.get("data_anchors") if isinstance(metadata.get("data_anchors"), list) else []),
        )
        table_requested = bool(table_intent.get("requested"))
        chart_requested = bool(chart_intent.get("requested"))
        table_allowed = bool(table_intent.get("allowed"))
        chart_allowed = bool(chart_intent.get("allowed"))
        if table_requested or chart_requested:
            if (table_requested and table_allowed) or (chart_requested and chart_allowed):
                data_posture = f"use only approved anchors for any visible data structure; anchor_count={anchor_count}"
            elif anchor_count:
                data_posture = "keep approved facts as callouts or non-data modules unless layout permissions allow data structures"
            else:
                data_posture = "avoid data-visual structures because no approved anchors are available"
        elif data_lines:
            data_posture = "use available factual context for hierarchy or callouts only; do not invent numeric visuals"
        else:
            data_posture = "do not introduce table, chart, dashboard, or axis grammar unless the prompt and anchors require it"

        explicit_data_visual_request = bool(
            request is not None
            and cls._has_explicit_data_visual_request(prompt_text, text_payload=None)
        )
        avoid_parts: list[str] = []
        if not explicit_data_visual_request:
            avoid_parts.append("unrequested data-visual hero treatment")
        if not treatment_allowed:
            avoid_parts.append(f"blocked {preferred} treatment")
        if blueprint:
            avoid_parts.append("new regions outside sample_page_blueprint visual permissions")
        avoid_line = "; ".join(dict.fromkeys(part for part in avoid_parts if part)) or "motifs unsupported by prompt, brand evidence, or approved layout slots"

        craft_posture = (
            "raise craft through the selected treatment and brand-grounded cues"
            if creativity.get("needs_attractive_visual")
            else "keep craft restrained around message clarity and brand fit"
        )
        layout_line = (
            "follow sample_page_blueprint visual_permissions, image_zones, and module slots first"
            if blueprint
            else "stay inside approved visual, image, and module slots from the active layout"
        )
        return (
            "Dynamic visual art direction: "
            f"communicate={communicate}; "
            f"slide purpose={purpose or 'current surface'}; "
            f"treatment={treatment}; "
            f"brand cues={brand_cue_text}; "
            f"data posture={data_posture}; "
            f"craft posture={craft_posture}; "
            f"avoid={avoid_line}; "
            f"layout={layout_line}."
        )

    @classmethod
    def _resolve_reference_creative_profile(
        cls,
        *,
        request: AIOrchestrationRequest | None = None,
        format_name: str = "",
        sample_page_blueprint: Any = None,
        visual_identity: Any = None,
        visual_plan: dict[str, Any] | None = None,
        structured_visual_metadata: Any = None,
        layout_budget: dict[str, Any] | None = None,
        slide: dict[str, Any] | None = None,
        metadata: dict[str, Any] | None = None,
        slide_purpose: Any = "",
        reference_assets: Any = None,
        asset_catalog: Any = None,
        compiled_context: dict[str, Any] | None = None,
        logo_position_hint: str = "",
    ) -> dict[str, Any]:
        blueprint = (
            cls._sample_blueprint_without_rendered_footer_text(sample_page_blueprint)
            if isinstance(sample_page_blueprint, dict)
            else {}
        )
        identity = visual_identity if isinstance(visual_identity, dict) else {}
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        structured = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        context = compiled_context if isinstance(compiled_context, dict) else {}
        adaptation_profile = (
            context.get("reference_adaptation_profile")
            if isinstance(context.get("reference_adaptation_profile"), dict)
            else {}
        )
        preference = structured.get("visual_treatment_preference") if isinstance(structured.get("visual_treatment_preference"), dict) else {}
        budget = layout_budget if isinstance(layout_budget, dict) else {}
        slide_payload = slide if isinstance(slide, dict) else {}
        meta = metadata if isinstance(metadata, dict) else {}
        counts = blueprint.get("module_counts") if isinstance(blueprint.get("module_counts"), dict) else {}
        permissions = cls._sample_visual_permissions(blueprint)

        layout_mode = cls._sample_blueprint_layout_mode(blueprint)
        layout_instruction = cls._sample_blueprint_layout_instruction(blueprint)
        layout_system = cls._normalize_metadata_text(
            " | ".join(
                part
                for part in [
                    cls._normalize_metadata_text(blueprint.get("layout_category"), limit=80),
                    cls._normalize_metadata_text(layout_mode, limit=80),
                    cls._normalize_metadata_text(blueprint.get("density"), limit=40),
                    cls._normalize_metadata_text(layout_instruction, limit=180),
                ]
                if part
            ),
            limit=320,
        )

        palette_roles = derive_palette_roles(identity) if identity else {}
        if not palette_roles and isinstance(identity.get("palette_roles"), dict):
            palette_roles = identity.get("palette_roles") or {}
        color_roles = {
            role: value
            for role in ("background", "surface", "primary", "secondary", "accent")
            if (value := cls._normalize_metadata_text(palette_roles.get(role), limit=32))
        }
        if not color_roles:
            color_roles = {
                "policy": "derive background, primary, secondary, accent, and legal/footer roles from approved brand or reference evidence"
            }

        typography = identity.get("typography") or identity.get("typography_guide") or {}
        typography_roles: dict[str, Any] = {}
        if isinstance(typography, dict):
            for role in ("headline", "subheadline", "callout", "body", "label", "source", "footer"):
                value = (
                    typography.get(role)
                    or typography.get(f"{role}_style")
                    or typography.get(f"{role}_role")
                )
                normalized = cls._normalize_metadata_text(value, limit=80)
                if normalized:
                    typography_roles[role] = normalized
        typography_roles.setdefault(
            "hierarchy_policy",
            "separate headline, subheadline, callout, body, label, source, and footer roles; do not make every text block bold or large",
        )

        brand_grounding = cls._brand_visual_grounding_evidence(
            visual_identity=identity,
            reference_assets=reference_assets,
            asset_catalog=asset_catalog,
            compiled_context=compiled_context,
            include_reusable_design_assets=not bool(blueprint),
            limit=4,
        )
        image_style_parts = [
            f"treatment={cls._normalize_metadata_text(preference.get('preferred'), limit=40)}"
            if preference.get("preferred")
            else "",
            cls._normalize_metadata_text(plan.get("mode"), limit=60),
            cls._normalize_metadata_text(plan.get("rationale"), limit=120),
            cls._normalize_metadata_text(meta.get("reference_visual_craft"), limit=140),
            "; ".join(brand_grounding[:3]),
        ]
        image_style = cls._normalize_metadata_text(
            " | ".join(part for part in image_style_parts if part),
            limit=320,
        ) or "derive image treatment from approved visual identity, reference assets, and current slide role"

        role_text = cls._normalize_metadata_text(
            " ".join(
                part
                for part in [
                    slide_payload.get("role"),
                    meta.get("story_role"),
                    meta.get("carousel_archetype"),
                    slide_purpose,
                    layout_mode,
                    cls._normalize_metadata_text(blueprint.get("layout_category"), limit=80),
                ]
                if cls._coerce_text_value(part).strip()
            ),
            limit=260,
        ).casefold()
        if re.search(r"\b(hook|cover|opening|opener|title)\b", role_text):
            slide_archetype = "hook/opener"
        elif re.search(r"\b(persona|example|story|relatable)\b", role_text):
            slide_archetype = "relatable persona setup"
        elif re.search(r"\b(problem|mistake|risk|pain|warning)\b", role_text):
            slide_archetype = "problem/mistake"
        elif re.search(r"\b(process|workflow|step|journey|behavior|behaviour|change)\b", role_text):
            slide_archetype = "behavior change/process"
        elif re.search(r"\b(proof|calculation|comparison|compare|table|chart|metric|data)\b", role_text):
            slide_archetype = "proof/calculation/comparison"
        elif re.search(r"\b(cta|close|closing|summary|takeaway|final|insight)\b", role_text):
            slide_archetype = "insight/CTA/summary"
        else:
            slide_archetype = "current slide role"

        persona_context = getattr(request, "persona_context", {}) if request is not None else {}
        persona_context = persona_context if isinstance(persona_context, dict) else {}
        persona_source_values: list[Any] = []
        for key in (
            "persona_summary",
            "audience_summary",
            "motivations",
            "pain_points",
            "objections",
            "language_preference",
        ):
            value = persona_context.get(key)
            if isinstance(value, (list, tuple, set)):
                persona_source_values.extend(value)
            else:
                persona_source_values.append(value)
        persona_clues = cls._normalize_metadata_list(persona_source_values, limit=4)
        persona_policy = (
            "reuse one non-sensitive audience/persona brief across the carousel: " + "; ".join(persona_clues)
            if persona_clues
            else "do not invent a recurring persona unless prompt, slide role, or reference evidence requires one"
        )

        logo_policy = cls._normalize_metadata_text(budget.get("brand_header_policy"), limit=180)
        if logo_policy and "brand header slot" in logo_policy.casefold() and "brand-header" not in logo_policy.casefold():
            logo_policy = f"{logo_policy}; brand-header slot alias for the reserved logo/header zone"
        if not logo_policy:
            logo_position = (
                cls._normalize_metadata_text(logo_position_hint, limit=64)
                or cls._sample_blueprint_logo_position(blueprint)
            )
            logo_policy = (
                f"reserve the approved brand-header slot at {logo_position}; use exact asset overlay when available and do not redraw the mark"
                if logo_position
                else "reserve any approved brand-header/logo zone from the active layout; use exact asset overlay when available and do not redraw the mark"
            )

        footer_policy = cls._normalize_metadata_text(budget.get("footer_policy"), limit=220)
        if not footer_policy:
            footer_count = cls._int_or_none(counts.get("footer_band_count")) or 0
            footer_policy = (
                "reserve observed footer/disclaimer band before visual placement; keep characters, icons, captions, CTA, and objects outside it"
                if footer_count
                else "if backend footer/disclaimer metadata exists, exclude that safe area from content and visual-object placement"
            )

        object_density_parts: list[str] = []
        for key in (
            "large_visual_count",
            "small_icon_like_count",
            "card_like_count",
            "horizontal_band_count",
            "text_block_count",
        ):
            value = cls._int_or_none(counts.get(key))
            if value is not None:
                object_density_parts.append(f"{key}={value}")
        visible_capacity = cls._int_or_none(budget.get("visible_capacity"))
        if visible_capacity is not None:
            object_density_parts.append(f"visible_content_capacity={visible_capacity}")
        object_density = (
            "; ".join(object_density_parts)
            + "; do not add extra hero objects, icons, callouts, or decorative metaphors beyond observed capacity"
            if object_density_parts
            else "use the minimum hero objects, icons, callouts, and decorative metaphors needed for the approved layout"
        )

        treatment_policy = cls._normalize_metadata_text(preference.get("preferred"), limit=40) or "brand_led"
        if permissions:
            treatment_policy += "; obey sample visual_permissions"

        return {
            "layout_system": layout_system or "derive from active layout slots",
            "color_roles": color_roles,
            "typography_roles": typography_roles,
            "image_style": image_style,
            "logo_header_policy": logo_policy,
            "footer_safe_policy": footer_policy,
            "slide_archetype": slide_archetype,
            "persona_policy": persona_policy,
            "object_density": object_density,
            "visual_treatment_consistency": treatment_policy,
            "reference_obedience": (
                "sample_first"
                if blueprint
                else (
                    cls._normalize_metadata_text(adaptation_profile.get("adaptation_mode"), limit=64)
                    if adaptation_profile
                    else "brand_context_first"
                )
            ),
            "reference_adaptation_mode": cls._normalize_metadata_text(adaptation_profile.get("adaptation_mode"), limit=64) if adaptation_profile else "",
        }

    @classmethod
    def _reference_creative_profile_prompt_section(cls, profile: Any) -> str:
        if not isinstance(profile, dict) or not profile:
            return ""
        profile = dict(profile)
        if "logo_header_policy" not in profile and profile.get("brand_header_policy"):
            profile["logo_header_policy"] = profile.get("brand_header_policy")
        if "footer_safe_policy" not in profile and profile.get("footer_policy"):
            profile["footer_safe_policy"] = profile.get("footer_policy")
        compact = json.dumps(profile, ensure_ascii=True, separators=(",", ":"))
        return (
            f"Reference creative profile JSON: {compact}. "
            "Use this as source-aware creative DNA for layout, color roles, typography hierarchy, image composition, persona continuity, brand-header handling, footer-safe placement, and object density. "
            "It must enhance only approved slots; do not copy literal sample text, artwork, brand mark, or unrelated subject matter, and do not modify structured_visual_metadata.data_anchors."
        )

    @classmethod
    def _compact_prompt_json_value(
        cls,
        value: Any,
        *,
        depth: int = 0,
        max_depth: int = 3,
        list_limit: int = 6,
        text_limit: int = 180,
    ) -> Any:
        if value in ("", None, [], {}):
            return None
        if isinstance(value, dict):
            compact: dict[str, Any] = {}
            for key, item in value.items():
                normalized_key = cls._normalize_metadata_text(key, limit=64)
                if not normalized_key:
                    continue
                if depth >= max_depth and isinstance(item, (dict, list, tuple, set)):
                    if isinstance(item, dict):
                        scalar_items = {
                            cls._normalize_metadata_text(nested_key, limit=64): cls._compact_prompt_json_value(
                                nested_value,
                                depth=depth + 1,
                                max_depth=max_depth,
                                list_limit=list_limit,
                                text_limit=text_limit,
                            )
                            for nested_key, nested_value in list(item.items())[:list_limit]
                            if not isinstance(nested_value, (dict, list, tuple, set))
                        }
                        compact_value = {k: v for k, v in scalar_items.items() if k and v not in ("", None, [], {})}
                    else:
                        compact_value = [
                            cls._compact_prompt_json_value(
                                nested,
                                depth=depth + 1,
                                max_depth=max_depth,
                                list_limit=list_limit,
                                text_limit=text_limit,
                            )
                            for nested in list(item)[:list_limit]
                        ]
                        compact_value = [nested for nested in compact_value if nested not in ("", None, [], {})]
                else:
                    compact_value = cls._compact_prompt_json_value(
                        item,
                        depth=depth + 1,
                        max_depth=max_depth,
                        list_limit=list_limit,
                        text_limit=text_limit,
                    )
                if compact_value not in ("", None, [], {}):
                    compact[normalized_key] = compact_value
            return compact or None
        if isinstance(value, (list, tuple, set)):
            compact_list = [
                cls._compact_prompt_json_value(
                    item,
                    depth=depth + 1,
                    max_depth=max_depth,
                    list_limit=list_limit,
                    text_limit=text_limit,
                )
                for item in list(value)[:list_limit]
            ]
            compact_list = [item for item in compact_list if item not in ("", None, [], {})]
            return compact_list or None
        if isinstance(value, str):
            return cls._normalize_metadata_text(value, limit=text_limit)
        return value

    @classmethod
    def _compact_reference_adaptation_profile_for_prompt(cls, profile: dict[str, Any]) -> dict[str, Any]:
        compact: dict[str, Any] = {}
        for key in (
            "source_format_family",
            "output_format_family",
            "selected_output_behavior",
            "adaptation_mode",
            "confidence",
            "adapt",
            "do_not_adapt",
            "balance",
        ):
            if key not in profile:
                continue
            compact_value = cls._compact_prompt_json_value(
                profile.get(key),
                max_depth=3,
                list_limit=6,
                text_limit=160,
            )
            if compact_value not in ("", None, [], {}):
                compact[key] = compact_value
        if isinstance(profile.get("template_structure"), dict) and profile.get("template_structure"):
            compact["template_structure_available"] = True
        return compact or dict(profile)

    @classmethod
    def _reference_adaptation_profile_prompt_section(cls, profile: Any) -> str:
        if not isinstance(profile, dict) or not profile:
            return ""
        compact_profile = cls._compact_reference_adaptation_profile_for_prompt(profile)
        compact = json.dumps(compact_profile, ensure_ascii=True, separators=(",", ":"))
        return (
            f"Reference adaptation profile JSON: {compact}. "
            "Use adaptation_mode to decide whether the active source is a template sequence, infographic surface, static creative, hybrid visual guide, or brand-only fallback. "
            "Apply only the visual-system traits marked in adapt; do not copy literal source text, source subject matter, unsupported claims, brand marks without permission, or unsupported data visuals. "
            "Conflict rule: current prompt content and approved evidence come first, reference visual system second, and footer/logo/data-anchor safety overrides both."
        )

    @classmethod
    def _generation_surface_contract_prompt_section(cls, contract: Any) -> str:
        if not isinstance(contract, dict) or not contract:
            return ""
        compact = json.dumps(contract, ensure_ascii=True, separators=(",", ":"))
        return (
            f"Generation surface contract JSON: {compact}. "
            "Selected format, platform, size, file type, and campaign goal define the output surface. "
            "Reference format can guide only compatible visual grammar; it must not convert static output into carousel, carousel output into a poster, or infographic output into generic static layout. "
            "File type controls export/render path only, not content meaning."
        )

    @classmethod
    def _reference_template_structure_payload(
        cls,
        compiled_context: dict[str, Any] | None,
        profile: dict[str, Any],
        *,
        source_family: str,
        output_family: str,
        layout_content_budget: dict[str, Any] | None = None,
        sample_page_blueprint: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        context = compiled_context if isinstance(compiled_context, dict) else {}
        structure = profile.get("template_structure") if isinstance(profile.get("template_structure"), dict) else {}
        runtime_blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}

        def normalize_family(value: Any) -> str:
            text = cls._normalize_metadata_text(value, limit=48).casefold()
            normalized = text.replace("-", "_").replace(" ", "_").replace("/", "_").strip("_")
            if normalized in {"static", "story", "poster", "hero", "single_frame"}:
                return "static"
            if normalized in {"carousel", "carousel_series", "slide_deck", "slide_series"}:
                return "carousel"
            if normalized in {"infographic", "diagram", "visual_explainer"}:
                return "infographic"
            return normalized if normalized in {"static", "carousel", "infographic"} else ""

        def trusted_reference(item: Any) -> bool:
            if not isinstance(item, dict):
                return False
            role = cls._normalize_metadata_text(item.get("role") or item.get("asset_role"), limit=32).casefold()
            trust = cls._normalize_metadata_text(item.get("trust_level"), limit=32).casefold()
            return (
                role in {"reference_creative", "template", "reference", "template_sequence"}
                and trust not in {"rejected", "blocked", "untrusted"}
            )

        selected_asset: dict[str, Any] = {}
        for item in context.get("reference_asset_brief") or []:
            if not isinstance(item, dict) or not trusted_reference(item):
                continue
            if normalize_family(item.get("format_family") or item.get("format")) == source_family:
                selected_asset = item
                break

        blueprint = (
            structure.get("sample_page_blueprint")
            if isinstance(structure.get("sample_page_blueprint"), dict)
            else profile.get("sample_page_blueprint")
            if isinstance(profile.get("sample_page_blueprint"), dict)
            else selected_asset.get("sample_page_blueprint")
            if isinstance(selected_asset.get("sample_page_blueprint"), dict)
            else runtime_blueprint
            if runtime_blueprint
            else {}
        )
        blueprint = cls._sample_blueprint_without_rendered_footer_text(blueprint) if blueprint else {}
        module_counts = (
            blueprint.get("module_counts")
            if isinstance(blueprint.get("module_counts"), dict)
            else structure.get("module_counts")
            if isinstance(structure.get("module_counts"), dict)
            else profile.get("module_counts")
            if isinstance(profile.get("module_counts"), dict)
            else {}
        )
        visual_permissions = (
            blueprint.get("visual_permissions")
            if isinstance(blueprint.get("visual_permissions"), dict)
            else structure.get("visual_permissions")
            if isinstance(structure.get("visual_permissions"), dict)
            else profile.get("visual_permissions")
            if isinstance(profile.get("visual_permissions"), dict)
            else {}
        )
        layout_dna = (
            structure.get("layout_dna")
            if isinstance(structure.get("layout_dna"), dict)
            else selected_asset.get("layout_dna")
            if isinstance(selected_asset.get("layout_dna"), dict)
            else {}
        )
        composition_logic = (
            structure.get("composition_logic")
            if isinstance(structure.get("composition_logic"), dict)
            else selected_asset.get("composition_logic")
            if isinstance(selected_asset.get("composition_logic"), dict)
            else {}
        )
        structural_cues = (
            structure.get("structural_cues")
            if isinstance(structure.get("structural_cues"), list)
            else selected_asset.get("structural_cues")
            if isinstance(selected_asset.get("structural_cues"), list)
            else []
        )
        template_layout_grammar = (
            structure.get("template_layout_grammar")
            if isinstance(structure.get("template_layout_grammar"), dict)
            else profile.get("template_layout_grammar")
            if isinstance(profile.get("template_layout_grammar"), dict)
            else selected_asset.get("template_layout_grammar")
            if isinstance(selected_asset.get("template_layout_grammar"), dict)
            else {}
        )
        budget = layout_content_budget if isinstance(layout_content_budget, dict) else {}
        surface_contract = (
            context.get("generation_surface_contract")
            if isinstance(context.get("generation_surface_contract"), dict)
            else {}
        )
        surface_budget = surface_contract.get("content_budget") if isinstance(surface_contract.get("content_budget"), dict) else {}

        payload: dict[str, Any] = {
            "selected_output_format": output_family,
            "reference_source_family": source_family,
        }
        if blueprint:
            sample_payload: dict[str, Any] = {}
            for key, limit in (("layout_category", 80), ("density", 40)):
                value = cls._normalize_metadata_text(blueprint.get(key), limit=limit)
                if value:
                    sample_payload[key] = value
            layout_mode = cls._sample_blueprint_layout_mode(blueprint)
            if layout_mode:
                sample_payload["layout_mode"] = layout_mode
            if module_counts:
                sample_payload["module_counts"] = module_counts
            if visual_permissions:
                sample_payload["visual_permissions"] = visual_permissions
            image_zones = blueprint.get("image_zones") if isinstance(blueprint.get("image_zones"), list) else []
            if image_zones:
                sample_payload["image_zones"] = image_zones[:4]
            layout_instruction = cls._sample_blueprint_layout_instruction(blueprint)
            if layout_instruction:
                sample_payload["layout_instruction"] = layout_instruction
            if sample_payload:
                payload["sample_page_blueprint"] = sample_payload
        elif module_counts or visual_permissions:
            payload["sample_page_blueprint"] = {
                **({"module_counts": module_counts} if module_counts else {}),
                **({"visual_permissions": visual_permissions} if visual_permissions else {}),
            }
        if layout_dna:
            compact_layout_dna = cls._compact_prompt_json_value(
                layout_dna,
                max_depth=2,
                list_limit=6,
                text_limit=120,
            )
            if compact_layout_dna:
                payload["layout_dna"] = compact_layout_dna
        if composition_logic:
            compact_composition_logic = cls._compact_prompt_json_value(
                composition_logic,
                max_depth=2,
                list_limit=6,
                text_limit=120,
            )
            if compact_composition_logic:
                payload["composition_logic"] = compact_composition_logic
        if structural_cues:
            payload["structural_cues"] = [
                cls._normalize_metadata_text(item, limit=80)
                for item in structural_cues[:8]
                if cls._normalize_metadata_text(item, limit=80)
            ]
        if template_layout_grammar:
            compact_template_layout_grammar = cls._compact_prompt_json_value(
                template_layout_grammar,
                max_depth=2,
                list_limit=8,
                text_limit=100,
            )
            if compact_template_layout_grammar:
                payload["template_layout_grammar"] = compact_template_layout_grammar
        layout_budget_payload: dict[str, Any] = {}
        for key in (
            "canvas_summary",
            "brand_header_policy",
            "footer_policy",
            "cta_policy",
            "visible_capacity",
            "overflow_count",
            "capacity_source",
            "density_label",
            "density_policy",
        ):
            value = budget.get(key)
            if value not in ("", {}, [], None):
                layout_budget_payload[key] = value
        if layout_budget_payload:
            payload["layout_content_budget"] = layout_budget_payload
        elif surface_budget:
            payload["surface_content_budget"] = surface_budget
        return {key: value for key, value in payload.items() if value not in ("", None, {}, [])}

    @classmethod
    def _reference_template_sample_page_blueprint(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        format_name: str,
    ) -> dict[str, Any]:
        context = compiled_context if isinstance(compiled_context, dict) else {}
        profile = context.get("reference_adaptation_profile") if isinstance(context.get("reference_adaptation_profile"), dict) else {}
        if not profile:
            return {}
        source_family = cls._normalize_metadata_text(profile.get("source_format_family"), limit=32).casefold()
        output_family = (
            cls._normalize_metadata_text(profile.get("output_format_family"), limit=32).casefold()
            or cls._normalize_metadata_text(format_name, limit=32).casefold()
        )
        if source_family != output_family or output_family not in {"static", "infographic"}:
            return {}
        try:
            confidence = float(profile.get("confidence") or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        if confidence <= 0.0:
            return {}
        payload = cls._reference_template_structure_payload(
            context,
            profile,
            source_family=source_family,
            output_family=output_family,
        )
        sample = payload.get("sample_page_blueprint") if isinstance(payload.get("sample_page_blueprint"), dict) else {}
        blueprint = (
            profile.get("template_structure", {}).get("sample_page_blueprint")
            if isinstance(profile.get("template_structure"), dict)
            and isinstance(profile.get("template_structure", {}).get("sample_page_blueprint"), dict)
            else profile.get("sample_page_blueprint")
            if isinstance(profile.get("sample_page_blueprint"), dict)
            else {}
        )
        if not blueprint:
            for item in context.get("reference_asset_brief") or []:
                if not isinstance(item, dict):
                    continue
                family = cls._normalize_metadata_text(item.get("format_family") or item.get("format"), limit=32).casefold()
                if family == source_family and isinstance(item.get("sample_page_blueprint"), dict):
                    blueprint = item.get("sample_page_blueprint")
                    break
        if blueprint:
            return cls._sample_blueprint_without_rendered_footer_text(blueprint)
        return sample

    @classmethod
    def _reference_template_adaptation_prompt_sections(
        cls,
        compiled_context: dict[str, Any] | None,
        *,
        format_name: str,
        layout_content_budget: dict[str, Any] | None = None,
        sample_page_blueprint: dict[str, Any] | None = None,
    ) -> list[str]:
        context = compiled_context if isinstance(compiled_context, dict) else {}
        profile = context.get("reference_adaptation_profile") if isinstance(context.get("reference_adaptation_profile"), dict) else {}
        runtime_blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else {}
        if not profile:
            output_family = cls._normalize_metadata_text(format_name, limit=32).casefold()
            if output_family not in {"static", "infographic"} or not runtime_blueprint:
                return []
            profile = {
                "source_format_family": output_family,
                "output_format_family": output_family,
                "selected_output_behavior": (
                    "infographic_surface_output"
                    if output_family == "infographic"
                    else "static_creative_output"
                ),
                "adaptation_mode": (
                    "infographic_surface_adaptation"
                    if output_family == "infographic"
                    else "static_creative_adaptation"
                ),
                "confidence": 1.0,
                "adapt": {
                    "layout_rhythm": True,
                    "module_density": True,
                    "logo_footer_policy": True,
                    "slide_archetype": True,
                },
                "template_structure": {
                    "sample_page_blueprint": cls._sample_blueprint_without_rendered_footer_text(runtime_blueprint),
                },
            }
        mode = cls._normalize_metadata_text(profile.get("adaptation_mode"), limit=64).casefold()
        if mode in {"", "brand_only", "video_output_disabled_or_unsupported"}:
            return []
        source_family = cls._normalize_metadata_text(profile.get("source_format_family"), limit=32).casefold()
        output_family = (
            cls._normalize_metadata_text(profile.get("output_format_family"), limit=32).casefold()
            or cls._normalize_metadata_text(format_name, limit=32).casefold()
        )
        if source_family not in {"carousel", "infographic", "static"}:
            return []
        if output_family not in {"carousel", "infographic", "static"}:
            return []
        if output_family == "carousel" and source_family == "carousel":
            return []
        try:
            confidence = float(profile.get("confidence") or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        if confidence <= 0.0:
            return []

        adapt = profile.get("adapt") if isinstance(profile.get("adapt"), dict) else {}
        active_traits = [
            label
            for key, label in (
                ("layout_rhythm", "layout rhythm"),
                ("module_density", "module density"),
                ("color_roles", "color roles"),
                ("typography_hierarchy", "typography hierarchy"),
                ("image_treatment", "image treatment"),
                ("logo_footer_policy", "logo/header and footer policy"),
                ("slide_archetype", "surface/slide archetype"),
            )
            if adapt.get(key)
        ]
        selected_behavior = cls._normalize_metadata_text(profile.get("selected_output_behavior"), limit=64)
        trait_summary = ", ".join(active_traits) if active_traits else "compatible visual-system traits"
        sections = [
            (
                "Reference template adaptation contract: "
                f"selected output format is {output_family}; reference source family is {source_family}; "
                f"adaptation mode is {mode}; selected output behavior is {selected_behavior or output_family}. "
                f"Apply only these approved visual-system traits: {trait_summary}. "
                "Prompt content and approved evidence remain the subject authority; reference text, claims, topic, and brand marks are not source material."
            ),
            (
                "Reference adaptation safety: preserve layout rhythm, module positions, hierarchy, typography scale roles, color roles, image treatment, object density, logo/header policy, footer/legal policy, spacing rhythm, and composition grammar only where compatible. "
                "This contract does not authorize charts, tables, dashboards, metrics, or data visuals; structured_visual_metadata.data_anchors and sample visual_permissions remain the only data-visual gate."
            ),
        ]
        structure_payload = cls._reference_template_structure_payload(
            context,
            profile,
            source_family=source_family,
            output_family=output_family,
            layout_content_budget=layout_content_budget,
            sample_page_blueprint=runtime_blueprint,
        )
        if structure_payload and source_family == output_family and output_family in {"static", "infographic"}:
            compact_structure = json.dumps(structure_payload, ensure_ascii=True, separators=(",", ":"))
            infographic_structure_guidance = (
                "For infographic outputs, preserve repeated card/row/panel rhythm, section cadence, connector/callout spacing, and vertical explanatory flow before adding new decorative ideas. "
                if output_family == "infographic"
                else ""
            )
            sections.append(
                f"{output_family.title()} template structure lock JSON: {compact_structure}. "
                "Treat sample_page_blueprint, template_layout_grammar, module_counts, visual_permissions, image_zones, and layout_content_budget as the prompt-visible layout payload. "
                "Map the current prompt content into the observed template modules; preserve macro flow, section ordering, card/panel/box shells, row/column rhythm, connector/callout/takeaway behavior, visual density, spacing roles, typography roles, color roles, and safe-area posture before adding new decorative ideas. "
                f"{infographic_structure_guidance}"
                "Replace the reference topic, copy, claims, numbers, image objects, icons, and assets with prompt-relevant content and prompt-relevant replacement visuals. "
                "If content exceeds visible capacity, compress or summarize within the observed layout instead of changing module counts, inventing unsupported regions, or copying reference source text."
            )
            sections.append(
                f"{output_family.title()} fallback takeover guard: any fallback photo, illustration, object, or human-subject visual can only fill an approved image zone or large-visual slot from the template payload. "
                "It must not become the whole composition, turn into an unrelated scenic, cartographic, dashboard, or hero redesign, erase headline/support/proof/CTA surfaces, remove card/panel/row/callout shells, or override header/logo and footer safe areas."
            )
        elif structure_payload and source_family != output_family:
            compact_structure = json.dumps(structure_payload, ensure_ascii=True, separators=(",", ":"))
            sections.append(
                f"Compatible reference template structure JSON: {compact_structure}. "
                "Use this only as compatible layout DNA; selected output format remains authoritative and current prompt content remains the subject authority."
            )
        if output_family == "static":
            if source_family == "static":
                sections.append(
                    "Static template adaptation: strongly adapt the trusted static reference as a single finished poster/hero system. "
                    "Preserve header/body/CTA/footer hierarchy, dominant-message path, image placement and focal object structure, whitespace, object density, color-role logic, typography-role hierarchy, logo/header policy, and footer/legal safe zones."
                )
            else:
                sections.append(
                    "Static cross-format adaptation: selected Static output remains a single static creative. "
                    "Use the reference only as compatible visual-system guidance; do not force carousel pagination, multi-slide sequence logic, infographic row structure, or a diagram-first surface unless the selected static layout and prompt explicitly support it."
                )
        elif output_family == "infographic":
            if source_family == "infographic":
                sections.append(
                    "Infographic template adaptation: strongly adapt the trusted infographic surface grammar. "
                    "Preserve section hierarchy, module grouping, row/column rhythm, connector/arrow relationship logic, callout/card/panel hierarchy, compact typography, diagram-first composition, color-role logic, and header/footer safe zones."
                )
            else:
                sections.append(
                    "Infographic cross-format adaptation: selected Infographic output remains an infographic surface. "
                    "Use the reference only for compatible visual rhythm, hierarchy, and craft; do not collapse into a generic static poster, a plain hero image, or carousel pagination."
                )
        elif output_family == "carousel" and source_family != "carousel":
            sections.append(
                "Carousel cross-format adaptation: selected Carousel output remains a slide sequence. "
                "Translate compatible reference rhythm into slide-safe modules and recurring visual grammar; do not let a static reference cause single-frame takeover or an infographic reference force one dense all-in-one surface."
            )
        return sections

    @classmethod
    def _visual_quality_bar_for_treatment(cls, structured_visual_metadata: Any) -> str:
        metadata = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        preference = metadata.get("visual_treatment_preference") if isinstance(metadata.get("visual_treatment_preference"), dict) else {}
        treatment = cls._normalize_metadata_text(preference.get("preferred"), limit=40).casefold()
        allowed = bool(preference.get("allowed", True))
        if not allowed:
            return (
                "Visual quality bar: clean, modern, brand-safe composition that avoids the blocked visual treatment and keeps the message clear."
            )
        if treatment in {"3d", "isometric"}:
            return (
                "Visual quality bar: polished dimensional treatment with controlled lighting, coherent materials, clean negative space, and brand-safe accents."
            )
        if treatment == "photo_composite":
            return (
                "Visual quality bar: polished photographic or composite-led scene with credible subject matter, natural lighting, and clean copy-safe space."
            )
        if treatment == "data_module":
            return (
                "Visual quality bar: sparse data/module composition tied only to approved anchors, with clean hierarchy and no invented metrics."
            )
        if treatment == "icon_system":
            return (
                "Visual quality bar: crisp icon-system or pictorial explainer with intentional spacing, consistent stroke/detail language, and restrained brand accents."
            )
        if treatment in {"2d", "flat_editorial"}:
            return (
                "Visual quality bar: polished flat/editorial composition with strong hierarchy, refined surfaces, clean negative space, and brand-safe accents."
            )
        if treatment == "document_evidence":
            return (
                "Visual quality bar: credible document/evidence-led composition with clean hierarchy, realistic context cues, and no fabricated values."
            )
        return (
            "Visual quality bar: premium, high-end, richly detailed brand-led imagery with elegant negative space, clear hierarchy, and brand-safe color accents."
        )

    @classmethod
    def _dynamic_layout_content_budget(
        cls,
        *,
        request: AIOrchestrationRequest | None = None,
        format_name: str = "",
        text_payload: StructuredTextPayload | None = None,
        slide: dict[str, Any] | None = None,
        metadata: dict[str, Any] | None = None,
        sample_page_blueprint: Any = None,
        scene_graph: GenerationSceneGraph | None = None,
        legal_footer_text: Any = "",
        disclaimer_guidance: Any = "",
        logo_position_hint: str = "",
    ) -> dict[str, Any]:
        payload = text_payload
        slide_payload = slide if isinstance(slide, dict) else {}
        meta = metadata if isinstance(metadata, dict) else {}
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else (
            meta.get("sample_page_blueprint") if isinstance(meta.get("sample_page_blueprint"), dict) else {}
        )
        counts = blueprint.get("module_counts") if isinstance(blueprint.get("module_counts"), dict) else {}
        permissions = cls._sample_visual_permissions(blueprint)

        def count_int(key: str) -> int:
            try:
                return int(counts.get(key) or 0)
            except (TypeError, ValueError):
                return 0

        studio_panel = getattr(request, "studio_panel", {}) if request is not None else {}
        studio_panel = studio_panel if isinstance(studio_panel, dict) else {}
        size = studio_panel.get("size") if isinstance(studio_panel.get("size"), dict) else {}
        canvas = getattr(scene_graph, "canvas", None)
        width = int(getattr(canvas, "width", None) or size.get("width") or 0)
        height = int(getattr(canvas, "height", None) or size.get("height") or 0)
        aspect_ratio = round(width / height, 3) if width and height else 0
        aspect_label = (
            "landscape"
            if aspect_ratio > 1.15
            else "portrait"
            if aspect_ratio and aspect_ratio < 0.95
            else "square"
            if aspect_ratio
            else "unknown"
        )
        canvas_summary = f"{width}x{height} {aspect_label}" if width and height else f"{aspect_label} canvas"

        prompt_text = getattr(request, "prompt", "") if request is not None else ""
        legal_footer = cls._normalize_metadata_text(legal_footer_text, limit=420)
        disclaimer = cls._normalize_metadata_text(disclaimer_guidance, limit=180)
        brief = getattr(request, "research_editorial_brief", {}) if request is not None else {}
        brief = brief if isinstance(brief, dict) else {}
        footer_band_count = count_int("footer_band_count")
        footer_requested = bool(
            legal_footer
            or disclaimer
            or brief.get("disclaimer_requested")
            or ("disclaimer" in str(prompt_text or "").casefold())
            or footer_band_count > 0
        )
        footer_source = (
            "sample_page_blueprint footer_band_count"
            if footer_band_count > 0
            else "legal/disclaimer metadata"
            if footer_requested
            else "none"
        )
        footer_policy = (
            f"reserve footer/disclaimer safe area before content and CTA using {footer_source}; "
            "leave exact bottom strip completely blank: no text/icons/objects/charts/cards/shadows/patterns/details"
            if footer_requested
            else "no footer/disclaimer safe area requested"
        )
        footer_safe_area = (
            calculate_footer_safe_area(
                canvas_width=width,
                canvas_height=height,
                footer_text=legal_footer or disclaimer,
            )
            if footer_requested and width and height
            else calculate_footer_safe_area(
                canvas_width=width or 1,
                canvas_height=height or 1,
                footer_text="",
            )
        )
        footer_reserved_height = int(footer_safe_area.get("reserved_height") or 0)
        content_canvas_height = int(footer_safe_area.get("content_canvas_height") or height or 0)
        content_safe_ratio = (
            max(0.0, min(content_canvas_height / max(float(height), 1.0), 1.0))
            if height
            else 1.0
        )
        if footer_requested and footer_reserved_height:
            footer_policy = (
                f"{footer_policy}; actual footer_safe_area reserves {footer_reserved_height}px "
                f"({footer_safe_area.get('reserved_ratio')}) and leaves {content_canvas_height}px content-safe height"
            )
        format_key = str(format_name or "").strip().casefold()
        if footer_requested and format_key == "infographic":
            footer_policy = " ".join(
                [
                    footer_policy,
                    cls._infographic_footer_safe_layout_contract(
                        format_name=format_key,
                        footer_requested=True,
                        footer_safe_area=footer_safe_area,
                    ),
                ]
            ).strip()

        cta_text = cls._normalize_metadata_text(
            getattr(payload, "cta", "") if payload is not None else slide_payload.get("cta") or meta.get("cta"),
            limit=90,
        )
        zones: list[Any] = []
        for key in ("zones", "image_zones", "content_zones"):
            value = blueprint.get(key)
            if isinstance(value, list):
                zones.extend(value)
        has_cta_slot = count_int("cta_count") > 0 or any(
            isinstance(zone, dict)
            and "cta" in " ".join(
                cls._normalize_metadata_text(zone.get(key), limit=60)
                for key in ("role", "name", "label", "zone_role")
            ).casefold()
            for zone in zones
        )
        cta_allowed = permissions.get("cta_allowed", True) is not False
        cta_render_allowed = bool(cta_text and cta_allowed and (has_cta_slot or (not footer_requested and not blueprint)))
        if cta_text and not cta_allowed:
            cta_policy = "no approved CTA slot: omit CTA shell or downgrade to a quiet approved content module outside footer/disclaimer"
        elif cta_text and footer_requested and not has_cta_slot:
            cta_policy = "no safe CTA slot above reserved footer/disclaimer: omit CTA shell or downgrade to text-only intent outside the image"
        elif cta_text and footer_requested:
            cta_policy = "CTA may render only in a CTA-safe slot above the reserved footer/disclaimer safe area; omit if no such slot exists"
        elif cta_text and blueprint and not has_cta_slot:
            cta_policy = "CTA has no explicit blueprint slot; render only if the active layout already reserves a CTA-safe zone"
        elif cta_text:
            cta_policy = "CTA must stay inside an approved CTA-safe slot"
        else:
            cta_policy = "no CTA requested; do not invent CTA button"

        raw_items: list[tuple[str, str]] = []

        def add_line(source: str, value: Any) -> None:
            text = cls._normalize_metadata_text(value, limit=180)
            if text:
                raw_items.append((source, text))

        for source, value in (
            ("proof_points", slide_payload.get("proof_points", meta.get("proof_points"))),
            ("body_points", slide_payload.get("body_points", meta.get("body_points"))),
            ("stat_highlights", slide_payload.get("stat_highlights", meta.get("stat_highlights"))),
        ):
            for item in cls._normalize_metadata_list(value, limit=10):
                add_line(source, item)
        for item in cls._claim_evidence_pair_lines(
            cls._normalize_claim_evidence_pairs(
                slide_payload.get("claim_evidence_pairs", meta.get("claim_evidence_pairs")),
                limit=4,
            ),
            limit=4,
        ):
            add_line("claim_evidence_pairs", item)

        blocked_keys = {
            cls._normalize_metadata_text(item, limit=180).casefold()
            for item in [
                getattr(payload, "headline", "") if payload is not None else slide_payload.get("headline"),
                slide_payload.get("supporting_line") or meta.get("supporting_line"),
                getattr(payload, "body", "") if payload is not None else slide_payload.get("body"),
                cta_text,
            ]
            if cls._normalize_metadata_text(item, limit=180)
        }
        deduped_items: list[tuple[str, str]] = []
        seen: set[str] = set()
        duplicate_count = 0
        for source, text in raw_items:
            key = text.casefold()
            if key in blocked_keys:
                continue
            if key in seen:
                duplicate_count += 1
                continue
            seen.add(key)
            deduped_items.append((source, text))

        capacity_candidates: list[tuple[str, int]] = []
        for key in ("horizontal_band_count", "card_like_count", "small_icon_like_count", "text_block_count"):
            count_value = count_int(key)
            if count_value > 0:
                capacity_candidates.append((key, count_value))
        if capacity_candidates:
            capacity_key, capacity_value = capacity_candidates[0]
            content_safe_capacity = int((capacity_value * content_safe_ratio) + 0.5) if footer_requested else capacity_value
            visible_capacity = max(1, min(content_safe_capacity, capacity_value, 8))
            capacity_source = (
                f"sample_page_blueprint module_counts.{capacity_key} after reserving brand header and footer/disclaimer safe areas"
            )
        else:
            reserved_segments = (1 if footer_requested else 0) + (1 if cta_render_allowed else 0) + (1 if request is not None else 0)
            raw_capacity = max(len(deduped_items) - reserved_segments, 1) if deduped_items else 1
            content_safe_capacity = int((raw_capacity * content_safe_ratio) + 0.5) if footer_requested else raw_capacity
            visible_capacity = max(1, min(content_safe_capacity, raw_capacity, 8))
            capacity_source = "deduped approved item count after reserving brand header, CTA, and footer/disclaimer safe areas"
        if footer_requested and format_key == "infographic" and visible_capacity > 3:
            visible_capacity = 3
            capacity_source = f"{capacity_source} with infographic footer-safe cap"
        visible_item_pairs = deduped_items[:visible_capacity]
        visible_items = [text for _, text in visible_item_pairs]
        overflow_items = [text for _, text in deduped_items[visible_capacity:]]

        headline = cls._normalize_metadata_text(
            getattr(payload, "headline", "") if payload is not None else slide_payload.get("headline"),
            limit=220,
        )
        body = cls._normalize_metadata_text(
            getattr(payload, "body", "") if payload is not None else slide_payload.get("body"),
            limit=360,
        )
        supporting = cls._normalize_metadata_text(slide_payload.get("supporting_line") or meta.get("supporting_line"), limit=220)
        text_pressure = len(headline.split()) + len(body.split()) + len(supporting.split()) + (len(deduped_items) * 8)
        if cta_text:
            text_pressure += 6
        if footer_requested:
            text_pressure += 10
        if request is not None:
            text_pressure += 6
        density_label = (
            "high"
            if text_pressure > 70 or overflow_items
            else "medium"
            if text_pressure > 42 or len(deduped_items) > visible_capacity
            else "low"
        )
        density_policy = (
            f"text density={density_label}; if density is medium/high, compress copy surfaces, prioritize strongest approved points, and reduce visual complexity before rendering"
        )

        logo_policy = "brand header/logo slot=not resolved"
        if request is not None:
            resolved_logo_hint = (
                cls._sample_blueprint_logo_position(blueprint)
                or cls._normalize_logo_position_option(logo_position_hint)
                or cls._effective_logo_position_hint(
                    request=request,
                    creative_decision=CreativeDecisionPayload(),
                    text_payload={"metadata": meta},
                )
            )
            logo_geometry = cls._normalize_logo_safe_zone_geometry(
                request=request,
                geometry=cls._logo_safe_zone_geometry(scene_graph),
                hint=resolved_logo_hint,
            )
            logo_x, logo_y, logo_width, logo_height = logo_geometry
            logo_left_pct = max(int(round(logo_x * 100)), 0)
            logo_top_pct = max(int(round(logo_y * 100)), 0)
            logo_width_pct = max(int(round(logo_width * 100)), 1)
            logo_height_pct = max(int(round(logo_height * 100)), 1)
            logo_left_px = max(int(round(logo_x * max(width, 1))), 0) if width else 0
            logo_top_px = max(int(round(logo_y * max(height, 1))), 0) if height else 0
            logo_width_px = max(int(round(logo_width * max(width, 1))), 1) if width else 0
            logo_height_px = max(int(round(logo_height * max(height, 1))), 1) if height else 0
            footprint_detail = (
                f"initial footprint starts around {logo_left_pct}% left/{logo_top_pct}% top "
                f"({logo_left_px}px/{logo_top_px}px) and measures {logo_width_pct}% x {logo_height_pct}% "
                f"({logo_width_px}px wide x {logo_height_px}px tall); "
                if width and height
                else f"initial footprint starts around {logo_left_pct}% left/{logo_top_pct}% top and measures {logo_width_pct}% x {logo_height_pct}%; "
            )
            logo_policy = (
                f"brand header slot=required readable reserved slot at {cls._logo_reserved_area_label(resolved_logo_hint)} "
                f"using pre-generation backend brand-asset size analysis; {footprint_detail}"
                "reserve this exact blank space before composing the AI image so the exact stored brand asset can be composited, and keep placement consistent across carousel slides unless the sample blueprint overrides it"
            )

        prompt_metadata = {
            "proof_points": visible_items,
            "body_points": [],
            "stat_highlights": [],
            "claim_evidence_pairs": [],
            "layout_content_budget": {
                "visible_capacity": visible_capacity,
                "visible_count": len(visible_items),
                "overflow_count": len(overflow_items),
                "capacity_source": capacity_source,
                "footer_reserved": footer_requested,
                "footer_safe_area": {
                    key: value
                    for key, value in footer_safe_area.items()
                    if not str(key).startswith("_")
                },
                "cta_render_allowed": cta_render_allowed,
                "density": density_label,
            },
        }
        return {
            "canvas_summary": canvas_summary,
            "brand_header_policy": logo_policy,
            "footer_policy": footer_policy,
            "cta_policy": cta_policy,
            "cta_render_allowed": cta_render_allowed,
            "visible_capacity": visible_capacity,
            "visible_items": visible_items,
            "overflow_items": overflow_items,
            "overflow_count": len(overflow_items),
            "capacity_source": capacity_source,
            "duplicate_count": duplicate_count,
            "density_label": density_label,
            "density_policy": density_policy,
            "prompt_metadata": prompt_metadata,
            "prompt_cta": cta_text if cta_render_allowed else "",
        }

    @classmethod
    def _prompt_visible_slide_from_layout_budget(
        cls,
        slide: dict[str, Any],
        layout_budget: dict[str, Any] | None,
    ) -> dict[str, Any]:
        if not isinstance(layout_budget, dict):
            return slide
        prompt_slide = dict(slide)
        prompt_slide["proof_points"] = list(layout_budget.get("visible_items") or [])
        prompt_slide["body_points"] = []
        prompt_slide["stat_highlights"] = []
        prompt_slide["claim_evidence_pairs"] = []
        prompt_slide["cta"] = layout_budget.get("prompt_cta", prompt_slide.get("cta"))
        metadata = dict(prompt_slide.get("metadata") if isinstance(prompt_slide.get("metadata"), dict) else {})
        metadata["layout_content_budget"] = (layout_budget.get("prompt_metadata") or {}).get("layout_content_budget", {})
        prompt_slide["metadata"] = metadata
        return prompt_slide

    @classmethod
    def _prompt_visible_text_payload_from_layout_budget(
        cls,
        text_payload: StructuredTextPayload,
        layout_budget: dict[str, Any] | None,
    ) -> StructuredTextPayload:
        if not isinstance(layout_budget, dict):
            return text_payload
        metadata = dict(text_payload.metadata or {})
        metadata.update(layout_budget.get("prompt_metadata") or {})
        return StructuredTextPayload(
            headline=text_payload.headline,
            body=text_payload.body,
            cta=layout_budget.get("prompt_cta", text_payload.cta),
            hashtags=list(text_payload.hashtags or []),
            metadata=metadata,
        )

    @classmethod
    def _dynamic_layout_quality_guard_section(
        cls,
        *,
        request: AIOrchestrationRequest | None = None,
        format_name: str = "",
        text_payload: StructuredTextPayload | None = None,
        metadata: dict[str, Any] | None = None,
        sample_page_blueprint: Any = None,
        structured_visual_metadata: Any = None,
        data_visualization_anchor_lines: list[str] | None = None,
        visual_intent: Any = "",
        visual_plan: dict[str, Any] | None = None,
        visual_identity: Any = None,
        reference_assets: Any = None,
        asset_catalog: Any = None,
        scene_graph: GenerationSceneGraph | None = None,
        legal_footer_text: Any = "",
        disclaimer_guidance: Any = "",
        layout_budget: dict[str, Any] | None = None,
    ) -> str:
        payload = text_payload
        meta = metadata if isinstance(metadata, dict) else {}
        blueprint = sample_page_blueprint if isinstance(sample_page_blueprint, dict) else (
            meta.get("sample_page_blueprint") if isinstance(meta.get("sample_page_blueprint"), dict) else {}
        )
        structured = structured_visual_metadata if isinstance(structured_visual_metadata, dict) else {}
        visual_plan = visual_plan if isinstance(visual_plan, dict) else {}
        budget = layout_budget if isinstance(layout_budget, dict) else {}
        permissions = cls._sample_visual_permissions(blueprint)
        counts = blueprint.get("module_counts") if isinstance(blueprint.get("module_counts"), dict) else {}

        studio_panel = getattr(request, "studio_panel", {}) if request is not None else {}
        studio_panel = studio_panel if isinstance(studio_panel, dict) else {}
        size = studio_panel.get("size") if isinstance(studio_panel.get("size"), dict) else {}
        canvas = getattr(scene_graph, "canvas", None)
        width = int(
            getattr(canvas, "width", None)
            or size.get("width")
            or 0
        )
        height = int(
            getattr(canvas, "height", None)
            or size.get("height")
            or 0
        )
        aspect_ratio = round(width / height, 3) if width and height else 0
        aspect_label = (
            "landscape"
            if aspect_ratio > 1.15
            else "portrait"
            if aspect_ratio and aspect_ratio < 0.95
            else "square"
            if aspect_ratio
            else "unknown"
        )
        canvas_summary = f"{width}x{height} {aspect_label}" if width and height else f"{aspect_label} canvas"

        prompt_text = getattr(request, "prompt", "") if request is not None else ""
        legal_footer = cls._normalize_metadata_text(legal_footer_text, limit=420)
        disclaimer = cls._normalize_metadata_text(disclaimer_guidance, limit=180)
        brief = getattr(request, "research_editorial_brief", {}) if request is not None else {}
        brief = brief if isinstance(brief, dict) else {}
        footer_requested = bool(
            legal_footer
            or disclaimer
            or brief.get("disclaimer_requested")
            or ("disclaimer" in str(prompt_text or "").casefold())
        )
        def count_int(key: str) -> int:
            try:
                return int(counts.get(key) or 0)
            except (TypeError, ValueError):
                return 0

        footer_band_count = count_int("footer_band_count")
        footer_requested = bool(footer_requested or footer_band_count > 0)
        footer_source = (
            "sample_page_blueprint footer_band_count"
            if footer_band_count > 0
            else "legal/disclaimer metadata"
            if footer_requested
            else "none"
        )
        footer_policy = (
            f"reserve footer/disclaimer safe area before content and CTA using {footer_source}; "
            "leave exact bottom strip completely blank: no text/icons/objects/charts/cards/shadows/patterns/details"
            if footer_requested
            else "no footer/disclaimer safe area requested"
        )

        cta_text = cls._normalize_metadata_text(
            getattr(payload, "cta", "") if payload is not None else meta.get("cta"),
            limit=90,
        )
        zones: list[Any] = []
        for key in ("zones", "image_zones", "content_zones"):
            value = blueprint.get(key)
            if isinstance(value, list):
                zones.extend(value)
        has_cta_slot = count_int("cta_count") > 0 or any(
            isinstance(zone, dict)
            and "cta" in " ".join(
                cls._normalize_metadata_text(zone.get(key), limit=60)
                for key in ("role", "name", "label", "zone_role")
            ).casefold()
            for zone in zones
        )
        cta_allowed = permissions.get("cta_allowed", True) is not False
        if cta_text and not cta_allowed:
            cta_policy = "no approved CTA slot: omit CTA shell or downgrade to a quiet approved content module outside footer/disclaimer"
        elif cta_text and footer_requested:
            cta_policy = "CTA may render only in a CTA-safe slot above the reserved footer/disclaimer safe area; omit if no such slot exists"
        elif cta_text and blueprint and not has_cta_slot:
            cta_policy = "CTA has no explicit blueprint slot; render only if the active layout already reserves a CTA-safe zone"
        elif cta_text:
            cta_policy = "CTA must stay inside an approved CTA-safe slot"
        else:
            cta_policy = "no CTA requested; do not invent CTA button"

        raw_item_lines: list[str] = []
        for key, item_limit in (
            ("proof_points", 10),
            ("body_points", 10),
            ("stat_highlights", 10),
        ):
            raw_item_lines.extend(cls._normalize_metadata_list(meta.get(key), limit=item_limit))
        raw_item_lines.extend(
            cls._claim_evidence_pair_lines(
                cls._normalize_claim_evidence_pairs(meta.get("claim_evidence_pairs"), limit=4),
                limit=4,
            )
        )
        normalized_raw_items = [
            cls._normalize_metadata_text(item, limit=180)
            for item in raw_item_lines
            if cls._normalize_metadata_text(item, limit=180)
        ]
        deduped_items = cls._dedupe_metadata_collection(
            normalized_raw_items,
            blocked_texts=[
                getattr(payload, "headline", "") if payload is not None else "",
                meta.get("supporting_line"),
                getattr(payload, "body", "") if payload is not None else "",
                cta_text,
            ],
            limit=12,
        )
        duplicate_count = max(0, len(normalized_raw_items) - len(deduped_items))

        capacity_candidates: list[tuple[str, int]] = []
        for key in ("horizontal_band_count", "card_like_count", "small_icon_like_count", "text_block_count"):
            try:
                count_value = int(counts.get(key) or 0)
            except (TypeError, ValueError):
                count_value = 0
            if count_value > 0:
                capacity_candidates.append((key, count_value))
        if capacity_candidates:
            capacity_key, capacity_value = capacity_candidates[0]
            visible_capacity = max(1, min(capacity_value, 8))
            capacity_source = f"sample_page_blueprint module_counts.{capacity_key}"
        else:
            visible_capacity = max(1, min(len(deduped_items) or 1, 8))
            capacity_source = "deduped approved item count and active layout density"
        visible_items = deduped_items[:visible_capacity]
        overflow_count = max(0, len(deduped_items) - len(visible_items))
        item_policy = (
            f"visible item capacity={visible_capacity} derived from {capacity_source}; "
            f"render only {len(visible_items)} deduped approved item(s); overflow={overflow_count}; "
            "never render hidden, clipped, or partially visible rows; summarize overflow or carry it to the next slide when supported"
        )
        dedupe_policy = (
            f"dedupe removed {duplicate_count} repeated content item(s); preserve first occurrence order"
            if duplicate_count
            else "dedupe checked approved list/card items; no repeated visible rows"
        )

        headline = cls._normalize_metadata_text(getattr(payload, "headline", "") if payload is not None else "", limit=220)
        body = cls._normalize_metadata_text(getattr(payload, "body", "") if payload is not None else "", limit=360)
        supporting = cls._normalize_metadata_text(meta.get("supporting_line"), limit=220)
        text_pressure = len(headline.split()) + len(body.split()) + len(supporting.split()) + (len(deduped_items) * 8)
        if cta_text:
            text_pressure += 6
        if footer_requested:
            text_pressure += 10
        density_label = (
            "high"
            if text_pressure > 70 or overflow_count > 0
            else "medium"
            if text_pressure > 42 or len(deduped_items) > visible_capacity
            else "low"
        )
        density_policy = (
            f"text density={density_label}; if density is medium/high, compress copy surfaces, prioritize strongest approved points, and reduce visual complexity before rendering"
        )
        brand_header_policy = ""
        if budget:
            canvas_summary = cls._normalize_metadata_text(budget.get("canvas_summary"), limit=80) or canvas_summary
            footer_policy = cls._normalize_metadata_text(budget.get("footer_policy"), limit=720) or footer_policy
            cta_policy = cls._normalize_metadata_text(budget.get("cta_policy"), limit=220) or cta_policy
            visible_capacity = int(budget.get("visible_capacity") or visible_capacity)
            visible_items = list(budget.get("visible_items") or [])
            overflow_count = int(budget.get("overflow_count") or 0)
            capacity_source = cls._normalize_metadata_text(budget.get("capacity_source"), limit=180) or capacity_source
            duplicate_count = int(budget.get("duplicate_count") or 0)
            density_policy = cls._normalize_metadata_text(budget.get("density_policy"), limit=220) or density_policy
            brand_header_policy = cls._normalize_metadata_text(budget.get("brand_header_policy"), limit=520)
            item_policy = (
                f"visible item capacity={visible_capacity} derived from {capacity_source}; "
                f"render only {len(visible_items)} deduped approved item(s); overflow={overflow_count}; "
                "never render hidden, clipped, or partially visible rows; summarize overflow or carry it to the next slide when supported"
            )
            dedupe_policy = (
                f"dedupe removed {duplicate_count} repeated content item(s); preserve first occurrence order"
                if duplicate_count
                else "dedupe checked approved list/card items; no repeated visible rows"
            )

        table_intent = structured.get("table_intent") if isinstance(structured.get("table_intent"), dict) else {}
        chart_intent = structured.get("chart_intent") if isinstance(structured.get("chart_intent"), dict) else {}
        strict_anchors = structured.get("data_anchors") if isinstance(structured.get("data_anchors"), list) else []
        data_requested = bool(table_intent.get("requested") or chart_intent.get("requested"))
        data_allowed = bool(table_intent.get("allowed") or chart_intent.get("allowed"))
        data_lines = data_visualization_anchor_lines if isinstance(data_visualization_anchor_lines, list) else []
        if data_requested and data_allowed and strict_anchors:
            data_policy = f"data visual gate=allowed only from {len(strict_anchors)} strict approved anchor(s); no extra axes, values, percentages, or dashboard furniture"
        elif data_requested or data_lines:
            data_policy = "data visual gate=blocked for chart-like visuals unless strict approved data_anchors allow them; broad layout/body context cannot unlock charts"
        else:
            data_policy = "data visual gate=no chart/table/dashboard grammar requested"

        combined_symbol_text = " ".join(
            part
            for part in [
                prompt_text,
                cls._coerce_text_value(visual_intent),
                headline,
                body,
                supporting,
            ]
            if cls._coerce_text_value(part).strip()
        ).casefold()
        official_symbol_requested = bool(
            re.search(
                r"\b(official|regulated|government|national|flag|seal|emblem|crest|wordmark|brand mark|logo)\b",
                combined_symbol_text,
            )
        )

        def asset_mentions_symbol(asset: Any) -> bool:
            if not isinstance(asset, dict):
                return False
            fields = [
                asset.get("asset_role"),
                asset.get("name"),
                asset.get("label"),
                asset.get("asset_kind"),
                asset.get("type"),
                asset.get("description"),
                " ".join(str(tag) for tag in asset.get("tags", [])[:6]) if isinstance(asset.get("tags"), list) else "",
            ]
            text = " ".join(cls._normalize_metadata_text(item, limit=90) for item in fields).casefold()
            return bool(re.search(r"\b(flag|seal|emblem|crest|logo|wordmark|brand mark|official)\b", text))

        reference_items = reference_assets if isinstance(reference_assets, list) else []
        catalog_items = asset_catalog if isinstance(asset_catalog, list) else []
        visual_assets = visual_identity.get("reusable_design_assets") if isinstance(visual_identity, dict) else []
        visual_assets = visual_assets if isinstance(visual_assets, list) else []
        approved_symbol_asset = any(asset_mentions_symbol(asset) for asset in [*reference_items, *catalog_items, *visual_assets])
        if official_symbol_requested and approved_symbol_asset:
            official_symbol_policy = "official symbol policy=use only approved uploaded/reference/vector asset evidence; do not freehand exact marks"
        elif official_symbol_requested:
            official_symbol_policy = "official symbol policy=no approved official-symbol asset available; use abstract geographic, institutional, or partnership cues instead of recreating exact flags/logos/marks"
        else:
            official_symbol_policy = "official symbol policy=no exact official mark required"

        plan_mode = cls._normalize_metadata_text(visual_plan.get("mode"), limit=40)
        layout_priority = (
            "layout priority=sample_page_blueprint, visual_permissions, footer/disclaimer safe area, CTA slot, and data-anchor correctness outrank dynamic visual art direction"
            if blueprint
            else "layout priority=active layout slots, footer/disclaimer safe area, CTA slot, and data-anchor correctness outrank dynamic visual art direction"
        )
        return (
            "Layout quality guard: "
            f"canvas={canvas_summary}; format={cls._normalize_metadata_text(format_name, limit=40) or 'unknown'}; "
            f"purpose={plan_mode or 'current slide/page'}; "
            f"{brand_header_policy + '; ' if brand_header_policy else ''}"
            f"safe areas={footer_policy}; "
            f"CTA policy={cta_policy}; "
            f"content budget={item_policy}; "
            f"text density guard={density_policy}; "
            f"duplicate guard={dedupe_policy}; "
            f"{data_policy}; "
            f"{official_symbol_policy}; "
            f"{layout_priority}."
        )

    @classmethod
    def _content_format_guide_prompt_section(
        cls,
        request: AIOrchestrationRequest,
    ) -> str:
        guide = request.content_format_guide if isinstance(request.content_format_guide, dict) else {}
        if not guide:
            return ""
        summary = cls._normalize_metadata_text(guide.get("summary"), limit=220)
        rules = guide.get("rules") if isinstance(guide.get("rules"), dict) else {}
        format_name = str(request.studio_panel.get("format") or "").strip().lower()
        platform = str(request.studio_panel.get("platform_preset") or "").strip().lower()
        global_rules = guide.get("global_rules") if isinstance(guide.get("global_rules"), list) else []
        selected_rules = cls._normalize_metadata_list(
            [
                *(rules.get(format_name) or []),
                *(rules.get(platform) or []),
                *global_rules,
            ],
            limit=5,
        )
        if not summary and not selected_rules:
            return ""
        return " ".join(
            part
            for part in (
                f"Content format guide summary: {summary}." if summary else "",
                f"Content format guide rules: {'; '.join(selected_rules)}." if selected_rules else "",
            )
            if part
        )

    @classmethod
    def _live_research_verified_facts_prompt_section(
        cls,
        request: AIOrchestrationRequest,
    ) -> str:
        research = request.live_research if isinstance(request.live_research, dict) else {}
        fact_model = research.get("fact_model") if isinstance(research.get("fact_model"), dict) else research
        raw_fact_limit = cls._int_or_none(
            research.get("verified_fact_limit")
            or research.get("fact_limit")
            or fact_model.get("verified_fact_limit")
            or fact_model.get("fact_limit")
        ) or 6
        data_surface_contract = cls._data_list_surface_contract(
            prompt=request.prompt,
            format_name=str(request.studio_panel.get("format") or ""),
            metadata={},
        )
        if isinstance(data_surface_contract, dict):
            raw_fact_limit = max(raw_fact_limit, int(data_surface_contract.get("module_count") or 0))
        fact_limit = max(1, min(raw_fact_limit, 10))
        facts: list[str] = []
        for fact in (fact_model.get("verified_facts") or [])[:fact_limit]:
            if not isinstance(fact, dict):
                continue
            label = cls._normalize_metadata_text(fact.get("label") or fact.get("title"), limit=90)
            value = cls._normalize_metadata_text(fact.get("value") or fact.get("detail"), limit=120)
            source = cls._normalize_metadata_text(fact.get("source_title") or fact.get("source"), limit=80)
            parts = [part for part in (label, value, source) if part]
            if parts:
                facts.append(" - ".join(parts))
        if not facts:
            return ""
        return "Use these externally verified facts exactly; do not invent adjacent values, rankings, dates, or claims: " + "; ".join(facts) + "."

    @staticmethod
    def _strip_blocked_compliance_phrases(value: str) -> str:
        text = str(value or "")
        text = re.sub(r"\bSEBI[-\s]*(?:regulated|licensed|registered|aware)?\b", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\bregulated\b", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\b(?:guaranteed|assured|risk[-\s]*free)\b", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\bwith confidence\b", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\btransparent\s+platform\b", "", text, flags=re.IGNORECASE)
        text = re.sub(r"#SEBI\w*", "", text, flags=re.IGNORECASE)
        text = re.sub(r"\s{2,}", " ", text)
        text = re.sub(r"\s+([,.;:])", r"\1", text)
        return text.strip()

    @staticmethod
    def _scrub_image_prompt_brand_mark_triggers(value: str, replacement: str = "empty space") -> str:
        text = str(value or "")
        safe_replacement = replacement.strip() or "empty space"
        substitutions = (
            (r"\bcorner[_-]safe[_-]zone[a-z0-9_]*\b", safe_replacement),
            (r"\bcorner[_\s-]*safe[_\s-]*zone(?:s)?\b", safe_replacement),
            (r"\blogo[_\s-]*safe\b", safe_replacement),
            (r"\blogo[_\s-]*(?:like|style|shaped)\b", safe_replacement),
            (r"(?<![a-zA-Z])logos?(?![a-zA-Z])", safe_replacement),
            (r"\bwatermarks?\b", "stray text"),
            (r"\bwatermarked\b", "marked"),
            (r"\bwordmarks?\b", "stray text"),
            (r"\bbrand[_\s-]*marks?\b", "standalone graphics"),
            (r"\bbrandmarks?\b", "standalone graphics"),
            (r"\bbrand[-\s]*name signatures?\b", "brand-name text"),
            (r"\bmonograms?\b", "letter symbols"),
            (r"\bemblems?\b", "symbols"),
            (r"\blockups?\b", "symbol groups"),
        )
        for pattern, substitute in substitutions:
            text = re.sub(pattern, substitute, text, flags=re.IGNORECASE)
        text = re.sub(
            r"legal copy, and empty space after image generation",
            "legal copy, and logo after image generation",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"must contain zero standalone graphics, stray text, brand-name text",
            "must contain zero logos, wordmarks, brand-name signatures",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"The exact stored standalone graphics is composited afterward as a separate asset",
            "The exact stored brand logo is composited afterward as a separate asset",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"Never write or paint ([^.]+?) in the corner-safe area",
            r"Never write or paint \1 in the logo-safe corner",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"never as a standalone graphics, masthead, signature, stray text, standalone standalone graphics, or top-corner stray text",
            "never as a logo, masthead, signature, watermark, standalone brand mark, or top-corner wordmark",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"no ghosted stray text",
            "no ghosted wordmark",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(r"SAMPLE empty space EXCEPTION", "SAMPLE LOGO EXCEPTION", text, flags=re.IGNORECASE)
        text = re.sub(
            r"copy only the empty empty space zone geometry",
            "copy only the empty logo-safe zone geometry",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"Do not copy the sample page's empty space artwork",
            "Do not copy the sample page's logo artwork",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"literal text, empty space, or exact original artwork",
            "literal text, logo, or exact original artwork",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"derived from the (?:empty|reserved) space",
            "derived from the logo",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r"stretching under the (?:empty|reserved) space",
            "stretching under the logo",
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(
            r'"(?:empty|reserved) space_header_policy"',
            '"logo_header_policy"',
            text,
            flags=re.IGNORECASE,
        )
        text = re.sub(r"\s{2,}", " ", text)
        text = re.sub(r"\s+([,.;:])", r"\1", text)
        return text.strip()

    @staticmethod
    def _visual_explanation_guidance(visual_plan: dict[str, Any] | None) -> str:
        plan = visual_plan if isinstance(visual_plan, dict) else {}
        mode = str(plan.get("mode") or "minimal_brand_scene").strip().lower()
        need = str(plan.get("need") or "low").strip().lower()
        density = str(plan.get("density") or "low").strip().lower()
        rationale = AIOrchestratorService._normalize_metadata_text(plan.get("rationale"), limit=180)
        guidance_by_mode = {
            "beginner_path": (
                "Use a beginner-friendly path, guided entry, simplified market steps, bond ladder, or confusion-to-clarity progression. "
                "Do not rely on a person holding a coin as the only visual idea."
            ),
            "process_steps": (
                "Use a simple sequence, pathway, checklist flow, or step markers that make the recommended actions understandable at a glance."
            ),
            "comparison": (
                "Use clear contrast zones, side-by-side comparison, or a visual transformation tied to the actual topic. "
                "Do not default to rising bar charts, stock arrows, generic finance dashboards, or a chart/graph-style hero image unless the copy explicitly contains quantitative chart data."
            ),
            "data_cue": (
                "Prefer tables, labeled figures, comparison blocks, ladders, or process markers before defaulting to charts. "
                "Use chart or graph motifs only when the copy includes explicit numeric series, time-based trends, or metric comparisons that truly need charting. "
                "Otherwise do not let a chart, bars, or arrow become the main hero image."
            ),
            "sample_page_adaptation": (
                "Use the selected sample page as the primary visual explanation system. "
                "Match its visible layout category, object count, image/copy balance, module rhythm, and whitespace before adding any chart, dashboard, icon set, or finance metaphor. "
                "Numeric facts may become callouts only when the sample page uses callouts; do not convert them into charts unless the user explicitly asked for charts."
            ),
            "icon_support": (
                "Use a few premium integrated icons, diagram cues, or proof-point symbols only where they clarify the message; keep them secondary. "
                "Do not fall back to stock upward arrows, rising bars, generic finance app tiles, repeated chart stickers, or a graph-like hero image."
            ),
            "minimal_brand_scene": (
                "Keep visual explanation low. Do not force charts, dashboards, random icons, diagrams, or faux UI when the message works as a clean brand scene."
            ),
        }
        mode_guidance = guidance_by_mode.get(mode, guidance_by_mode["minimal_brand_scene"])
        return (
            f"Visual explanation plan: mode={mode}, need={need}, density={density}. "
            f"Rationale: {rationale}. {mode_guidance} "
            "Reference/template fit: if the reference is image-led, place the explanatory visual in the same image-emphasis region; "
            "if it is type-led or minimal, keep explanation subtle and lower density. "
            "Never let reference creatives force generic people imagery when this mode calls for an explainer."
        )

    def normalize_creative_decision_payload(
        self,
        raw: Any,
        fallback: dict[str, Any],
        *,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any],
    ) -> CreativeDecisionPayload:
        payload = dict(fallback or {})
        if isinstance(raw, dict):
            payload.update(raw)
        payload["layout_mode"] = str(
            payload.get("layout_mode")
            or payload.get("mode")
            or fallback.get("layout_mode")
            or "synthesized_layout"
        )
        if payload["layout_mode"] not in {"exact_template", "adapted_template", "synthesized_layout"}:
            payload["layout_mode"] = "synthesized_layout"
        payload["selected_template_id"] = self._resolve_template_candidate_identifier(
            str(payload.get("selected_template_id") or payload.get("template_id") or "").strip() or None,
            template_name=(
                str(payload.get("template_name") or "").strip()
                or str((payload.get("planning_hints") or {}).get("template_name") or "").strip()
                or str((fallback.get("planning_hints") or {}).get("template_name") or "").strip()
                or None
            ),
            template_candidates=[
                item
                for item in self._coerce_list(payload.get("template_candidates") or request.template_candidates or [])
                if isinstance(item, dict)
            ],
        )
        try:
            payload["confidence"] = max(0.0, min(float(payload.get("confidence", 0.0)), 1.0))
        except (TypeError, ValueError):
            payload["confidence"] = float(fallback.get("confidence") or 0.0)
        payload["reasoning"] = [
            str(item).strip()
            for item in self._coerce_list(payload.get("reasoning") or payload.get("rationale") or fallback.get("reasoning") or [])
            if str(item).strip()
        ]
        payload["adaptations"] = self._coerce_mapping(payload.get("adaptations") or payload.get("adaptation_plan"))
        asset_strategy = self._coerce_mapping(payload.get("asset_strategy") or fallback.get("asset_strategy"))
        for key in ("use_generated_image", "use_template_background", "use_brand_reference_assets", "logo_injection_required"):
            if key in asset_strategy:
                asset_strategy[key] = bool(asset_strategy.get(key))
        if asset_strategy.get("logo"):
            asset_strategy.setdefault("logo_injection_required", True)
        inferred_surface_policy = self._effective_template_surface_policy(
            request,
            creative_decision=None,
            metadata={"asset_strategy": asset_strategy},
        )
        if inferred_surface_policy and not asset_strategy.get("template_surface_policy"):
            asset_strategy["template_surface_policy"] = inferred_surface_policy
        if asset_strategy.get("template_surface_policy") == "style_reference_only":
            asset_strategy["use_template_background"] = False
        major_flags = self._major_asset_strategy_flags(asset_strategy)
        dominant = self._normalized_dominant_visual_system(asset_strategy)
        supporting = self._normalized_supporting_visual_system(asset_strategy)
        if not dominant:
            dominant = next((name for name, enabled in major_flags.items() if enabled), "generated_image")
        asset_strategy["dominant_visual_system"] = dominant
        if supporting:
            asset_strategy["supporting_visual_system"] = supporting
        if dominant == "generated_image":
            asset_strategy["use_generated_image"] = True
            if payload["layout_mode"] == "synthesized_layout" or asset_strategy.get("template_surface_policy") == "style_reference_only":
                asset_strategy["use_template_background"] = False
            if supporting != "reference_assets":
                asset_strategy["use_brand_reference_assets"] = False
            if supporting == "icon_sequence":
                asset_strategy["icon_sequence"] = True
                asset_strategy["use_brand_reference_assets"] = True
        elif dominant == "template_background":
            asset_strategy["use_template_background"] = payload["layout_mode"] in {"exact_template", "adapted_template"}
            asset_strategy["use_generated_image"] = False
            if asset_strategy.get("template_surface_policy") == "style_reference_only":
                asset_strategy["use_template_background"] = False
        elif dominant == "reference_assets":
            asset_strategy["use_brand_reference_assets"] = True
            asset_strategy["use_template_background"] = False
            asset_strategy["use_generated_image"] = False
        elif dominant == "icon_sequence":
            asset_strategy["icon_sequence"] = True
        if supporting == "icon_sequence":
            asset_strategy["icon_sequence"] = True
            if dominant in {"generated_image", "type_led"}:
                asset_strategy["use_brand_reference_assets"] = True
        payload["asset_strategy"] = asset_strategy
        payload["template_candidates"] = [
            item
            for item in self._coerce_list(payload.get("template_candidates") or request.template_candidates or [])
            if isinstance(item, dict)
        ]
        payload["planning_hints"] = {
            **self._coerce_mapping(fallback.get("planning_hints")),
            **self._coerce_mapping(payload.get("planning_hints")),
            "backend_compiled_template_fit": compiled_context.get("template_fit_brief", {}),
        }
        normalized = CreativeDecisionPayload.model_validate(payload)
        sequence_pack = self._template_sequence_pack(request, creative_decision=normalized)
        if isinstance(sequence_pack, dict):
            sequence_surface_policy = str(sequence_pack.get("surface_policy") or "").strip().lower()
            if sequence_surface_policy == "style_reference_only":
                normalized_payload = normalized.model_dump(mode="json")
                normalized_asset_strategy = self._coerce_mapping(normalized_payload.get("asset_strategy"))
                normalized_asset_strategy["template_surface_policy"] = "style_reference_only"
                normalized_asset_strategy["use_template_background"] = False
                normalized_asset_strategy["use_brand_reference_assets"] = True
                dominant_visual_system = self._normalized_dominant_visual_system(normalized_asset_strategy)
                if dominant_visual_system in {"", "template_background"}:
                    normalized_asset_strategy["dominant_visual_system"] = "generated_image"
                    normalized_asset_strategy["use_generated_image"] = True
                if normalized_payload.get("layout_mode") == "exact_template":
                    normalized_payload["layout_mode"] = "adapted_template"
                normalized_payload["asset_strategy"] = normalized_asset_strategy
                normalized_payload["reasoning"] = [
                    *[
                        str(item).strip()
                        for item in self._coerce_list(normalized_payload.get("reasoning") or [])
                        if str(item).strip()
                    ],
                    "Use the ordered reference sequence as story and slide guidance only; do not reuse the sample surface as the literal background.",
                ]
                normalized = CreativeDecisionPayload.model_validate(normalized_payload)
        if self._should_force_sequence_pack(request, creative_decision=normalized):
            normalized_payload = normalized.model_dump(mode="json")
            if normalized.layout_mode == "synthesized_layout":
                normalized_payload["layout_mode"] = "adapted_template"
            normalized_asset_strategy = self._coerce_mapping(normalized_payload.get("asset_strategy"))
            normalized_asset_strategy["use_template_background"] = True
            normalized_asset_strategy["use_brand_reference_assets"] = True
            normalized_asset_strategy["use_generated_image"] = False
            normalized_asset_strategy["template_surface_policy"] = "sequence_pack_locked"
            normalized_asset_strategy.setdefault("dominant_visual_system", "template_background")
            normalized_payload["asset_strategy"] = normalized_asset_strategy
            normalized_payload["reasoning"] = [
                *[
                    str(item).strip()
                    for item in self._coerce_list(normalized_payload.get("reasoning") or [])
                    if str(item).strip()
                ],
                "Forced to ordered reference sequence pack because a locked multi-slide template pack is available for this carousel.",
            ]
            normalized = CreativeDecisionPayload.model_validate(normalized_payload)
        return normalized

    def normalize_message_strategy_payload(
        self,
        raw: Any,
        fallback: dict[str, Any],
    ) -> MessageStrategyPayload:
        payload = dict(fallback or {})
        if isinstance(raw, dict):
            payload.update(raw)
        aliases = {
            "primary_campaign_theme": ["primary_campaign_theme", "Primary Campaign Theme"],
            "core_audience_message": ["core_audience_message", "Core Audience Message"],
            "headline_direction": ["headline_direction", "Headline Direction"],
            "supporting_copy_direction": ["supporting_copy_direction", "Supporting Copy Direction"],
            "cta_intent": ["cta_intent", "CTA Intent"],
            "key_value_proposition": ["key_value_proposition", "Key Value Proposition"],
            "important_keywords": ["important_keywords", "Important Keywords/Phrases", "keywords"],
            "emotional_messaging_direction": ["emotional_messaging_direction", "Emotional Messaging Direction"],
            "what_must_be_avoided_in_messaging": [
                "what_must_be_avoided_in_messaging",
                "What Must Be Avoided In Messaging",
                "avoid_messaging",
            ],
        }
        normalized: dict[str, Any] = {}
        for target, keys in aliases.items():
            value = None
            fallback_candidate = None
            for key in keys:
                candidate = payload.get(key) if key in payload else None
                if candidate is None or candidate == "":
                    continue
                if target in {"important_keywords", "what_must_be_avoided_in_messaging"}:
                    candidate_items = self._normalize_metadata_list(candidate, limit=8)
                    if candidate_items and any(item.strip().upper() != "MISSING" for item in candidate_items):
                        value = candidate_items
                        break
                    fallback_candidate = candidate_items
                    continue
                if str(candidate).strip() and str(candidate).strip().upper() != "MISSING":
                    value = candidate
                    break
                fallback_candidate = candidate
            if value is None:
                value = fallback_candidate
            if target in {"important_keywords", "what_must_be_avoided_in_messaging"}:
                normalized[target] = self._normalize_metadata_list(value, limit=8)
            else:
                text = self._coerce_text_value(value).strip()
                normalized[target] = text or self._coerce_text_value(fallback.get(target) or "MISSING")
        if not normalized["important_keywords"]:
            normalized["important_keywords"] = self._normalize_metadata_list(fallback.get("important_keywords"), limit=8) or ["MISSING"]
        if not normalized["what_must_be_avoided_in_messaging"]:
            normalized["what_must_be_avoided_in_messaging"] = (
                self._normalize_metadata_list(fallback.get("what_must_be_avoided_in_messaging"), limit=8) or ["MISSING"]
            )
        return MessageStrategyPayload.model_validate(normalized)

    @classmethod
    def _should_use_image_led_social(
        cls,
        request: AIOrchestrationRequest,
        compiled_context: dict[str, Any],
    ) -> bool:
        ai_final_render_required = cls._request_requires_ai_final_render(request)
        if not cls._image_generation_requested(request) and not ai_final_render_required:
            return False
        platform = str(request.studio_panel.get("platform_preset") or "").strip().lower()
        format_name = str(request.studio_panel.get("format") or "").strip().lower()
        if platform not in {"instagram", "linkedin", "x", "youtube_thumbnail"}:
            return False
        if format_name not in cls.AI_FINAL_RENDER_FORMATS:
            return False
        if cls._should_force_sequence_pack(request) and not ai_final_render_required:
            return False
        planning_hints = request.layout_decision or {}
        mode = str(planning_hints.get("mode") or "").strip().lower()
        review_flags = {
            str(flag).strip().lower()
            for flag in cls._coerce_list(planning_hints.get("review_flags") or [])
            if str(flag).strip()
        }
        template_surface_policy = cls._effective_template_surface_policy(
            request,
            metadata=planning_hints if isinstance(planning_hints, dict) else {},
        )
        template_fit_brief = compiled_context.get("template_fit_brief", {}) or {}
        template_confidence = 0.0
        try:
            template_confidence = float(template_fit_brief.get("confidence") or 0.0)
        except (TypeError, ValueError):
            template_confidence = 0.0
        if format_name in cls.TEMPLATE_LOCKED_IMAGE_LED_FORMATS and not ai_final_render_required:
            if mode == "exact_template" and not review_flags and template_surface_policy != "style_reference_only":
                return False
            if template_confidence >= 0.9 and mode == "exact_template" and template_surface_policy != "style_reference_only":
                return False
        return True

    @staticmethod
    def _image_generation_size(studio_panel: dict[str, Any]) -> str:
        size = studio_panel.get("size") or {}
        width = int(size.get("width") or 1080)
        height = int(size.get("height") or 1080)
        if width >= height * 1.2:
            return "1536x1024"
        if height >= width * 1.2:
            return "1024x1536"
        return "1024x1024"

    @staticmethod
    def _canvas_fit_guidance(studio_panel: dict[str, Any]) -> str:
        size = studio_panel.get("size") or {}
        width = int(size.get("width") or 1080)
        height = int(size.get("height") or 1080)
        if width <= 0 or height <= 0:
            width, height = 1080, 1080
        orientation = "square"
        if width >= height * 1.15:
            orientation = "landscape"
        elif height >= width * 1.15:
            orientation = "portrait"
        return (
            f"Canvas fit: design for the requested {width}x{height} {orientation} output ratio. "
            "Keep every headline, body line, proof point, CTA, corner-safe area, and visual focal subject fully inside a centered target-aspect safe frame with at least 8% inner margin. "
            "Never place CTA buttons, bullets, faces, hands, or key objects on the outer edge; if text feels tight, reduce copy density and scale down the layout instead of letting anything run below or outside the canvas."
        )

    @classmethod
    def _generation_to_export_fit_guidance(cls, studio_panel: dict[str, Any]) -> str:
        target_width, target_height = cls._requested_canvas_dimensions(studio_panel)
        generation_size = cls._image_generation_size(studio_panel)
        try:
            generation_width, generation_height = [int(part) for part in generation_size.lower().split("x", 1)]
        except (TypeError, ValueError):
            generation_width, generation_height = target_width, target_height
        target_ratio = target_width / max(target_height, 1)
        generation_ratio = generation_width / max(generation_height, 1)
        aspect_delta = abs(generation_ratio - target_ratio) / max(target_ratio, 0.01)
        if aspect_delta < 0.06:
            return (
                f"Generation-to-export fit: model canvas {generation_size} closely matches the final {target_width}x{target_height} export. "
                "Keep all modules, visual anchors, and overlay-safe surfaces inside the requested canvas."
            )
        return (
            f"Generation-to-export fit: model canvas {generation_size} will be center-fitted into the final {target_width}x{target_height} export. "
            "Keep every important module, face, object, divider, card shell, and overlay-safe surface inside the central target-aspect safe frame; avoid critical detail near the model-canvas edges."
        )

    @classmethod
    def _should_use_ai_final_render(
        cls,
        request: AIOrchestrationRequest,
        generation_path: str,
        creative_decision: CreativeDecisionPayload,
    ) -> bool:
        if generation_path != "image_led_social":
            return False
        if cls._request_requires_ai_final_render(request) and cls._image_generation_requested(request):
            return True
        layout_mode = str(getattr(creative_decision, "layout_mode", "") or "").strip().lower()
        request_layout = request.layout_decision if isinstance(request.layout_decision, dict) else {}
        request_mode = str(request_layout.get("mode") or "").strip().lower()
        request_template_context = request.template_context if isinstance(request.template_context, dict) else {}
        request_sequence_pack = (
            request_template_context.get("sequence_pack")
            if isinstance(request_template_context.get("sequence_pack"), dict)
            else {}
        )
        template_surface_policy = cls._effective_template_surface_policy(
            request,
            creative_decision=creative_decision,
            metadata=request_layout,
        )
        if (
            cls._request_requires_ai_final_render(request)
            and (
                request_mode in {"adapted_template", "exact_template"}
                or str(request_sequence_pack.get("surface_policy") or "").strip().lower() == "style_reference_only"
            )
        ):
            return True
        if not cls._image_generation_requested(request):
            return False
        return cls._request_requires_ai_final_render(request)

    @classmethod
    def _image_generation_requested(cls, request: AIOrchestrationRequest) -> bool:
        if not bool(request.generate_image):
            format_name = str(request.studio_panel.get("format") or "").strip().lower()
            template_context = request.template_context if isinstance(request.template_context, dict) else {}
            sequence_pack = template_context.get("sequence_pack") if isinstance(template_context.get("sequence_pack"), dict) else {}
            surface_policy = str(sequence_pack.get("surface_policy") or "").strip().lower()
            if format_name == "carousel" and surface_policy == "style_reference_only":
                return True
            return False
        if cls._request_requires_ai_final_render(request):
            return True
        return bool(request.generate_image)

    @classmethod
    def _request_requires_ai_final_render(cls, request: AIOrchestrationRequest) -> bool:
        format_name = str(request.studio_panel.get("format") or "").strip().lower()
        file_type = str(request.studio_panel.get("file_type") or "").strip().lower()
        return format_name in cls.AI_FINAL_RENDER_FORMATS and file_type in {"png", "jpg", "pdf", "doc"}

    @staticmethod
    def _ai_final_render_failure_message() -> str:
        return "AI final render failed and backend fallback rendering is disabled for this format."

    @staticmethod
    def _resolve_logo_box(scene_graph: GenerationSceneGraph) -> tuple[float, float, float, float] | None:
        for element in scene_graph.elements:
            if not element.visible or element.role != "logo":
                continue
            geometry = element.geometry
            if (
                geometry.x is None
                or geometry.y is None
                or geometry.width is None
                or geometry.height is None
            ):
                continue
            return (
                float(geometry.x),
                float(geometry.y),
                float(geometry.width),
                float(geometry.height),
            )
        return None

    @classmethod
    def _build_logo_mask_bytes(
        cls,
        *,
        scene_graph: GenerationSceneGraph,
        width: int,
        height: int,
    ) -> bytes | None:
        box = cls._resolve_logo_box(scene_graph)
        if box is None:
            left, top, box_width, box_height = 0.76, 0.06, 0.18, 0.1
        else:
            left, top, box_width, box_height = box
        x0 = max(int(left * width), 0)
        y0 = max(int(top * height), 0)
        x1 = min(int((left + box_width) * width), width)
        y1 = min(int((top + box_height) * height), height)
        if x1 <= x0 or y1 <= y0:
            return None

        mask = Image.new("RGBA", (width, height), (0, 0, 0, 255))
        draw = ImageDraw.Draw(mask)
        draw.rounded_rectangle((x0, y0, x1, y1), radius=max(min(x1 - x0, y1 - y0) // 5, 8), fill=(0, 0, 0, 0))
        buffer = BytesIO()
        mask.save(buffer, format="PNG")
        return buffer.getvalue()

    def _apply_ai_logo_edit_pass(
        self,
        *,
        image_provider,
        tenant_id,
        brand_space_id,
        prompt: str,
        base_asset_payload: dict[str, Any],
        logo_storage_path: str | None,
        scene_graph: GenerationSceneGraph,
        size: str | None,
        trace_id: str | None,
        trace_label: str,
    ) -> tuple[dict[str, Any], bool]:
        if not logo_storage_path or not self.storage.exists(logo_storage_path):
            return base_asset_payload, False
        base_storage_path = str(base_asset_payload.get("storage_path") or "").strip()
        if not base_storage_path or not self.storage.exists(base_storage_path):
            return base_asset_payload, False
        width = int(base_asset_payload.get("width") or 0)
        height = int(base_asset_payload.get("height") or 0)
        if width <= 0 or height <= 0:
            return base_asset_payload, False
        mask_png_bytes = self._build_logo_mask_bytes(
            scene_graph=scene_graph,
            width=width,
            height=height,
        )
        if not mask_png_bytes:
            return base_asset_payload, False
        try:
            edited_asset = self._edit_image_with_retries(
                image_provider=image_provider,
                tenant_id=tenant_id,
                brand_space_id=brand_space_id,
                prompt=(
                    f"{prompt}\n\n"
                    "Use the exact provided brand logo in the reserved logo area only. "
                    "Preserve the composition, copy layout, and overall design. "
                    "Do not add extra text, icons, or substitute marks."
                ),
                image_paths=[
                    self.storage.absolute_path(base_storage_path),
                    self.storage.absolute_path(logo_storage_path),
                ],
                size=size,
                mask_png_bytes=mask_png_bytes,
                trace_id=trace_id,
                trace_label=trace_label,
            )
            return edited_asset, True
        except Exception as exc:  # pragma: no cover - resilience path
            self._trace_payload(
                trace_id,
                self.trace,
                f"{trace_label}_error",
                {
                    "error": str(exc),
                    "logo_storage_path": logo_storage_path,
                    "base_storage_path": base_storage_path,
                },
            )
            return base_asset_payload, False

